update content_bodies set title = 'はしとはしのはなし', description = 'この動画は、はしとはしのはなしについて紹介しています。はしの歴史や役割、さまざまな種類のはしについての情報が含まれており、視聴者にとって興味深い内容となっています。はしがどのように人々の生活に影響を与えているのか、またその重要性についても触れられています。' where id = 'mrnGIIJG22f_rbvJNxkWP';
