update content_bodies set title = 'NAME CAMP 60s', description = 'NAME CAMP 60sは、1960年代に焦点を当てたユニークなイベントで、その時代の文化、音楽、ライフスタイルを祝います。このイベントでは、参加者が60年代の精神に浸ることができるさまざまなアクティビティ、ワークショップ、パフォーマンスが行われます。参加者は、ライブ音楽やヴィンテージファッション、そしてこの変革の十年の重要性を強調するインタラクティブな体験を楽しむことができます。' where id = '7APqi77-v_da7vSAAj2pL';
update content_bodies set title = 'NAME CAMP 60s', description = 'NAME CAMP 60s is a unique event that focuses on the 1960s, celebrating the culture, music, and lifestyle of that era. The event features various activities, workshops, and performances that allow participants to immerse themselves in the spirit of the 60s. Attendees can expect to enjoy live music, vintage fashion, and interactive experiences that highlight the significance of this transformative decade.' where id = 'uuXgtcVVXv75bFBWjDgQA';
