update content_bodies set title = 'NAGI倉敷ホテル＆ラウンジ -ワーケーション-', description = 'NAGI倉敷ホテル＆ラウンジは、仕事と休暇を組み合わせた「ワーケーション」を提供するユニークな体験を提供しています。ホテルは、リモートワークに適した快適な環境を提供し、ゲストが倉敷の地元文化や観光名所を楽しむことができるようになっています。詳細はウェブサイトをご覧ください。' where id = 'wmCXN1FK_zCqgSzXg78yH';
update content_bodies set title = 'NAGI Kurashiki Hotel & Lounge -Worcation-', description = 'NAGI Kurashiki Hotel & Lounge offers a unique experience for those looking to combine work and vacation, known as ''worcation.'' The hotel provides a comfortable environment suitable for remote work while allowing guests to enjoy the local culture and attractions of Kurashiki. For more information, visit their website.' where id = 'N6yNb1Fzaogcuz-TjyvC0';
update content_bodies set title = 'SHINJI KASAI', description = 'これは、笠井真司の公式ウェブサイトです。彼の作品やプロジェクトに関する情報が提供されています。' where id = 'RvsFqEwQFFNnUxwJ9RYiR';
update content_bodies set title = 'SHINJI KASAI', description = 'This is the official website of Shinji Kasai. It provides information about his work and projects.' where id = 'n8JmyDHgdSLZjoYxP-tkH';
update content_bodies set title = '県南浜街道地域（名取市，岩沼市，亘理町，山元町）観光案内動画（台湾語版）', description = '宮城県仙台地方振興事務所は、東日本大震災で大きな被害を受けた県南浜街道地域（名取市、岩沼市、亘理町、山元町）に多くの観光客に訪れてもらいたいという思いから、各市町の魅力的な自然や観光施設、復興の様子を紹介する動画を制作しました。ドローンで撮影された迫力ある映像で、県南浜街道地域の魅力を発信していますので、ぜひご覧ください。' where id = 'u_Du7VbkrvG2sk72GB_Of';
update content_bodies set title = 'Tourism Promotion Video for the Ken-Nan Hama Kaido Region (Natori City, Iwanuma City, Watari Town, Yamamoto Town) - Taiwanese Version', description = 'The Miyagi Prefecture Sendai Regional Promotion Office has produced a video to encourage more tourists to visit the Ken-Nan Hama Kaido region, which suffered significant damage from the Great East Japan Earthquake. The video showcases the attractive nature, tourist facilities, and the recovery efforts of each city and town in the region. With impressive drone footage, it highlights the charm of the Ken-Nan Hama Kaido area, inviting viewers to watch.' where id = '1Ut3b1dTk59XFo0z-jvUO';
update content_bodies set title = 'THE ROOTS #01 殿様が搾る牛乳', description = '広島県東部の神石高原町で酪農を営む相馬行胤さん、通称「殿様」は、旧相馬中村藩の第34代目当主です。もともと北海道十勝地方で肉牛の牧場を経営し、福島県相馬市でシイタケを栽培していましたが、東日本大震災をきっかけに神石高原町へ移住しました。農業の未来を考え、命を愛おしむことや素材本来の味を守ること、土を痛めないことを重視したサスティナブルな牧場を運営しています。広い敷地で限られた数の牛を育て、牛にストレスをかけないために搾乳は早朝の1回のみ。土と牛と人間が共生するこの牧場で、殿様が搾る牛乳をぜひ味わってみてください。' where id = 'UuvYhdZNyL62xZSpd2tkF';
update content_bodies set title = 'THE ROOTS #01 The Lord''s Milk', description = 'In the eastern part of Hiroshima Prefecture, Michitane Soma, known as ''the Lord,'' runs a dairy farm in Jinseki Kogen Town. He is the 34th head of the former Soma Nakamura clan, making him a real lord. Originally, he managed a beef cattle ranch in Hokkaido''s Tokachi region and cultivated shiitake mushrooms in Fukushima. The 2011 Great East Japan Earthquake prompted him to move to Jinseki Kogen, leading to the closure of his business and departure from his hometown. Soma emphasizes the importance of cherishing life, preserving the natural flavors of ingredients, and sustainable farming practices. He raises a limited number of cows on a spacious farm to avoid stressing them, milking them only once a day in the early morning. This farm embodies the coexistence of soil, cows, and humans, producing milk that reflects Soma''s philosophy.' where id = 'zS_7UaFRa8VQeYeX63Tx-';
update content_bodies set title = '県南浜街道地域（名取市，岩沼市，亘理町，山元町）観光案内動画（英語版）', description = '宮城県仙台地方振興事務所は、東日本大震災で大きな被害を受けた県南浜街道地域（名取市、岩沼市、亘理町、山元町）に多くの観光客に訪れてもらうことを願い、各市町の魅力的な自然や観光施設、復興の様子を紹介する動画を制作しました。ドローンで撮影された迫力ある映像で、県南浜街道地域の魅力を発信していますので、ぜひご覧ください。' where id = 'htvKUQ-VdZA43uhhvLoKH';
update content_bodies set title = 'Tourism Promotion Video for the Ken-Nan Hama Kaido Region (Natori City, Iwanuma City, Watari Town, Yamamoto Town)', description = 'The Miyagi Prefectural Sendai Regional Promotion Office has produced a video to encourage more tourists to visit the Ken-Nan Hama Kaido region, which suffered significant damage from the Great East Japan Earthquake. The video showcases the attractive nature, tourist facilities, and the recovery efforts of each city and town in the area. With impressive drone footage, it highlights the charm of the Ken-Nan Hama Kaido region, inviting viewers to explore its beauty.' where id = 'Bbzve2t4Wm39sWE5ayMq7';
update content_bodies set title = 'ジオダイニング下北半島', description = '下北半島からの招待状が届いたら、特別な旅の準備を始めましょう。ここでしか体験できない、下北ジオダイニングというユニークな旅です。ジオガストロノミー・ツーリズムは、2019年のクールジャパンマッチングアワードで《特別賞》を受賞しました。' where id = 'WV2QbBSNdbr7-fYI7IgmB';
update content_bodies set title = 'Shimokita Geo-Dining', description = 'Shimokita invites you to prepare for a unique travel experience. This is a one-of-a-kind journey in the world, known as Shimokita GEO-DINING. The concept of geogastronomy tourism was honored with the ''Special Award'' at the Cool Japan Matching Award 2019.' where id = 'wveg0aGK8BujrrekQLKaJ';
update content_bodies set title = 'さあ、瀬戸内をめしあがれ。阿藻珍味', description = 'このウェブサイトは、瀬戸内地域の美味しい食材を紹介する阿藻珍味についての情報を提供しています。地域特有の味や食材に焦点を当て、地元の特産品や料理の魅力を伝えています。' where id = 'xwwyY_KiQITQ6HUm8pxVf';
update content_bodies set title = 'Enjoy the Setouchi Region: Amou Chinmi', description = 'The website provides information about Amou Chinmi, a brand that showcases the culinary delights of the Setouchi region. It highlights various local delicacies and offers insights into the unique flavors and ingredients that define this area.' where id = 'A1d9UUCiO6Gwsd2v6y8gq';
update content_bodies set title = 'おいしいってこんなにも楽しい。 阿藻珍味', description = 'このウェブサイトは、阿藻珍味というブランドの美味しい製品を楽しむことの喜びを紹介しています。美味しい食べ物を味わうことから得られる楽しさを強調しています。' where id = 'OnKPRK89z5Hs2ZR1JPnlY';
update content_bodies set title = 'Deliciousness is this much fun. Amou Chinmi', description = 'The website showcases the delightful experience of enjoying Amou Chinmi, a brand known for its tasty products. It emphasizes the joy that comes from savoring delicious food.' where id = 'WNzacGMYKgoznEkzx7n36';
update content_bodies set title = '嵐山京都 - 日本で最も美しい竹林 | 4K', description = '嵐山は世界中の旅行者を惹きつける京都の名所であり、特に美しい竹林が有名です。嵐山の最も風光明媚なスポットは、竹林を通る小さな散策路です。著者は、誰もいない早朝にこの美しい竹林を歩いた体験を語っています。' where id = 'ROLoFIpvRc3lLg_JKRIoG';
update content_bodies set title = 'Arashiyama Kyoto - The most beautiful bamboo forest in Japan | 4K', description = 'Arashiyama in Kyoto is a popular destination for travelers worldwide, renowned for its stunning bamboo forest. The most picturesque area is a small walking path that winds through the bamboo. The author describes their experience walking through this beautiful forest early in the morning when it was completely empty.' where id = 'HrV0ba4SP0ozhYbmLQusk';
update content_bodies set title = 'ともによろこぶ Celebrate Tomonoura Together  -Japanese-【鞆の浦】', description = '鞆の浦は地元で「鞆＝とも」と呼ばれ、自然との共生や家族・友人との支え合いを大切にしてきた人々の思いが込められています。本映像「時をともに」は、日本遺産に認定された鞆の浦の穏やかで優しい時間を体験する機会を提供します。第三章「ともによろこぶ」では、のどかな港町が一丸となって盛り上がる10の祭事や神事を紹介し、鞆の浦の日常に触れることができます。' where id = 'OzaDmGuzBjG7KXYXaiWnq';
update content_bodies set title = 'Celebrate Tomonoura Together -Japanese-【Tomonoura】', description = 'In Tomonoura, known locally as ''Tomo'', the name embodies the spirit of coexistence with nature and the support among family and friends. The video ''Together in Time'' invites viewers to experience the gentle and serene atmosphere of this Japanese Heritage site. Chapter three, ''Celebrate Together'', showcases ten festivals and rituals that unite this tranquil port town, allowing visitors to engage with the joyful daily life of Tomonoura.' where id = 'Jzyof3ozFbPLjXTUprVu2';
update content_bodies set title = 'NAMETOKO英語キャンプ', description = 'NAMETOKO英語キャンプは、1957年から2009年までの53年間にわたり開催されていました。このキャンプは、その理念に共鳴した有志や松野町、過去の参加者によって復活しました。子どもたちはこの2泊3日の中で、英語のスキルを学ぶだけでなく、自我を発見し、自己表現を学んでいきます。' where id = 'ABXzIrGduBPCyWlfZLmWf';
update content_bodies set title = 'NAMETOKO ENGLISH CAMP', description = 'The Nametoko English Camp was held for 53 years from 1957 to 2009. It has been revived by volunteers who resonate with its philosophy, along with Matsuno Town and past participants. During this 2-night, 3-day camp, children not only learn English skills but also discover their identity and learn self-expression.' where id = 'DNCjh_ccDuqgzBnujm-zu';
update content_bodies set title = '県南浜街道地域（名取市，岩沼市，亘理町，山元町）観光案内動画（日本語字幕版）', description = '宮城県仙台地方振興事務所は、東日本大震災で大きな被害を受けた県南浜街道地域（名取市、岩沼市、亘理町、山元町）に多くの観光客に訪れてもらいたいという思いから、各市町の魅力的な自然や観光施設、復興の様子を紹介する動画を制作しました。ドローンで撮影された迫力ある映像で、県南浜街道地域の魅力を発信していますので、ぜひご覧ください。' where id = 'bcTkS4_o_4Tve3Sa1UEdw';
update content_bodies set title = 'Tourist Information Video of the Ken-Nan Hama Kaido Region (Natori City, Iwanuma City, Watari Town, Yamamoto Town)', description = 'The Miyagi Prefecture Sendai Regional Promotion Office has produced a video to encourage more tourists to visit the Ken-Nan Hama Kaido region, which suffered significant damage from the Great East Japan Earthquake. The video showcases the attractive nature, tourist facilities, and the recovery efforts of each city and town in the area. With impressive drone footage, it highlights the charm of the Ken-Nan Hama Kaido region, inviting viewers to watch.' where id = 'xVc2iLE_sV_w98JocGNvS';
update content_bodies set title = '和歌山ワーケーションPR動画　個人編（95秒）', description = 'ワーケーションとは、リモートワークを活用し、リゾート地などの環境の良い場所で、休暇や研修を兼ねて短中期的に滞在し仕事を行う新しい働き方です。この動画では、首都圏で活躍するビジネスパーソンが和歌山でのワーケーションを体験する様子を紹介しています。交通の利便性が高く、リゾート環境が整った和歌山の魅力の一部をお伝えします。' where id = 'OQ2Z77ydCp4-h9QBTvFvl';
update content_bodies set title = 'Wakayama Workation PR Video - Individual Edition (95 seconds)', description = 'Workation is a new way of working that utilizes remote work, allowing individuals to stay in pleasant environments, such as resorts, for short to medium-term periods while combining work with vacation or training. This video showcases the experience of business professionals from the Tokyo metropolitan area as they engage in workation in Wakayama. It highlights some of the attractions of Wakayama, which boasts high transportation convenience and well-established resort environments.' where id = 'Gir8MzHUqM_h5noUp98ys';
update content_bodies set title = 'イタリアに行く前に覚えておいて！', description = 'この動画では、イタリアに行く前に知っておくべきことを紹介しています。旅行を計画している方にとって、役立つ情報が満載です。特に、イタリアの文化や習慣、観光地の選び方、食事のマナーなど、旅行をより楽しむためのポイントが解説されています。イタリアの魅力を最大限に引き出すために、事前に知識を身につけておくことが大切です。' where id = 'BHoZvsJb7_2QZczLKM0zU';
update content_bodies set title = 'Things to Remember Before Traveling to Italy!', description = 'This video introduces important things to keep in mind before traveling to Italy.' where id = 'iXj1KPSIFmaR7Q_m_tOah';
update content_bodies set title = '兵庫・尼崎の魅力旅：一度は訪れたい観光＆グルメ7選', description = 'この動画は、兵庫県尼崎市を訪れる旅行者に向けたガイドです。尼崎市のおすすめスポットとして、農業公園や記念館、公園、博物館、城、地元の飲食店など、7つの場所を紹介しています。視聴者には、他のおすすめスポットがあればコメント欄でシェアするよう促しています。チャンネル「旅行の達人」は、観光、移動、宿泊、食事に関する情報を提供し、旅行を通じて人生を豊かにすることを目指しています。旅行を通じて新しい可能性を発見することを奨励しています。' where id = 'Aq7093jQt2pO6kUiw6OEL';
update content_bodies set title = 'Attractions and Gourmet Spots in Amagasaki, Hyogo: 7 Must-Visit Places', description = 'This video serves as a guide for travelers interested in visiting Hyogo Prefecture, specifically Amagasaki City. It highlights seven recommended spots, including parks, museums, and local eateries. Viewers are encouraged to share any additional recommendations in the comments. The channel, ''Travel Master,'' aims to enhance travel experiences by providing a variety of information on sightseeing, transportation, accommodation, and dining. The team behind the channel believes in enriching lives through travel and encourages viewers to explore new possibilities through their journeys.' where id = 'c6I2W_wjjl-00fqxBNhDJ';
update content_bodies set title = '和歌山観光プロモーションビデオ（熊野編1）', description = '和歌山県の観光を促進するためのビデオで、特に熊野地域に焦点を当てています。このビデオは和歌山県インターネット放送局を通じて視聴可能です。' where id = 'WIbjoHI-FKp-Xj7VNwCjK';
update content_bodies set title = 'Wakayama Tourism Promotion Video (Kumano Edition 1)', description = 'This is a promotional video for tourism in Wakayama Prefecture, focusing on the Kumano region. It is available through the Wakayama Prefectural Internet Broadcasting Station.' where id = 'l1qyt1XIp3RimE0PCoGmK';
update content_bodies set title = '和歌山観光プロモーションビデオ ''自然の驚異、熊野と高野の伝統文化''', description = 'このビデオは、和歌山の熊野と高野地域の自然の美しさと文化遺産を紹介しています。大地の営みによって育まれた豊かな風景を強調し、この地域が寛容さと精神的な重要性を持つ場所であることを伝えています。' where id = 'MrjnURMmwo8a4CgaKoTbC';
update content_bodies set title = 'Wakayama Tourism Promotion Video ''Natural wonders, traditional culture of Kumano and Koyasan''', description = 'This video showcases the natural beauty and cultural heritage of the Kumano and Koyasan regions in Wakayama. It highlights the area''s rich landscapes shaped by the earth''s processes and emphasizes the region''s reputation as a place of tolerance and spiritual significance.' where id = '7ps0KzMXLS3-PicGEwLgH';
update content_bodies set title = '真田ゆかりの地　高野・九度山', description = '和歌山県にあるインターネット放送局で、真田家に関連する高野と九度山の歴史的な重要性についての情報を提供しています。' where id = 'DTgwyzH7SKYT8Ew-EeGHT';
update content_bodies set title = 'Sanada''s Related Places: Takano and Kudoyama', description = 'This is an internet broadcasting station in Wakayama Prefecture, providing information about the historical significance of Takano and Kudoyama, areas associated with the Sanada clan.' where id = 'QCuICmoLZ6Zy8XpXVMf-H';
update content_bodies set title = '夜の森をほのかに照らすキノコ「シイノトモシビダケ」', description = '和歌山県那智勝浦町の宇久井半島に自生するシイノトモシビダケについて紹介しています。このキノコは夜の森をほのかに照らす特徴があります。シイノトモシビダケの見学会についての問い合わせは、宇久井海と森の自然塾（宇久井ビジターセンター内）までお願いします。連絡先はTEL:0735-54-2510、FAX:0735-54-1540、HPアドレスはhttp://ugui-shizenjyuku.com/index.htmlです。' where id = '2PF1a8tM4d-SIoZue2R-3';
update content_bodies set title = 'Mushroom Illuminating the Night Forest: Shiinotomoshibidake', description = 'This text introduces Shiinotomoshibidake, a mushroom that grows naturally on the Ukui Peninsula in Nachikatsuura, Wakayama Prefecture. For inquiries about viewing events related to Shiinotomoshibidake, please contact the Ukui Sea and Forest Nature School located within the Ukui Visitor Center.' where id = 'KZ-60tDPRRIX0dPEwoy-2';
update content_bodies set title = '日本の精神的な心の故郷—和歌山', description = '和歌山は日本の精神的な心の故郷として知られ、豊かな文化遺産と美しい自然景観を提供しています。この地域には、世界遺産に登録された有名な熊野古道や歴史的な高野山などの聖地があります。訪問者は古代の寺院や神社を探索し、伝統的な日本文化を体験することができます。また、温泉、美しい海岸線、地元の美味しい料理でも知られており、精神的および肉体的なリフレッシュを求める人々にとって理想的な目的地です。' where id = '-NNT8AK_dXldZdsnkLAEj';
update content_bodies set title = 'The Spiritual Heartland of Japan—Wakayama', description = 'Wakayama is known as the spiritual heartland of Japan, offering a rich cultural heritage and stunning natural landscapes. The region is home to sacred sites, including the famous Kumano Kodo pilgrimage routes and the historic Mount Koya, which is a UNESCO World Heritage site. Visitors can explore ancient temples, shrines, and experience traditional Japanese culture. The area is also renowned for its hot springs, beautiful coastlines, and delicious local cuisine, making it a perfect destination for those seeking both spiritual and physical rejuvenation.' where id = 'tMWuit2lvMkiC6N0jYJqn';
update content_bodies set title = '岩手県 国見温泉 日帰り温泉 3選', description = '国見温泉は、岩手県に位置する人気の温泉地で、リラックスできる温泉が魅力です。この記事では、国見温泉エリア内の日帰り利用が可能な温泉施設を3つ紹介し、訪れる人々に自然の温泉の癒し効果を楽しむ選択肢を提供しています。説明には、簡単にナビゲートできるGoogleマップのリンクや、温泉体験に関連するSNSや商品リンクも含まれています。国見温泉の独自の魅力を紹介し、訪問者にその魅力を探求することを促しています。' where id = 'AFgutroEOVCQtYMT0eLJy';
update content_bodies set title = 'Top 3 Day-Use Onsen in Kunimi-onsen, Iwate Prefecture', description = 'Kunimi Onsen is a popular destination in Iwate Prefecture, known for its relaxing hot springs. This article highlights the top three day-use onsen facilities in the area, providing visitors with options to enjoy the therapeutic benefits of the natural hot springs. The description includes links to Google Maps for easy navigation, as well as social media and merchandise links related to the onsen experience. The focus is on promoting the unique charm of Kunimi Onsen and encouraging visitors to explore its offerings.' where id = '0yRTp_fivFuALyl_LkE_z';
