update content_bodies set title = '会津青年会議所', description = 'この動画は会津青年会議所について紹介しています。会津青年会議所は地域の若者たちが集まり、様々な活動を通じて地域社会の発展に寄与することを目的とした団体です。会議所では、地域の課題解決やイベントの企画・運営などを行い、メンバー同士の交流を深める機会も提供しています。' where id = 'ISJ06kiJSjje46ddk-0E2';
