update content_bodies set title = '下北半島 GEO DINING SHIMOKITA', description = '2019年日本国際観光映像祭ガストロノミー部門で優秀賞を受賞した作品です。ジオが生み出した大自然の景観美や、かつて北前船が行き交った港の歴史的意義、豊富な海の幸から生まれた食文化を紹介しています。また、古代から大切に受け継がれてきた芸能や祭り、風土や習慣、地元の人々の温かさも描かれています。この作品は、下北半島国定公園の仏ヶ浦で開催されたダイニングイベント「GEO DINING SHIMOKITA」の様子を可視化し、下北半島の可能性を探ります。' where id = 'XW6skL8DdW4rBrTfJ08gB';
update content_bodies set title = 'Shimokita Peninsula GEO DINING SHIMOKITA', description = 'This work won the Excellence Award in the Gastronomy category at the 2019 Japan International Tourism Film Festival. It showcases the stunning natural beauty created by geological features, the historical significance of ports once frequented by Kitamaebune ships, and the rich food culture stemming from abundant seafood. The film also highlights the traditional arts, festivals, customs, and the warmth of the local people that have been cherished since ancient times. It visualizes the dining event ''GEO DINING SHIMOKITA'' held at Fureai Cape in Shimokita Peninsula National Park and explores the potential of the Shimokita Peninsula.' where id = '3MiQSjDOluD-pGCnNSv5I';
update content_bodies set title = '下北半島 - GEO DINING SHIMOKITA -', description = '2019年日本国際観光映像祭ガストロノミー部門で優秀賞を受賞した作品です。ジオによって生まれた大自然の景観美や、かつて北前船が行き交った港、豊富な海の幸から生まれた食文化を紹介しています。また、古代から受け継がれてきた芸能や祭り、風土や習慣、そこに住む人々の温かさも描かれています。下北半島国定公園の仏ヶ浦で開催されたダイニングアウト「GEO DINING SHIMOKITA」の様子を可視化し、下北半島の可能性を強調しています。' where id = 'NctSRSG_1Oocghl0khe5x';
update content_bodies set title = 'Shimokita Peninsula - GEO DINING SHIMOKITA -', description = 'This work won the Excellence Award in the Gastronomy category at the 2019 Japan International Tourism Film Festival. It showcases the stunning natural beauty created by geological features, the historical ports frequented by Kitamaebune ships, and the rich seafood that has shaped the local food culture. The film also highlights the traditional arts, festivals, customs, and the warmth of the people who have preserved these elements since ancient times. The dining event ''GEO DINING SHIMOKITA'' held at Fureai Cape in Shimokita Peninsula National Park is visually represented, emphasizing the potential of the Shimokita Peninsula.' where id = 'xM1CHKulYsC2l8BTzmliq';
