update content_bodies set title = '田舎館村 冬の田んぼアート２０２２「花時の日の出」', description = '「冬の田んぼアート２０２２」は、新型コロナウイルスの感染拡大防止のため中止となりましたが、青森県では田舎館村とスノーアーティスト集団「It’s OK」の協力で制作したスノーアートの映像を公開します。スノーアートのテーマは「花時の日の出」で、春に花が咲き始める時期、特に桜を指します。この作品は、桜が咲く頃までに新型コロナウイルス感染症が収束し、明るい未来が訪れることを願って制作されました。' where id = 'rRdk6f0U7visauLY7YQn6';
update content_bodies set title = 'Inakadate Village Winter Rice Field Art 2022 ''Sunrise of Flower Time''', description = 'The ''Winter Rice Field Art 2022'' event was unfortunately canceled due to the need to prevent the spread of COVID-19. However, in Aomori Prefecture, a video of the snow art created in collaboration with Inakadate Village and the snow artist group ''It’s OK'' has been released. The theme of the snow art is ''Sunrise of Flower Time,'' which refers to the period in spring when various flowers, especially cherry blossoms, begin to bloom. The artwork was created with the hope that by the time the cherry blossoms start to bloom, the COVID-19 pandemic will have subsided, bringing a bright future like a sunrise.' where id = 'N8op8z4-uiFwBVYjxEj93';
update content_bodies set title = '青森', description = 'この動画では、青森を紹介しています。青森は美しい風景、豊かな文化、独自の伝統で知られる日本の地域です。青森を特別な目的地にするさまざまな観光名所や特徴が強調されています。' where id = 'L-aWtFsuUpr6go1FP2A0I';
update content_bodies set title = 'AOMORI', description = 'This video introduces AOMORI, a region in Japan known for its beautiful landscapes, rich culture, and unique traditions. It highlights various attractions and features that make AOMORI a notable destination.' where id = 'SGPCXcDByTrLNDK4HVsqf';
update content_bodies set title = '高尾山　チェアリフト', description = '高尾山は東京都八王子市に位置し、599メートルの高さを誇る山で、明治の森高尾国定公園内にあります。年間250万人以上の訪問者があり、8つのハイキングコースや山麓にある多摩森林科学園が人気です。チェアリフトは山の中腹までの約12分の乗車時間で、山のふもとの「山麓駅」から中間の「山上駅」まで872メートルの距離を移動します。この乗車は、山々の美しい景色を楽しむことができるため、多くの訪問者に人気があります。' where id = 'sFkquG9LG0vRs8y3WZV7J';
update content_bodies set title = 'Chair Lift Ride at Mount Takao (Ascend) | Japan''s Steepest Slope', description = 'Mount Takao, located in Hachiōji, Tokyo, stands at 599 meters and is part of Meiji no Mori Takao Quasi-National Park. It attracts over 2.5 million visitors annually, offering eight hiking courses and the Tama Forest Science Garden at its base. The chair lift ride to the mountain''s midway point lasts about 12 minutes, covering a distance of 872 meters from Sanroku Station to Sanjo Station. This ride provides a scenic aerial view of the mountains, making it a popular choice for visitors looking to enjoy the natural beauty of the area.' where id = 'FNijca9UDYv4GDvjSZ7Aa';
update content_bodies set title = 'むつ湾 イルカの楽園', description = '2021年6月にむつ湾で遭遇したイルカたちの映像を紹介します。美しい海で自由に泳ぐイルカたちの姿が捉えられており、彼らの生態や行動を観察することができます。この映像は、むつ湾の自然の魅力を伝えるとともに、イルカたちの楽園とも言える環境を感じさせてくれます。' where id = 'sxreDk2sm70LS2aFDwr9H';
update content_bodies set title = 'Mutsu Bay: A Paradise for Dolphins', description = 'This video showcases the dolphins encountered in Mutsu Bay in June 2021.' where id = 'EOvY63e4hxBOoDlibRsjh';
update content_bodies set title = '縄文土偶ならぬ、「縄文にゃ偶」', description = '縄文遺跡群の世界遺産登録を記念して、従来の縄文土偶とは異なる「縄文にゃ偶」を紹介します。この取り組みは、縄文時代の文化的意義を強調しつつ、現代的でユーモラスな解釈を提供しています。' where id = '7gFdCHy--QaYrIl3CTJkm';
update content_bodies set title = 'Jomon Nyagu: A Unique Take on Jomon Figurines', description = 'In celebration of the World Heritage registration of the Jomon archaeological sites, we present ''Jomon Nyagu,'' a playful twist on traditional Jomon figurines. This initiative highlights the cultural significance of the Jomon period while introducing a modern and whimsical interpretation.' where id = 'P6f_xOxOTn24EYpX-VGbz';
update content_bodies set title = 'りんご娘の遮光器土偶けん玉「シャコケン」チャレンジ！！', description = '5月14日はけん玉の日で、りんご娘のトキさんと彩香さんが遮光器土偶けん玉「シャコケン」に挑戦しました。このチャレンジは難易度が高いと言われています。成功すると、木造駅のマスコットしゃこちゃんの目が変わるそうです。' where id = 'XcRARw8wNuBJr8GXtyTuL';
update content_bodies set title = 'Ringo Musume''s Shakouki Dogu Kendama ''Shakoken'' Challenge!!', description = 'On May 14th, which is Kendama Day, Ringo Musume members Toki and Ayaka took on the challenge of the Shakouki Dogu Kendama, known as ''Shakoken.'' The challenge is said to be quite difficult. If they succeed, the eyes of the wooden station''s mascot, Shako-chan, will change!' where id = 'ds1bQa6VCr9PF2m0mZWCc';
update content_bodies set title = 'チャレンジヒルクライム岩木山', description = '青森県の最高峰である岩木山には、69か所のつづら折れカーブを持つ自動車専用道路「津軽岩木スカイライン」があります。この道路は年に一度だけ開放され、山道をひたすら登る自転車レース「チャレンジヒルクライム岩木山」が開催されます。このイベントのドローン映像をぜひご覧ください。' where id = '17tqrgSczCAcxjAhj2_4x';
update content_bodies set title = 'CHALLENGE HILL CLIMB MT. IWAKI, JAPAN', description = 'Located in Aomori Prefecture, Mt. Iwaki is the highest peak in the region, featuring the Tsugaru Iwaki Skyline, a car-only road with 69 winding curves. Once a year, this road is opened for the Challenge Hill Climb Mt. Iwaki, a bicycle race that involves climbing the mountain path. Be sure to check out the drone footage of this exciting event.' where id = 'HRs5ewuMv56XI5WoUFs-i';
update content_bodies set title = '静岡県の浜名湖を上空から - DJI Mavic Mini', description = 'この短い動画は、DJI Mavic Miniを使用して上空から撮影した浜名湖の様子を紹介しています。湖の風景や周辺の様子をユニークな視点で捉えています。' where id = '7-m42mtfaMjBXwBbt36gh';
update content_bodies set title = 'Hamanako(Lake Hamana) from above - Shizuoka, Japan | DJI Mavic Mini', description = 'This video showcases Lake Hamana from an aerial perspective, captured using a DJI Mavic Mini drone. The footage provides a unique view of the lake''s landscape and surroundings.' where id = 'RgpctGhA4K2r2zc1-FO-h';
update content_bodies set title = '十和田湖スカイランタン　湖水まつり2020', description = 'この動画は十和田湖スカイランタン　湖水まつり2020について紹介しています。' where id = 'pQbkY8doSGl_Ys8bL8xvr';
update content_bodies set title = 'Towada Lake Sky Lantern Festival 2020', description = 'This video introduces the Towada Lake Sky Lantern Festival 2020.' where id = '8r88kFM1Hab-nPYbEimJO';
update content_bodies set title = '夢の島熱帯植物館| ハロウィーンのカボチャ', description = '夢の島熱帯植物館は、東京にある植物園で、熱帯植物と人間の生活の関係をテーマにしています。1988年に設立され、3つのドームには約1,000種の熱帯および亜熱帯植物が展示されています。ドーム内には熱帯雨林や熱帯村、オガサワラ諸島の植生があり、月曜日を除いて毎日開館しています。土日や祝日にはガイドツアーも行われています。9月末から11月初めまでの間、毎年恒例のハロウィーンカボチャ月間を開催し、庭には子供たちが遊べる巨大なカボチャが展示されます。入場料は大人250円、65歳以上120円、13〜15歳100円、12歳以下は無料です。新木場駅から徒歩10分の距離にあります。' where id = '1X5EIJI-N24t8N_4IhzEZ';
update content_bodies set title = 'Yumenoshima Tropical Greenhouse Dome | Annual Halloween Pumpkin Month', description = 'The Yumenoshima Tropical Greenhouse Dome, located in Tokyo, Japan, is a botanical garden that showcases the relationship between tropical plants and human life. Established in 1988, it features three domes housing around 1,000 species of tropical and semitropical plants, including a rainforest, a tropical village, and vegetation from the Ogasawara Islands. The greenhouse is open daily except Mondays and offers guided tours on weekends and holidays. From late September to early November, the dome celebrates its annual Halloween Pumpkin Month, featuring giant pumpkins in the garden for children to play around. Admission fees are 250 yen for adults, with discounts for seniors and free entry for children under 12. The location is a 10-minute walk from Shin-Kiba Station.' where id = 'sAtSkYMyhvGQzwUGouEuV';
update content_bodies set title = '2020蕪島のサンドアート　タイムラプス', description = 'ウミネコの繁殖地である蕪島でのサンドアート制作の様子をタイムラプス動画で紹介しています。動画では短時間で制作されているように見えますが、実際には約5時間かかっています。制作者の城前さんはサンドアートを独学で習得し、今年の8月頃から制作を始めたそうです。また、蕪島を訪れる人との交流も楽しんでいるので、見かけた際にはぜひ声をかけてみてください。' where id = 'wDdYex1sA5gu_Ke9WEnfY';
update content_bodies set title = '2020 Kabushima Sand Art Time-lapse', description = 'This time-lapse video showcases the creation of sand art at Kabushima, a breeding ground for black-tailed gulls. Although the video appears to show the process happening quickly, it actually took about five hours to complete. The artist, Mr. Jomae, learned sand art entirely through self-study and began creating pieces around August of this year. He enjoys interacting with visitors to Kabushima, so feel free to approach him if you see him.' where id = 'qC-xS2o-j2mYf1ictZXor';
update content_bodies set title = 'ハロウィンパーティー2021 | 巨大ハロウィンカボチャの展示', description = '夢の島熱帯植物館ドームでは、毎年恒例のハロウィンパーティーが開催され、巨大なゴーストカボチャが展示されています。このイベントは9月22日から10月31日まで行われ、50〜100キログラムのカボチャが100個以上展示されます。入場料は大人250円で、12歳以下の子供は無料です。来場者は温室を散策し、熱帯植物を楽しんだり、ハロウィンの背景で写真を撮ったりできます。ピクニックエリアもあり、カフェテリアで食事を購入することも可能です。イベントは火曜日から日曜日の午前9時30分から午後5時まで営業しており、最終入場は午後4時です。会場は新木場駅から徒歩10分の距離です。' where id = 'YgKnfO6D_3qjdkS0eWemS';
update content_bodies set title = 'Giant Halloween Pumpkins 2021 at Yumenoshima | Halloween Pumpkins | Halloween Party', description = 'The Yumenoshima tropical greenhouse dome is hosting its annual Halloween party featuring giant ghost pumpkins. The event runs from September 22 to October 31, showcasing over 100 pumpkins weighing between 50 to 100 kilograms, crafted in Hitachiomiya City, Ibaraki Prefecture. Admission is 250 yen for adults, with free entry for children under 12. Visitors can explore the greenhouse, enjoy tropical plants, and take photos with Halloween backdrops. A picnic area is available, or guests can purchase food from the cafeteria. The event operates Tuesday to Sunday from 9:30 AM to 5:00 PM, with last entry at 4:00 PM. The venue is a 10-minute walk from Shin-Kiba Station.' where id = 'jSfBkhwWkFAVgHKGkrEG6';
update content_bodies set title = '2020ザボンの月（種差海岸の満月） タイムラプス', description = '草野心平が「ザボンの月」と称した種差海岸の満月は、上がり始めは赤く、徐々に黄色く変わります。月の明かりが海を照らし、幻想的な銀色の道が現れます。ハマギクやアヅマギクが群生する突端に登ると、ザボンのような満月が美しく浮かび上がります。この情景は、草野心平の1973年の作品「種差海岸」にインスパイアされています。' where id = '_rgnucwKWikbXAMTPM2SL';
update content_bodies set title = '2020 Zabon Moon (Full Moon at Tanesashi Coast) Time-lapse', description = 'The full moon at Tanesashi Coast, referred to as the ''Zabon Moon'' by Shinpei Kusano, begins rising red and gradually turns yellow. As the moonlight illuminates the sea, a fantastical silver path appears. When reaching the tip where the beach daisies and eastern daisies bloom, the Zabon-like full moon rises beautifully. This scene is inspired by Shinpei Kusano''s work ''Tanesashi Coast'' from 1973.' where id = 'wp2n1fn6pHvFo_RgUCTWD';
update content_bodies set title = '函館市観光PR動画　＃函館旅部「Oh!Hakodate!」　春夏秋冬編ショート', description = 'この動画は函館市の観光を紹介しており、春夏秋冬の魅力を伝えています。函館の美しい風景や文化、観光スポットを短い時間で楽しむことができ、観光客にとって訪れる価値があることをアピールしています。' where id = 't59teIPiQNAFqGH7neabR';
update content_bodies set title = 'Hakodate City Tourism PR Video #HakodateTravelClub ''Oh! Hakodate!'' Four Seasons Edition Short', description = 'This video introduces tourism in Hakodate City.' where id = 'UNDu67hvkEQVsaZ2AEjhQ';
update content_bodies set title = '冬の八甲田山 バックカントリースキー編', description = '冬の八甲田山の雄大な自然の中を滑り降りるバックカントリースキーの映像を公開します。八甲田山への入山にあたっては、八甲田山岳スキー安全対策協議会により制定されたMt.八甲田ローカルルールを確認するようお願いします。' where id = 'nkbD9kZecm3QTrO9-Huo6';
update content_bodies set title = 'Backcountry Skiing in Winter at Mount Hakkoda', description = 'This video showcases the exhilarating experience of backcountry skiing down the majestic slopes of Mount Hakkoda in winter. Before entering the area, please ensure to check the local rules established by the Hakkoda Mountain Ski Safety Measures Council.' where id = 'fli7kvzHzwWuMV1_NGaIP';
update content_bodies set title = '冬の八甲田山 銀世界編', description = 'ドローンで撮影した冬の八甲田山の映像を公開します。八甲田山に入山する際は、八甲田山岳スキー安全対策協議会が制定したローカルルールを必ず確認してください。' where id = 'vi13Br4PjKZFkdkd-PCYZ';
update content_bodies set title = 'Winter at Mount Hakkoda: Silver World Edition', description = 'This video showcases the winter scenery of Mount Hakkoda, captured by drone. Please be sure to check the local rules established by the Hakkoda Mountain Ski Safety Measures Council before entering Mount Hakkoda.' where id = 'xLLr1l10GywzV4yxhe5w-';
update content_bodies set title = 'Tech Trip TOKUSHIMA City', description = '徳島の伝統文化や観光資源をクリエイターの視点で表現したPR動画「Tech Trip TOKUSHIMA City」が完成しました。この動画では、徳島の魅力を新たな視点から紹介しています。ぜひご覧ください。' where id = '8ekcNFTnzUhkgRBFqNTGL';
update content_bodies set title = 'Tech Trip TOKUSHIMA City', description = 'The promotional video ''Tech Trip TOKUSHIMA City'' has been completed, showcasing Tokushima''s traditional culture and tourist resources from a creator''s perspective. We invite you to watch it.' where id = 'nZ0GxNuDmNm7TaodVS1bK';
update content_bodies set title = '【知られざる鈴鹿の森】 ～森の案内人編～', description = '東近江市に位置する鈴鹿の森は、豊かな自然と文化が共存する場所です。この森の魅力を発信する活動を行っている人々がいて、彼らは鈴鹿の森の特有の魅力について語ります。自然の美しさや文化的な重要性を強調しながら、鈴鹿の森の魅力を伝えることに情熱を注いでいます。' where id = '-fEhDMRrPs-GXozdVp5Je';
update content_bodies set title = 'Discovering the Hidden Charm of Suzuka Forest: Guide Edition', description = 'In Higashiomi City, the Suzuka Forest is alive with rich nature and culture, and there are people dedicated to sharing its allure. They discuss the unique attractions of Suzuka Forest, highlighting its natural beauty and cultural significance.' where id = 'bCz3RXu_16pId_qmxwVkz';
update content_bodies set title = '2020 五所川原立佞武多 ドローンLIVE配信', description = '2:29:45から立佞武多の点灯・出陣のライブ配信が始まります。今年は新型コロナウイルス感染症の拡大防止のため、五所川原立佞武多の運行が中止となりました。青森県では、地域の協力のもと、ドローンを使用して高さ23mの立佞武多出陣の迫力映像をライブ配信します。なお、ドローン撮影中は会場周辺が立ち入り禁止となりますので、ぜひご自宅でご覧ください。' where id = '-Jly44Z1NulhVbugBDN6W';
update content_bodies set title = '2020 Goshogawara Tachineputa Drone Live Streaming', description = 'The live streaming of the Tachineputa lantern lighting and departure begins at 2:29:45. This year, due to the spread of COVID-19, the Goshogawara Tachineputa event has been canceled. In Aomori Prefecture, with the cooperation of the local community, a powerful live broadcast of the 23-meter tall Tachineputa''s departure will be captured using drones. Please note that the area around the venue will be off-limits during the drone filming, so we encourage everyone to watch from home.' where id = 'N8Y3tSaYltDPOBgyI9frp';
update content_bodies set title = '２０２０　世界でいちばん美しい桜　～弘前公園　Ｐａｒｔ２～', description = '今年も弘前公園の桜を楽しみにしていた皆様へ、閉鎖されている弘前公園の桜を特別に撮影した映像（Part2）を公開します。今年は、新型コロナウイルスの感染拡大を防止するため、やむを得ず、４月１０日から弘前公園は閉鎖されています。青森県では、その美しい弘前公園の桜をご自宅でご覧いただけるよう、弘前市の協力のもと撮影した今年の桜の映像を公開します。新型コロナウイルスの収束後には、再び、国内外から多くの方々に青森県を訪れていただきたいと願っています。' where id = 'FyMN8KGr32-qHr_df_AVm';
update content_bodies set title = '2020 The Most Beautiful Cherry Blossoms in the World - Hirosaki Park Part 2', description = 'For those who were looking forward to the cherry blossoms at Hirosaki Park this year, we are releasing special footage of the park''s cherry blossoms, which are currently closed. Due to the spread of COVID-19, Hirosaki Park has been closed since April 10 to prevent infection during the cherry blossom viewing season. In collaboration with Hirosaki City, Aomori Prefecture is providing this year''s cherry blossom footage for you to enjoy at home. We hope that after the COVID-19 situation improves, many people from both Japan and abroad will visit Aomori Prefecture again.' where id = 'XK4vo1DuvRzV6hV4T0ijl';
update content_bodies set title = 'まるで海外な青森の絶景スポットを紹介！「ここも青森」CM', description = '青森には、ハワイやカッパドキア、北欧を思わせる絶景スポットが存在します。新型コロナウイルスの影響で海外旅行が難しい今、青森で海外気分を味わえるスポットをぜひ訪れてみてください。もちろん、青森ならではの魅力もたくさんあります。' where id = 'ruC5Zza9FVpzCyR4lQKD6';
update content_bodies set title = 'Introducing Aomori''s Stunning Spots That Feel Like Overseas! ''This is Aomori'' Commercial', description = 'Aomori features breathtaking spots that evoke images of Hawaii, Cappadocia, and Scandinavia. Due to the impact of the COVID-19 pandemic, traveling abroad has become challenging, but you can still experience a taste of international vibes right in Aomori. The region also offers unique attractions that you won''t find anywhere else in the world.' where id = 'EYCSwJRqfyWkqg1yc3CxS';
update content_bodies set title = '～梅～　三重梅めぐり　いなべ市梅林公園', description = '三重県はいなべ市梅林公園を含む梅の名所であり、ここには東海地区最大級の梅林があります。鈴鹿山脈を背景に、白や薄紅、黄色などの梅が約4000本咲き誇り、色とりどりの美しい景観を楽しむことができます。' where id = '3Q5Qz_r5uSEEjFj5v8FCT';
update content_bodies set title = 'Ume Blossoms - Inabe City Plum Grove Tour', description = 'Mie Prefecture is known for its plum blossoms, and Inabe City Plum Grove Park features one of the largest plum groves in the Tokai region. Set against the backdrop of the Suzuka Mountains, the park boasts around 4,000 plum trees blooming in various colors, including white, pale pink, and yellow.' where id = 'cz_GPLu5F9Wel6BQiyipS';
update content_bodies set title = '２０２０　世界でいちばん美しい桜　～弘前公園　Ｐａｒｔ１～', description = '今年も弘前公園の桜を楽しみにしていた皆様へ、特別に撮影した閉鎖中の弘前公園の桜の映像を公開します。今年は新型コロナウイルスの感染拡大防止のため、やむを得ず４月１０日から弘前公園が閉鎖されています。青森県では、その美しい桜を自宅で楽しんでいただけるよう、弘前市の協力のもと撮影した映像をお届けします。新型コロナウイルスが収束した後には、国内外から多くの方々に青森県を訪れていただけることを願っています。' where id = 'eYxXjZZPWmmXfvcDECnNB';
update content_bodies set title = '2020 The Most Beautiful Cherry Blossoms in the World - Hirosaki Park Part 1', description = 'For those who were looking forward to the cherry blossoms at Hirosaki Park this year, we are pleased to share special footage of the park''s cherry blossoms, which are currently closed. Due to the spread of COVID-19, Hirosaki Park has been closed since April 10 to prevent infection during the cherry blossom viewing season. In collaboration with Hirosaki City, we have filmed this year''s cherry blossoms so that you can enjoy their beauty from home. We hope that after the COVID-19 situation improves, many people from both Japan and abroad will visit Aomori Prefecture again.' where id = 'BBAg4EgPRV42Qm44aWvcZ';
update content_bodies set title = 'これが、青森県の本気のリンゴCMだ！「あおもりんご」CM', description = '青森県は、日本一のリンゴ生産量を誇り、リンゴ試験場で約300種、県内で約50種のリンゴが栽培されています。市場に出荷されるのは約40種類です。本CMには本物の青森のリンゴ農家が出演し、しりとりを繰り広げます。真冬の雪を溶かすような熱演をぜひご覧ください。青森県内には「リンゴのポスト」や「リンゴ型のつり革」、「リンゴ型のカーブミラー」、「リンゴ型の駅のホームの無線」など、リンゴ愛があふれています。このCMは、青森のリンゴの多様性と愛情を知ってもらうために制作されました。1月から3月にかけて出荷量が最も多くなる青森県のリンゴを、ぜひスーパーでお楽しみください！' where id = 'X6WLRPZ4fz1gc2lo-NjUj';
update content_bodies set title = 'This is Aomori''s Serious Apple Commercial! ''Aomori Apple'' CM', description = 'Aomori Prefecture boasts the highest apple production in Japan, with around 300 varieties cultivated at the apple research station and about 50 varieties grown in the region. Only about 40 of these varieties are shipped to the market. The commercial features real apple farmers from Aomori engaging in a game of shiritori (a Japanese word game). Their passionate performances are sure to melt the winter snow. The love for apples is evident throughout the city, with apple-themed items like ''apple post boxes,'' ''apple-shaped handrails,'' ''apple-shaped convex mirrors,'' and ''apple-shaped wireless stations.'' This commercial aims to showcase the overwhelming variety of apples and the deep affection for them in Aomori. From January to March, Aomori''s apple shipments peak, so be sure to enjoy Aomori apples when shopping at supermarkets!' where id = 'aPpNLZHzzNkJfrgffLhNp';
update content_bodies set title = '漁師の一日　風間浦のアンコウ漁', description = '青森県風間浦村で、伝統的な「からばり」を使ってアンコウ漁を行う唯一の漁師、木村喜志雄さんの一日を描いています。冬の厳しい津軽海峡での漁は過酷ですが、温泉や昔からの仲間たちがその疲れを癒してくれます。漁師の生活を通じて、青森ならではの暮らしぶりを紹介しています。' where id = 'bSP2t8auP3H8Veq0peDcV';
update content_bodies set title = 'A Day in the Life of a Fisherman: Anglerfish Fishing in Kazamaura', description = 'Kimura Kishiou is the only fisherman in Kazamaura, Aomori Prefecture, who uses the traditional ''karabari'' method for anglerfish fishing. Fishing in the harsh winter conditions of the Tsugaru Strait is challenging, but hot springs and long-time friends help alleviate the fatigue of fishing. This piece showcases the unique lifestyle of Aomori through the daily life of a fisherman.' where id = '3B6svoH0akBcrnS1hTAQl';
update content_bodies set title = '田舎館田んぼアート「手塚治虫キャラクター」', description = '2018年7月12日、青森県田舎館村にて、手塚治虫のキャラクターをテーマにした田んぼアートが一挙に撮影されました。' where id = '3aC6dOpCycelnrG3qmvum';
update content_bodies set title = 'Inakadate Rice Field Art: Tezuka Osamu Characters', description = 'On July 12, 2018, a series of rice field art featuring characters created by Osamu Tezuka was captured in Inakadate Village, Aomori Prefecture.' where id = 'Zpa-Wzh77_BHKHwFCT0pX';
update content_bodies set title = '青森市公式チャンネルで「#青森ねぶた祭」を目撃せよ！', description = '青森ねぶた祭の再生リストをYouTubeでチェックし、華やかな祭りの様子を体験しましょう。詳細については、青森ねぶた祭の公式サイトをご覧ください。' where id = 'cndKGrPiXpbsR4_dih9EV';
update content_bodies set title = 'Experience the Aomori Nebuta Festival on the Official Aomori City Channel!', description = 'Check out the Aomori Nebuta Festival playlist on YouTube to witness the vibrant celebrations. For more information, visit the official Aomori Nebuta Festival website.' where id = 'J1Hf4Xj6UNPm249D58ix0';
update content_bodies set title = '透明な海、左右からの波(Time Lapse)～尻屋埼灯台～2', description = '日本で唯一無二の絶景が解禁されました！2018年6月1日に一般公開が開始された尻屋埼灯台に登ってみました。画面の左側には津軽海峡、右側には太平洋が映し出されています。' where id = 'HCC8WfouuKcTMzB4FpAyC';
update content_bodies set title = 'Transparent Sea, Waves from Both Sides (Time Lapse) - Shiriya Cape Lighthouse 2', description = 'A unique breathtaking view in Japan has been unveiled! I climbed the Shiriya Cape Lighthouse, which opened to the public on June 1, 2018. The left side of the screen shows the Tsugaru Strait, while the right side displays the Pacific Ocean.' where id = 'yBo2eRGC0xmVAuizbdwR-';
update content_bodies set title = '津軽あかつきの会　古津軽伝承料理', description = '弘前市石川地区では、約30人の「かっちゃ」が集まり、地域の伝承料理の復活と保存に取り組んでいる「津軽あかつきの会」が活動しています。使用する食材のほとんどは地元産で、冬の雪に閉ざされた季節には、発酵・乾燥・塩蔵といった伝承技術を駆使した「古津軽伝承料理」を提供しています。訪れる人々を温かく迎える「津軽あかつきの会」の雰囲気を伝えるDELISH AOMORIの特別ムービーです。' where id = 'sKJGKZauCmoy4U9RlJ7O2';
update content_bodies set title = 'Tsugaru Akatsuki Association: Traditional Tsugaru Cuisine', description = 'In the Ishikawa district of Hirosaki City, about 30 local women, known as ''kaccha'', have come together to revive and preserve traditional regional cuisine through the ''Tsugaru Akatsuki Association''. Most of the ingredients used are locally sourced. During the winter months, when the area is covered in snow, they showcase ''Ancient Tsugaru Traditional Cuisine'', which employs traditional techniques such as fermentation, drying, and salting. DELISH AOMORI presents a special movie that captures the warm atmosphere of the Tsugaru Akatsuki Association, welcoming visitors with their culinary heritage.' where id = 'dX94RzxGlN9Om7wGgmcpc';
update content_bodies set title = '函館山の夜景', description = '函館山からの眺望は、ミシュラン・グリーンガイド・ジャポンで三つ星として評価されています。この映像は、日没の約30分前から約2時間にわたってタイムラプスで撮影されました。撮影日は2020年11月17日で、撮影場所は函館山展望台です。' where id = 'J65ETqTPp81pkhvG66I7y';
update content_bodies set title = 'The Night View from Mt Hakodate', description = 'The view from Mt. Hakodate is highly acclaimed, receiving a three-star rating in the ''Michelin Green Guide Japon.'' The footage was captured in a time-lapse format, showcasing the scenery from about 30 minutes before sunset for approximately two hours. The filming took place on November 17, 2020, at the Mt. Hakodate Observatory.' where id = '0hF1vix-LHt11251lCAno';
update content_bodies set title = '2025.8.2 青森ねぶた祭 ダイジェスト', description = '青森市で8月2日から7日まで開催される青森ねぶた祭の初日、8月2日の夜の様子をお届けします。今年のテーマは「～みなとまち青森400歳～龍神とともに」で、作は福士裕朗氏によるものです。' where id = 'gSUqoU-dA-Omx0owjuQtx';
update content_bodies set title = 'Aomori Nebuta Festival Digest - August 2, 2025', description = 'The Aomori Nebuta Festival is being held in Aomori City from August 2 to 7. This summary captures the atmosphere of the first night, August 2, showcasing the vibrant festivities. The theme for this year''s festival is ''400 Years of Port City Aomori - Together with the Dragon God,'' created by Hiroaki Fukushi.' where id = 'iZLtsSbRPHWbNEVm8I6GB';
update content_bodies set title = '青い森の水辺から', description = '青森市企業局水道部が制作したPR動画です。' where id = 'Rsgx62POP6h34kwf2it2L';
update content_bodies set title = 'From the Waterside of Aomori', description = 'This is a PR video created by the Aomori City Waterworks Bureau.' where id = 'QeKslkBoFfwdX-6-rfN-i';
update content_bodies set title = 'DELISH AOMORI「大間マグロのマグロカツ」', description = 'まるごと青森が提供するレシピ動画「DELISH AOMORI」の第10弾では、有名な大間のマグロを取り上げています。刺身として食べても美味しいのは間違いありませんが、このレシピではカリッとした衣ととろけるようなレアの中身を持つカツに仕上げています。やはり大間のマグロは格別です！「DELISH AOMORI」はまるごと青森のFacebookで随時公開されています。' where id = 'cmTfJbVPzmQQy3GuMo0U6';
update content_bodies set title = 'DELISH AOMORI ''Oma Tuna Katsu''', description = 'The recipe video series ''DELISH AOMORI'' presents its 10th episode featuring the famous ingredient, Oma tuna. While it is undoubtedly delicious as sashimi, this recipe transforms it into a crispy, succulent katsu with a melt-in-your-mouth rare center. Oma tuna truly is exceptional! ''DELISH AOMORI'' is regularly published on the Marugoto Aomori Facebook page.' where id = 'UpLPDSuQCTIg7nF1GG3oo';
update content_bodies set title = 'DELISH AOMORI「八戸前沖さばの洋風味噌煮」', description = 'まるごと青森が提供するレシピ動画「DELISH AOMORI」の第9弾では、八戸前沖さばを使った洋風の味噌煮を紹介しています。定番の味噌煮をアレンジし、脂の乗ったさばの美味しさを引き立てた一皿に仕上げました。いつもとは異なる晩ごはんのおかずとして楽しめるレシピです。「DELISH AOMORI」はまるごと青森のFacebookで随時公開されています。' where id = 'fOk2bGt59an8iJSBjtf8B';
update content_bodies set title = 'DELISH AOMORI: Western-style Miso Braised Hachinohe Mackerel', description = 'The ninth installment of the recipe video series ''DELISH AOMORI'' presents a unique take on a classic dish using Hachinohe mackerel. This recipe features the rich flavor of mackerel, traditionally prepared in miso, but with a Western twist. It''s a delicious option for a dinner side dish that offers a different flavor profile. ''DELISH AOMORI'' is regularly updated on the Marugoto Aomori Facebook page.' where id = 'vroW7QGsspEl9Fx3G1Ymg';
update content_bodies set title = 'DELISH AOMORI「津軽百年食堂　清おばあちゃん」', description = '黒石市の弘南鉄道黒石駅前に位置する「すごう食堂」は、大正時代から4代にわたり受け継がれ、「津軽百年食堂」の一つとして知られています。現在の店主である須郷清さんは87歳で、今も現役の調理担当として店に立っています。このDELISH AOMORIのスペシャルムービーでは、百年にわたって受け継がれてきた変わらない味と、懐かしさを感じる店の雰囲気をお伝えします。' where id = 'kZyIsFHLKmRsJmod3u7sR';
update content_bodies set title = 'Delish Aomori: Tsugaru Hyakunen Shokudo - Grandma Kiyo', description = 'Located in front of Kuroishi Station on the Konan Railway, ''Sugou Shokudo'' has been passed down through four generations since the Taisho era and is counted among the ''Tsugaru Hyakunen Shokudo'' establishments. The current owner, 87-year-old Kiyo Sugou, continues to work actively in the kitchen, embodying the spirit of the restaurant. This Special Movie from DELISH AOMORI showcases the unchanged flavors that have been preserved for a century and the nostalgic atmosphere of the establishment.' where id = 'o7OPwL21Qbl0y2eJScTdI';
update content_bodies set title = 'DELISH AOMORI「三沢の長芋アヒージョ」', description = 'まるごと青森が提供するレシピ動画「DELISH AOMORI」の第８弾では、三沢市で栽培されている長芋を使用したアヒージョのレシピが紹介されています。長芋を皮ごと使うことで、手にかゆみが起きず、栄養をしっかり摂取できるのが特徴です。「DELISH AOMORI」は、まるごと青森のFacebookで随時公開されています。' where id = '4-5miS6EjfVhdbMiFzq0s';
update content_bodies set title = 'DELISH AOMORI: Misawa Nagaimo Ajillo', description = 'DELISH AOMORI presents a recipe video featuring ingredients from Aomori. The eighth installment highlights Nagaimo, a type of yam cultivated in Misawa City. This recipe showcases Ajillo made with the whole Nagaimo, including the skin. Cooking with the skin prevents itching on the hands and ensures that nutrients are fully retained. DELISH AOMORI videos are regularly published on the Marugoto Aomori Facebook page.' where id = 'RDfg-SrbT9FgAKcmH6cPa';
update content_bodies set title = '桜の名所　鏡山公園（東広島市）', description = '鏡山公園は、国史跡・鏡山城跡の麓に整備された公園で、30種余り約500本の桜が咲きほこる、東広島を代表する桜の名所の一つです。園内には、幾つかの池があり、美しい景観を見せてくれるほか、ウォーキングコースも設定されており、晴れた日には健康づくりを兼ねた散策にもお勧めです。アクセスは、JR山陽本線西条駅からバスで約10分、または山陽自動車道西条ICから車で約20分です。駐車場もあり、220台収容可能で大型バスも利用できます。' where id = 'oGi7IcLsLJnRWuK8ZgdGZ';
update content_bodies set title = 'Kaguyama Park: A Famous Cherry Blossom Spot in Higashihiroshima', description = 'Kaguyama Park, located at the foot of the historic Kaguyama Castle ruins, is one of Higashihiroshima''s premier cherry blossom viewing spots, featuring over 500 cherry trees of more than 30 varieties. The park includes several ponds that enhance its beautiful scenery, and it offers walking courses, making it an excellent choice for health-conscious visitors on sunny days.' where id = '8Y_sADr4IquZzQsP5lmlZ';
update content_bodies set title = 'DELISH AOMORI「十和田ごぼうの洋風きんぴら」', description = 'まるごと青森が提供するレシピ動画「DELISH AOMORI」の第６弾です。今回は、みずみずしく、獲れたては生でも食べられる十和田のごぼうを使い、きんぴらごぼうを洋風にアレンジしました。「DELISH AOMORI」は、まるごと青森のFacebookで随時公開されています。' where id = '1Z07Q2YYPqNzEP1nqUb83';
update content_bodies set title = 'DELISH AOMORI: Western-style Kinpira with Towada Burdock', description = 'This is the sixth installment of the recipe video series ''DELISH AOMORI,'' which showcases the flavors of Aomori. The featured ingredient is the fresh and juicy Towada burdock, which can even be eaten raw when freshly harvested. In this episode, we present a Western-style twist on the traditional kinpira gobo dish. ''DELISH AOMORI'' is regularly published on the Marugoto Aomori Facebook page.' where id = 'O5-5e14qaIRwavlhHO8ah';
update content_bodies set title = '沖縄市を5分で', description = 'このプロモーションDVDは、沖縄市の魅力を5分という短い時間で紹介しています。観光客を惹きつけることを目的としており、沖縄市の独自の文化や観光名所、体験を提示しています。視聴者は沖縄市の魅力を手軽に理解できる内容となっており、訪問を検討している人々にとって理想的な導入となっています。' where id = 'd3Wg4ivgjAAAXWKemS1_A';
update content_bodies set title = 'Okinawa City in 5 Minutes', description = 'This promotional DVD showcases the highlights of Okinawa City in a concise five-minute format. It aims to attract tourists by presenting the city''s unique culture, attractions, and experiences. Viewers can expect a quick yet engaging overview of what Okinawa City has to offer, making it an ideal introduction for potential visitors.' where id = 'm2G6jAjH2WEOyjqFOOM-T';
update content_bodies set title = 'DELISH AOMORI「嶽きみのカラフルディップ」', description = 'まるごと青森が提供するレシピ動画「DELISH AOMORI」の第３弾では、とうもろこしの美味しさを引き立てるカラフルな４種のディップを紹介します。特に、スルッとキレイに剥ける皮にも注目が集まります。「DELISH AOMORI」は、まるごと青森のFacebookで随時公開されています。' where id = 'c4y0zwFtFEW0DPZSGbgYm';
update content_bodies set title = 'DELISH AOMORI: Colorful Dips with Dake Kimi Corn', description = 'The third installment of the recipe video series ''DELISH AOMORI'' showcases four colorful dips that enhance the deliciousness of Dake Kimi corn. The video also highlights the easy-to-peel skin of the corn. ''DELISH AOMORI'' is regularly published on the Marugoto Aomori Facebook page.' where id = '56LDYDIrQmX3u9DjKl7c_';
update content_bodies set title = '祖母・傾・大崩ユネスコエコパークPR動画（1分バージョン）', description = '宮崎県と大分県にまたがる「祖母・傾・大崩ユネスコエコパーク」は、鋭く尖った山々や切り立った崖、美しい渓谷など、独特な景観を持っています。この地域は世界にその価値を認められた魅力が満載です。ぜひ訪れてみませんか？' where id = 'wRAjhlggXVUPIjFtzPzSB';
update content_bodies set title = 'Sobo, Kake, and Okue UNESCO Eco-Park PR Video (1-Minute Version)', description = 'The Sobo, Kake, and Okue UNESCO Eco-Park, spanning Miyazaki and Oita Prefectures, features unique landscapes characterized by sharply pointed mountains, steep cliffs, and beautiful valleys. Why not visit this region, rich in charm and recognized for its value worldwide?' where id = '1zdNlBJtybnjWKib1FIwJ';
update content_bodies set title = 'DELISH AOMORI「蓬田村の冷やしトマト麺」', description = '「DELISH AOMORI」は、青森の魅力を伝えるレシピ動画と観光動画の新しい形です。第1弾として紹介されるのは、蓬田村産のトマト「津軽の雫」を使用した冷やし麺です。このプロジェクトは、まるごと青森のFacebookページで順次公開されます。青森の食材を活かした新しい料理を楽しむことができる機会です。' where id = 'j4o62ul9qg5QP6sHq6ES8';
update content_bodies set title = 'DELISH AOMORI ''Chilled Tomato Noodles from Yawatamura''', description = 'DELISH AOMORI is a new format for recipe and tourism videos showcasing the entirety of Aomori. The first menu features chilled noodles made with tomatoes, specifically using ''Tsugaru no Shizuku'', a variety of tomato produced in Yawatamura. DELISH AOMORI will be released sequentially on the Marugoto Aomori Facebook page.' where id = 'bs1mSlKH0oxs3cmM3E5OA';
update content_bodies set title = 'DELISH AOMORI「ミサオおばあちゃんの笹餅」', description = '五所川原市金木町で、90歳の元気なおばあちゃん、桑田ミサオさんが作る人気の笹餅。食べた人を幸せにするその笹餅を作る様子と、ミサオさんの温かい人柄に触れられる、DELISH AOMORIが届ける特別な映画です。' where id = 'vqv3Ip_xxPJ-fnS9sWCwf';
update content_bodies set title = 'DELISH AOMORI: Grandma Misao''s Sasa Mochi', description = 'In Goshogawara City, Kanagi Town, 90-year-old Misao Kuwata continues to make her popular sasa mochi. This special movie by DELISH AOMORI showcases the warm personality of Grandma Misao and the delightful process of making the sasa mochi that brings happiness to those who eat it.' where id = 'F67k97Hd4ArbqVUA4IYL9';
update content_bodies set title = 'サイクリングパラダイス MIYAZAKI', description = '宮崎は温暖な気候に恵まれ、年間を通じてサイクリングを楽しむことができます。この記事では、宮崎の中でも特に美しいサイクリングルートである青島から日南海岸、都井岬までの風景とサイクリング環境を紹介します。「サイクリングパラダイス＝みやざき」として、日本のひなたを走る魅力を体験してください。' where id = '8Kq2xS5nY4za0Mc7L1lB0';
update content_bodies set title = 'Cycling paradise MIYAZAKI', description = 'Miyazaki, with its warm climate, offers year-round cycling opportunities. This article highlights one of the best cycling routes in Miyazaki, which stretches from Aoshima to the Nichinan Coast and Cape Toi, showcasing beautiful landscapes and excellent cycling conditions. Experience the ''Cycling Paradise = Miyazaki'' and ride through Japan''s sunny side!' where id = 'y-C_Obj01UkvaGI0R6g-x';
update content_bodies set title = '十和田市民に親しまれる「とうてつ駅そば」', description = 'この動画では、十和田市民に親しまれている「とうてつ駅そば」について紹介しています。地元の人々に愛されるこのそば屋は、地域の食文化の一部として重要な存在です。' where id = 'iMfbj5U_Gs0FRjsFmRZm9';
update content_bodies set title = 'Tōtetsu Station Soba, Beloved by the Citizens of Towada', description = 'This video introduces ''Tōtetsu Station Soba,'' a popular soba restaurant cherished by the citizens of Towada City.' where id = 'l50jR3zsp9oSLofWiXzsQ';
update content_bodies set title = '地域に愛される「ハピたのかふぇ」', description = 'この動画では、地域に愛されている「ハピたのかふぇ」について紹介しています。' where id = '7aHIZjHGNMP15YxOvvj2f';
update content_bodies set title = 'Hapi Tano Cafe Loved by the Community', description = 'This video introduces ''Hapi Tano Cafe,'' a place cherished by the local community.' where id = 'rCMkF9ZfZqSxOMwBTizF2';
update content_bodies set title = '十和田市民のソウルフード、司バラ焼き大衆食堂', description = 'この動画では、十和田市民にとってのソウルフードである司バラ焼き大衆食堂について紹介しています。' where id = 'R-4w-RZsCe2kekqK1CTEC';
update content_bodies set title = 'Tsukasa Bara-yaki Daisuke Shokudo: The Soul Food of Towada City', description = 'This video introduces Tsukasa Bara-yaki Daisuke Shokudo, a popular eatery that serves as the soul food for the residents of Towada City.' where id = '7PdhKped9DgfqTe5OBF69';
update content_bodies set title = 'すずのや、化け焼きそば', description = 'この動画では、すずのやと化け焼きそばについて紹介しています。すずのやは、特に化け焼きそばに焦点を当てた内容で、視聴者にその魅力を伝えています。化け焼きそばの特徴や調理方法、味わいについての情報が含まれており、興味を持つ人々にとって有益な内容となっています。' where id = 'Eu_4e2ROyYtbrgeOQMsqO';
update content_bodies set title = 'Suzunoya, Bake Yakisoba', description = 'This video introduces Suzunoya and Bake Yakisoba.' where id = 'UR1sE6dtptLVNHp7Ingx-';
update content_bodies set title = '黒石つゆ焼きそば「すずのや」', description = 'この動画では、黒石つゆ焼きそば「すずのや」について紹介しています。' where id = 'NpFQdUlfefRP95Ejc4OKA';
update content_bodies set title = 'Kuroishi Tsuyu Yakisoba ''Suzunoya''', description = 'This video introduces Kuroishi Tsuyu Yakisoba ''Suzunoya''.' where id = 'A6ktfaiWdFuyE1OzxG8TS';
update content_bodies set title = '江戸時代から、弘前市民に愛される「川越黄金焼店」', description = 'この動画では、江戸時代から弘前市民に愛され続けている「川越黄金焼店」について紹介しています。' where id = '26vkVhsVmViTsYMoU3cii';
update content_bodies set title = 'Kawagoe Kogane Yaki Shop Loved by Hirosaki Citizens Since the Edo Period', description = 'This video introduces the ''Kawagoe Kogane Yaki Shop,'' which has been cherished by the citizens of Hirosaki since the Edo period.' where id = 'zClVy4WmTliRNgMPEBhYJ';
update content_bodies set title = '津軽百年食堂、そば処「三忠食堂」', description = 'この動画では、津軽百年食堂にあるそば処「三忠食堂」について紹介しています。' where id = 'K7xFB4reWsFC73DMC7Q7X';
update content_bodies set title = 'Tsugaru Hyakunen Shokudo, Soba Restaurant ''Miyachudo''', description = 'This video introduces Tsugaru Hyakunen Shokudo, a soba restaurant named ''Miyachudo''.' where id = 'JbgEwCe_43UWFhYC8D39L';
update content_bodies set title = '又鬼（マタギ）', description = '工藤光治さんは、マタギとして銃を手放すという苦渋の決断をしました。しかし、彼は今でもほぼ毎日山を歩き続けています。彼はマタギがどのようにクマを捕まえるのか、山の中での生活、そして山の神について語ります。' where id = 'qOalPowbc8gnBGTXTE_zH';
update content_bodies set title = 'Matagi', description = 'Kudo Koji has made the difficult decision to put down his gun, a significant choice for a Matagi. Despite this, he continues to walk in the mountains almost every day. He shares insights on how Matagi hunt bears, their way of life in the mountains, and the significance of the mountain gods.' where id = 'kwJGIYpsJXy42JdyuBqHL';
update content_bodies set title = '絶景！幻想的な雲海　～ツエノ峰～', description = '雲海とは、山などの高い位置から見下ろしたときに、雲が広がって海のように見える現象です。この絶景は、特定の天候条件が整わないと見ることができないため、非常に珍しいものです。三重県熊野市のツエノ峰では、11月から2月の晴れた早朝に雲海が出現しやすく、前日夜と当日朝の寒暖差が大きいほど出現率が高まります。天候を確認して、ぜひ訪れてみてください。' where id = 'aFs4JDWdqmdL_aqWyDW3l';
update content_bodies set title = 'Spectacular! The Enchanting Sea of Clouds - Tsuenomine', description = 'The sea of clouds, or ''unkai'' in Japanese, is a breathtaking sight that occurs when clouds spread out below from a high vantage point, resembling a vast ocean. This rare phenomenon can only be witnessed under specific weather conditions. At Tsuenomine in Kumano City, Mie Prefecture, the sea of clouds is most likely to appear during clear early mornings from November to February. The likelihood increases with significant temperature differences between the previous night and the morning of the observation. Be sure to check the weather and plan your visit!' where id = 'xFn1zvrxRZyxCxpxa0dms';
update content_bodies set title = '風間浦鮟鱇、めがった～（おいしかったー）', description = '作家・大岡玲さん、浦風親方、カメラマン・松隈直樹さん、紀行作家・山内史子さんの4人が参加する「冬の青森旅」シリーズの第4回目で、風間浦鮟鱇に焦点を当てています。地元の美味しい料理や食文化を楽しむ様子が描かれています。' where id = 'eiTNP3hEyNQ-X_pbQ1Aor';
update content_bodies set title = 'Kazamaura Anko, Delicious!', description = 'This is the second part of the ''Winter Aomori Trip'' series featuring writer Rei Ooka, sumo wrestler Ura Kaze, photographer Naoki Matsukuma, and travel writer Fumiko Yamauchi. The focus is on Kazamaura Anko, highlighting the culinary experiences and the enjoyment of the local delicacies.' where id = 'RCkI5itnlZSMNKpgScjyY';
update content_bodies set title = '～梅～　三重梅めぐり　鈴鹿の森庭園', description = '三重県は梅の名所であり、約200本の見事なしだれ梅がある「鈴鹿の森庭園」には、日本最古とされる呉服しだれ「天の龍」も含まれています。この庭園では、日本の伝統園芸文化の一つである「仕立て技術」の存続と普及を目的とした研究栽培が行われています。梅の見頃に合わせた時期のみ一般公開され、夜間のライトアップも実施されています。' where id = 'c74HesCRhDR0aioO0rXa2';
update content_bodies set title = 'Ume Blossoms: Mie Ume Tour at Suzuka no Mori Garden', description = 'Mie Prefecture is known for its plum blossoms, featuring approximately 200 stunning weeping plum trees, including the ancient ''Amanoryu,'' believed to be the oldest in Japan. Suzuka no Mori Garden conducts research cultivation to preserve and promote the traditional Japanese horticultural technique known as ''shitate'' (training). The garden is open to the public only during the plum blossom season and offers nighttime illuminations.' where id = 'QnG_QLLSSCrwmg5eoJHaV';
update content_bodies set title = '祖母・傾・大崩ユネスコエコパークPR動画（30秒バージョン）', description = '宮崎県と大分県にまたがる「祖母・傾・大崩ユネスコエコパーク」は、鋭く尖った山々や切り立った崖、美しい渓谷など、独特な景観を持っています。この地域は世界にその価値を認められた魅力がいっぱいです。ぜひ訪れてみませんか？' where id = 'j-eG_-pob5yn8t4IszrEN';
update content_bodies set title = 'Sobo, Kake, and Okue UNESCO Eco-Park PR Video (30-Second Version)', description = 'The Sobo, Kake, and Okue UNESCO Eco-Park, spanning Miyazaki and Oita Prefectures, features unique landscapes with sharply pointed mountains, steep cliffs, and beautiful valleys. Why not visit this region, recognized globally for its rich value and charm?' where id = 'D1rt6oGXYXZ_OrjH68K4N';
update content_bodies set title = '秋田県 乳頭温泉郷 日帰り温泉 7選', description = '乳頭温泉郷は、秋田県に位置する有名な温泉地で、美しい自然環境とリラックスできる温泉体験が魅力です。本記事では、地域内の日帰り利用が可能な温泉を7つ紹介しており、訪れる人々に温泉の癒し効果を楽しむための多様な選択肢を提供しています。それぞれの温泉は独自の特徴や設備を持ち、ゲストがリラックスできる完璧な場所を見つけやすくなっています。また、温泉体験に関連するSNSや商品へのリンクも含まれており、訪問者の全体的なエンゲージメントを高めています。' where id = 'Ffc6ZAP0BP-zEBenP79y6';
update content_bodies set title = 'Top 7 Day Onsen in Nyuto Onsen-kyo, Akita', description = 'Nyuto Onsen-kyo is a renowned hot spring area in Akita, Japan, known for its beautiful natural surroundings and relaxing onsen experiences. This article highlights the top seven day-use onsens in the region, providing visitors with a variety of options to enjoy the therapeutic benefits of the hot springs. Each onsen offers unique features and amenities, making it easy for guests to find the perfect spot to unwind. Additionally, the article includes links to social media and merchandise related to the onsen experience, enhancing the overall engagement for visitors.' where id = 'jxdoC3AthYStvcyHd8PuT';
update content_bodies set title = '長野県 霊泉寺温泉 日帰り温泉 ３選', description = '霊泉寺温泉は、長野県に位置する人気の温泉地で、リラックスできる温泉が魅力です。この記事では、日帰りで利用できるおすすめの温泉を3つ紹介しており、訪れる人々が自然の美しさを楽しみながらくつろげる機会を提供しています。また、著者はインスタグラムアカウントへのリンクを共有し、日本の秘湯を広めるためのオリジナルオレンジタオルの販売も行っています。タオルは複数のセットで購入可能です。' where id = 'j643ZEVaZZ_LmuKupE_qI';
update content_bodies set title = 'Top 3 Day Onsen in Reisenji, Nagano', description = 'Reisenji Onsen is a popular destination in Nagano, known for its relaxing hot springs. The article highlights three recommended day-use onsens in the area, providing visitors with a chance to unwind and enjoy the natural beauty of the region. Additionally, the author shares links to their Instagram account and offers original orange towels for sale, which can be purchased in various sets. These towels are part of a campaign to promote hidden hot springs in Japan.' where id = 'raGPTQ3FkVmMvKPXXcSgH';
update content_bodies set title = '酸ヶ湯温泉の湯治場', description = '酸ヶ湯温泉は、昔から多くの湯治客に愛されてきました。湯治棟に宿泊し、温泉療養を楽しむことができ、自炊場で自分の料理を作って食べることができます。ここでは、昔と変わらない「湯治場」での過ごし方を紹介します。' where id = 'gWHOwS99lL9ch0H6YoH4F';
update content_bodies set title = 'Sukayu Onsen: A Healing Hot Spring', description = 'Sukayu Onsen has been cherished by many visitors seeking healing for a long time. Guests stay in the healing lodge, enjoy hot spring therapy, and prepare their own meals in the cooking area. This summary introduces the traditional way of spending time at this historic ''healing place.''' where id = 'W1eLqxdHYAFAKSAXvkJ6D';
update content_bodies set title = '高木恭造文学碑前にて by紀行作家・山内史子さん', description = '作家の大岡玲さん、浦風親方、カメラマンの松隈直樹さん、紀行作家の山内史子さんの4人が参加する「冬の青森旅」の第2弾です。今回は今別町高野崎にある高木恭造文学碑を訪れ、その魅力を探ります。' where id = 'nL7KZm5XMMX_8HE9Fp56g';
update content_bodies set title = 'At the Takagi Kyozo Literary Monument by Travel Writer Fumiko Yamauchi', description = 'This is the second volume of the ''Winter Aomori Trip'' featuring four individuals: writer Rei Ooka, sumo wrestler Ura Kaze, photographer Naoki Matsukuma, and travel writer Fumiko Yamauchi. The focus is on the Takagi Kyozo Literary Monument located in Takayanosaki, Imabetsu Town.' where id = 'hfyXeqZnOgxm25wPY_85Q';
update content_bodies set title = '酸ヶ湯温泉', description = '酸ヶ湯温泉は日本一の豪雪観測地点として知られています。酸ヶ湯周辺は一面の銀世界で、息をのむほど美しい景色が広がっています。手つかずの自然が多く残る小沼や湿原に囲まれた、昔懐かしい山の温泉宿です。' where id = '8yK9i53sfDtbOHXqP58OZ';
update content_bodies set title = 'Sukayu Onsen', description = 'Sukayu Onsen is known as the snowiest place in Japan. The area surrounding Sukayu is a breathtaking winter wonderland, covered in a blanket of snow. It is an old-fashioned mountain hot spring inn, surrounded by untouched nature, including the serene Konuma and wetlands.' where id = 'xyyQBscpvR-ccdZKO2oae';
update content_bodies set title = '冬限定「酒のあで雪見列車」運行', description = '星野リゾート青森屋は、青い森鉄道株式会社の協力のもと、2017年1月8日から2月26日までの毎週日曜日に、三沢駅から青森駅まで「酒のあで雪見列車」を運行します。この列車では、青森の地酒と停車駅の名産珍味「あで」（青森の方言で「つまみ」の意味）を楽しみながら、祭囃子の生演奏を聴くことができます。' where id = '0yu3DOPyF5ev2FktpRQUA';
update content_bodies set title = 'Winter Limited ''Sake and Snow Viewing Train'' Operation', description = 'Hoshino Resort Aomoriya, in collaboration with Aomori Railway Company, will operate the ''Sake and Snow Viewing Train'' every Sunday from January 8 to February 26, 2017. The train departs from Misawa Station and travels to Aomori Station. Passengers can enjoy Aomori''s local sake and unique local delicacies known as ''ade'' (meaning ''snacks'' in the Aomori dialect) while listening to live performances of festival music.' where id = 'Dd9HisXFp1W4_x9TBJ1sA';
update content_bodies set title = '長崎県 小浜温泉 日帰り温泉 5選', description = 'この記事では、長崎県小浜にある日帰り温泉のおすすめ5選を紹介しています。それぞれの温泉の特徴や魅力を簡潔に説明し、訪れる人々がリラックスできる雰囲気や癒しの効果を楽しめることを強調しています。日帰り旅行に最適な温泉として、訪問者にとっての魅力が伝わる内容です。また、Googleマップのリンクや、日本の温泉に関連するInstagramアカウント、商品販売の情報も掲載されています。' where id = 'o_ybN8gJJIGtH3jLprXBa';
update content_bodies set title = 'Top 5 Day Onsen in Obama, Nagasaki', description = 'This article highlights five recommended day-use hot springs in Obama, Nagasaki. It provides a brief overview of each onsen, showcasing their unique features and attractions. Visitors can enjoy the relaxing atmosphere and therapeutic benefits of these hot springs, making them ideal for a day trip. The article also includes links to a Google Maps location for easy navigation and additional resources such as an Instagram account and merchandise related to Japanese hot springs.' where id = 'Xj8yTwngImQhDHNlKD-fE';
update content_bodies set title = 'Surf Slow SAGA, Japan 4K (Ultra HD) - 佐賀市', description = 'この映像は、佐賀市を紹介するもので、監督は栄川裕樹です。音楽は中本直による「Leap in the air」で、タイトルデザインはni-ma graphicsが手掛けています。佐賀市について詳しく知りたい方は、提供されたウェブサイトを訪れることができます。字幕をONにすると、撮影地が表示されます。' where id = 'ghKdSiI69VBiFrHLxirXn';
update content_bodies set title = 'Surf Slow SAGA, Japan 4K (Ultra HD) - Saga City', description = 'This film showcases Saga City in Japan, directed by Yuki Eikawa. It features music titled ''Leap in the air'' by Nao Kakimoto and has title design by ni-ma graphics. Viewers can learn more about Saga City by visiting the provided website. Subtitles can be turned on to display the shooting locations.' where id = 'zRyccOfG3MFklDGSd0Qh-';
update content_bodies set title = '『ことばの贈りもの』〜 東京都商工会女性部連合会 創立40周年記念祝賀会 〜', description = '2024年2月16日、フォレスト・イン昭島館で東京都商工会女性部連合会の40周年を祝う式典・祝賀会が開催されました。この特別な瞬間に、多摩地域や島しょの女性たちがつながりました。会場には全国から駆けつけた各県の女性部会長や、都内27商工会の関係者が集まり、盛大な拍手が送られました。ステージに立った女性たちは、この日を迎えるために何度も練習を重ねてきました。異なる住まいや職種を持ちながらも、感謝の気持ちが一つとなり、見事な花を咲かせました。東京都女性部連合会の創立40周年、おめでとうございます！' where id = 'ZkBbx5ald_lOzPIF8eTsE';
update content_bodies set title = 'Gifts of Words - 40th Anniversary Celebration of the Tokyo Federation of Commerce and Industry Women''s Associations', description = 'On February 16, 2024, a ceremony and celebration were held at the Forest Inn Akishima to commemorate the 40th anniversary of the Tokyo Federation of Commerce and Industry Women''s Associations. Women from the Tama region and the islands connected during this momentous occasion. The venue was filled with representatives from various prefectures and members from 27 commerce associations in Tokyo, who offered warm applause. The women on stage had practiced tirelessly to prepare for this day. Despite their different backgrounds and professions, their shared feelings of appreciation blossomed beautifully. Congratulations on the 40th anniversary of the Tokyo Federation of Women''s Associations!' where id = 'Jr_LLHpovg4lNnPbWWYoh';
update content_bodies set title = '熊野大花火大会2018(熊野市)スターマイン（２）｜観光三重｜三重県の観光・旅行情報', description = '熊野大花火大会のスターマインの動画です。視野に収まりきらない打ち上げ花火は圧巻です！イベント情報はリンクを参照してください。また、観光三重のYouTubeチャンネルでは三重県内の観光や旅行に関する動画をアップしていますので、ぜひチャンネル登録をお願いします。心、身体、魂を癒やす聖地「熊野」の観光情報や、熊野古道伊勢路、伊勢神宮に関する情報もリンクからご覧いただけます。三重県の観光、旅行、イベント、宿泊予約は、観光三重の公式サイトをご利用ください。' where id = 'c3rYBvxBX3O2xK7msn4ox';
update content_bodies set title = 'Kumano Grand Fireworks Festival 2018 (Kumano City) Star Mine (2) | Tourism Mie | Mie Prefecture Travel Information', description = 'This is a video of the star mine from the Kumano Grand Fireworks Festival. The fireworks display is breathtaking, with bursts that cannot be fully captured in view! For more event information, visit the provided link. Additionally, the Tourism Mie YouTube channel features various travel and sightseeing videos from Mie Prefecture, so please consider subscribing. Explore recommended sightseeing spots in Kumano, a sacred place for healing the heart, body, and soul. For more travel information about the Kumano Kodo Iseji and Ise Jingu, check the respective links. For all tourism, travel, events, and accommodation bookings in Mie Prefecture, visit the official Tourism Mie website.' where id = 'T5Dk1yNNyoUsqti-edihV';
update content_bodies set title = 'はるえ食堂', description = '青森市の古川市場に位置する横山商店、通称「はるえ食堂」は、絶品の焼きおにぎりで知られています。' where id = 'w86S8kPiQON5sp-ukaBFA';
update content_bodies set title = 'Harue Shokudo', description = 'Harue Shokudo, also known as Yokoyama Shoten, is located in Aomori City''s Furukawa Market and is famous for its delicious grilled rice balls.' where id = 'EPU1J-k1kvWvmHDH4gG-H';
update content_bodies set title = '古川市場のっけ丼', description = 'のっけ丼は青森魚菜センターで提供される丼料理で、市場に並ぶさまざまな食材を少しずつ購入して楽しむことができます。自分の好みに合わせて好きな具材を好きな量だけ選べるため、一人でも仲間やカップル、家族と一緒でも楽しむことができます。' where id = 'DNEt_SWpF5uCznuxnKLNW';
update content_bodies set title = 'Nokke Don at Furukawa Market', description = 'Nokke Don is a type of rice bowl available at the Aomori Fish and Vegetable Center, where customers can buy small portions of various items displayed in the market. This allows individuals, groups, couples, and families to enjoy their favorite ingredients in their preferred quantities.' where id = 'jwXQf4KAhPJ7ReLPTH46v';
update content_bodies set title = 'Go Slow SAGA, 日本 - 文化 -', description = '佐賀市の文化や歴史的な場所を紹介する内容です。動画では、浄土寺の大壁画、旧久富家、佐賀城本丸、幕末・維新の八賢人おもてなし隊などの重要なスポットが紹介されています。また、佐嘉神社、新北神社、HAGAKURE酒バー、佐賀ライトファンタジーイベントも見どころです。' where id = 'mUMjVnxvU3GNafBAVsN6f';
update content_bodies set title = 'Go Slow SAGA, Japan - Culture -', description = 'Discover SAGA City, Japan, through various cultural and historical sites. The video showcases significant locations such as Jodoji Temple with its large wall painting, the former Kudo family residence, Saga Castle''s main keep, and the hospitality team of the Eight Wise Men from the Bakumatsu and Meiji periods. Other highlights include Saga Shrine, Shin-Kita Shrine, HAGAKURE Sake Bar, and the Saga Light Fantasy event.' where id = 'rtGayIQLtlHlDF4BRskfK';
update content_bodies set title = '210602 NHK 首都圏ネットワーク ちかさとコレクション', description = '新島では、年間100トン以上の海洋ゴミが流れ着き、美しい景観が損なわれる大問題となっています。漁業の水揚げ量も減少し、漁業や水産加工業は厳しい状況に直面しています。このままでは、海と共に生きてきた島の暮らしが危機に瀕する可能性があります。そこで、新島水産加工業協同組合は、伝統食「くさや」を受け継ぎ、海と共に生きる暮らしを未来へつなぐ活動を開始します。第一弾として、アルミ製洗濯バサミ「HOSSY」を全家庭に配布し、プラスチックごみを減らすことを目指します。' where id = 'y1KSOxqgbAR1fOy4zI3F7';
update content_bodies set title = '210602 NHK Tokyo Metropolitan Network Chikasato Collection', description = 'The New Island Mirai Project addresses the pressing issue of marine debris, with over 100 tons washing ashore annually, threatening the island''s beautiful landscape and fishing industry. As fish catches decline, the local fishing and seafood processing sectors face significant challenges. To combat this, the New Island Fisheries Processing Cooperative is committed to preserving the traditional food ''kusaya,'' which is derived from the ocean''s bounty. Their initiative includes distributing 20 aluminum clothespins, ''HOSSY,'' to every household on the island, aiming to reduce plastic waste and promote a sustainable lifestyle that honors the island''s connection to the sea.' where id = '5L3SoqkQ6_aEQCq9zZzFo';
update content_bodies set title = '【新島】新しい、でつながる島 2022', description = '新島ベロタクシー「ホヌ」は、人と人、人と場所をつなぐ乗り物です。ハワイ語で海亀を意味する「ホヌ」という名前は、亀のようにゆったりとした走行を表現しています。このプロジェクトは、島内のつながりを強化することを目的としています。' where id = '38BxgOsP23jLvr9jiAATB';
update content_bodies set title = 'Niijima: A New Island Connected in 2022', description = 'Introducing the Niijima Velotaxi ''HONU'', a vehicle designed to connect people and places. Named ''HONU'' after the Hawaiian word for sea turtle, it reflects the leisurely pace of its travel, akin to that of a turtle. This project aims to enhance connectivity on the island.' where id = '-d4P3FrGAQzBlmfkpxnr9';
update content_bodies set title = 'キャッシュレスアイランド in 式根島', description = '新島村では、電子決済サービスの普及に向けた取り組みが始まっています。そこで、キャッシュレスが進んでいる式根島を訪れ、実際に導入している方々の声を集めました。キャッシュレス導入を検討している方は、ぜひご覧ください。撮影に協力してくださった方々（順不同）：藤井サービス工業、式根島観光協会、民宿清水屋、池村商店、ファミリーストアみやとら、民宿かねやま。撮影・編集：NUMA FILMS。協力：一社）アットアイランド。制作：新島村商工会。' where id = '2fYxpUKlDw4WaWt-8eO3C';
update content_bodies set title = 'Cashless Ireland in Shikine Island', description = 'The Niijima Village is taking steps towards the promotion of electronic payment services. To explore this initiative, we visited Shikine Island, which is ahead in cashless transactions, and gathered voices from those who have implemented these services. If you are considering the introduction of cashless payments, please take a look. Special thanks to the following for their cooperation (in no particular order): Fujii Service Industry, Shikine Island Tourism Association, Minpaku Shimizuya, Ikemura Store, Family Store Miyatora, and Minpaku Kaneyama. Filming/Editing: NUMA FILMS. Cooperation: At Island Association. Production: Niijima Village Chamber of Commerce.' where id = 'YdXb2bSauRsX8QjoiaGfT';
update content_bodies set title = '斎宮歴史博物館：土器チャレンジ(明和町)', description = '斎宮歴史博物館では、土器の組み立て体験ができる「土器チャレンジ」が開催されています。この体験では、二人一組で競い合うことができ、楽しみながら土器作りの技術を学ぶことができます。観光の一環として、家族や友人と一緒に参加するのにぴったりのアクティビティです。' where id = 'j37f1vKeAp49xQ_mU5GVy';
update content_bodies set title = 'Saiku Historical Museum: Pottery Challenge (Meiwa Town) | Tourism Mie | Mie Prefecture Travel Information', description = 'At the Saiku Historical Museum, you can experience a pottery assembly challenge. You can compete with another person!' where id = 'I98lXMVEH927MbWVCPqSi';
update content_bodies set title = '『ことばの贈りもの』　〜フラでつなぐ 東京諸島の未来〜', description = 'この動画コンテンツは、東京にある11の島の人々や、島にゆかりのある方々と共に未来を想像し、創造することを目的としたプロジェクトです。各島の独自の文化を表現したフラのパフォーマンスが含まれており、2022年3月19日に開催された第4回日本国際観光映像祭で日本部門観客賞を受賞しました。振付は上原まき、音楽は藤井恵が担当し、編曲は藤木英史が行っています。このプロジェクトは東海汽船株式会社の協力を得て、多くの方々の支援を受けています。' where id = 'HDTvrMDuiC2xg4HtokgKF';
update content_bodies set title = 'Gifts of Words: Connecting the Future of Tokyo Islands through Hula', description = 'This video project aims to envision and create a future together with the islanders and those connected to the islands of Tokyo, which consist of 11 islands. The project includes various hula performances from different islands, showcasing their unique cultural expressions. Notably, the project received the Audience Award in the Japanese category at the 4th Japan International Tourism Film Festival on March 19, 2022. The video features choreography by Maki Uehara and music by Megumi Fujii, with arrangements by Eiji Fujiki. The project is supported by Tokai Kisen Co., Ltd. and involves contributions from many individuals.' where id = '72ILIyM7DUwk9KiHoHzRB';
update content_bodies set title = '山形県 湯田川温泉 日帰り温泉 ３選', description = '湯田川温泉は、山形県に位置する人気の温泉地で、リラックスできる雰囲気と癒しの湯が魅力です。本記事では、湯田川で楽しめる日帰り温泉の中から特におすすめの3つを紹介しています。それぞれの温泉は独自の特徴や設備を持ち、日帰り旅行に最適です。また、温泉体験に関連するSNSやオリジナルタオルの販売リンクも掲載されています。湯田川温泉は、自然の美しさを楽しみながらリフレッシュしたい方にぴったりの場所です。' where id = 'jZP2XJDKeNBw0hOxUOnDz';
update content_bodies set title = 'Top 3 Day Onsen in Yutagawa, Yamagata', description = 'Yutagawa Onsen is a popular hot spring destination in Yamagata Prefecture, known for its relaxing atmosphere and therapeutic waters. This article highlights three top day-use onsens in Yutagawa, providing visitors with options to enjoy a rejuvenating experience. Each onsen offers unique features and amenities, making them ideal for day trips. The article also includes links to social media and merchandise related to the onsen experience, such as original towels for sale. Overall, Yutagawa Onsen is a perfect getaway for those looking to unwind and enjoy the natural beauty of the region.' where id = '6ej418buqLlqMngsN9AXK';
update content_bodies set title = '新島', description = '新島では、あなた自身が島の楽しみ方を決めることができます。美しい海の色や澄んだ砂の粒に出会い、白ママ断崖の絶景を堪能し、コーガ石に刻まれた島の暮らしを知ることができます。また、オープンマインドな島人たちと交流し、あなたが見つけた宝物を共に楽しむことができます。この島は出会いの連鎖を生み出し、新しい扉を開く場所です。新しい人生の視点をもたらす新島へようこそ。' where id = 'IpCQ04KdvzBzUXHe3E9xf';
update content_bodies set title = 'A trip to Niijima Island', description = 'Niijima Island offers a unique experience where you decide how to enjoy the island. Encounter the stunning colors of the sea and the clear grains of sand. Explore the breathtaking 7-kilometer white cliffs and the lifestyle etched in Koga stones. Engage with the open-minded locals who are eager to share in the treasures you discover. This island fosters a chain of connections that opens new doors, leading to a fresh perspective on life. Welcome to Niijima, a new island of possibilities.' where id = '_Tjvx_uy1S63ZEUx9AeZ1';
update content_bodies set title = '【式根島】 A Trip to Shikinejima Island', description = '式根島は、仕事と遊びを融合させた新しいライフスタイルを提案する場所です。週末や一週間を仕事とバケーションの両立を図る「ワーケーション」を通じて、生活のシフトチェンジを促します。東京からジェット船でわずか3時間の距離にあり、懐かしさと品格を兼ね備えた島です。紺碧の海や青空、24時間利用可能な温泉、豊かな自然に囲まれたこの島で、人生の大切な価値を見直すことができます。共に新しい暮らし方や働き方を模索する仲間を歓迎し、東京と島のデュアルライフや移住を促進しています。式根島で未来づくりに参加しませんか。' where id = 'jyiyEUIj_0JhoTMDvEjJD';
update content_bodies set title = 'A Trip to Shikinejima Island', description = 'Shikinejima Island offers a unique blend of work and leisure, promoting a lifestyle shift through ''workation''—balancing work and vacation. Located just three hours by jet ferry from Tokyo, the island combines nostalgic charm with modern work styles. Surrounded by a deep blue sea, clear skies, and abundant nature, Shikinejima provides a serene environment ideal for re-evaluating life''s essential values. The island invites those who share this vision to explore new ways of living and working together. Whether for dual living between Tokyo and the island or permanent relocation, Shikinejima welcomes everyone to participate in shaping a future that harmonizes work and life.' where id = 'ytAya-TeMPpMeLpXbwYh8';
update content_bodies set title = '新島 -とびきりの夏を-', description = '新島・式根島の映像のチカラコンテスト2019 FINALにエントリーされた作品です。チーム名は「世界平和」です。' where id = 'bxvD5IWdMK_RV_wBlQSH8';
