update content_bodies set title = 'Niijima and You', description = 'This is an entry for the 2019 Final of the Niijima and Shikinejima Video Power Contest by the team KMT45.' where id = 'KRFVxaUBz0LXzrBlUClc_';
update content_bodies set title = '映像のチカラコンテスト in NIIJIMA&SHIKINEJIMA TOKYO のライブ ストリーム', description = 'この動画は、NIIJIMAとSHIKINEJIMAで開催される映像のチカラコンテストのライブストリームについて紹介しています。イベントの内容や参加者の作品がどのように配信されるかに焦点を当てており、視聴者にリアルタイムでの体験を提供します。映像の力を通じて、参加者の創造性や技術がどのように表現されるのかを楽しむことができる機会です。' where id = '78OC0kuoO6DGroDPfy1hC';
update content_bodies set title = 'Live Stream of the Power of Video Contest in NIIJIMA & SHIKINEJIMA TOKYO', description = 'This video introduces the live stream of the Power of Video Contest held in NIIJIMA & SHIKINEJIMA TOKYO.' where id = 'Z5L-2xLMmx_haaDxdVCFy';
update content_bodies set title = '【式根島】映像のチカラコンテスト2018 『SHIKINE.zip』', description = 'チーム名は早稲田大学空間映像ゼミナールです。このコンテストは、式根島を舞台にした映像制作を通じて、映像の力を探求するイベントです。参加チームは、独自の視点で式根島の魅力を表現し、観客に新たな発見を提供します。早稲田大学のチームは、空間映像に特化した技術と創造性を駆使して、印象的な作品を制作することを目指しています。' where id = 'Gdy0sj8fPREA6S3ln5VMT';
update content_bodies set title = 'Shikine Island Video Power Contest 2018 ''SHIKINE.zip''', description = 'Team Name: Waseda University Spatial Video Seminar' where id = 'PqWKRsYZ08eP0DIMlO31C';
update content_bodies set title = '【新島】映像のチカラコンテスト2018 『New TOKYO』', description = 'チーム名はN4で、日本工学院専門学校に所属しています。このコンテストは、映像制作の力を競うイベントであり、参加者は独自の視点で新しい東京を表現することを目指しています。' where id = '0s4tQSZUf_HK22enTFP8J';
update content_bodies set title = 'New Island Video Power Contest 2018 ''New TOKYO''', description = 'Team Name: N4 (Nihon Kogakuin College)' where id = 'F1JVT0f9QuvBUEqa9zLKQ';
update content_bodies set title = '【新島】映像のチカラコンテスト2018 『＃東京新島物語 ~CITY SIDE~』', description = 'このコンテストは、映像制作を通じて新島の魅力を伝えることを目的としています。参加チームの一つであるTREC Studiosは、山梨県立大学と混合チームで構成されています。彼らは新島の都市側の物語を映像で表現し、観客に新たな視点を提供することを目指しています。' where id = 'lt3n90cufYHEn055Ld_2x';
update content_bodies set title = 'New Island Video Power Contest 2018 ''#Tokyo New Island Story ~CITY SIDE~''', description = 'Team Name: TREC Studios (Yamanashi Prefectural University x Mixed)' where id = '-fLnvQhCbSxARKztAEr3i';
update content_bodies set title = '【新島】映像のチカラコンテスト2018 『＃東京新島物語~ISLAND SIDE~』', description = 'チーム名はTREC Studiosで、山梨県立大学と混合チームによる参加です。このコンテストは、新島をテーマにした映像作品を競い合うイベントであり、参加者は新島の魅力を映像で表現することを目的としています。映像の力を通じて、新島の文化や自然を広く伝えることが期待されています。' where id = 'VWboqO7aWfBCds2qbEReN';
update content_bodies set title = 'New Island: Power of Video Contest 2018 ''#Tokyo New Island Story ~ISLAND SIDE~''', description = 'Team Name: TREC Studios (Yamanashi Prefectural University x Mixed)' where id = 'oHRS9GG-TmCL7VETVflYX';
update content_bodies set title = '【式根島】映像のチカラコンテスト2018 『式根、晴好雨奇』', description = 'このコンテストは、式根島を舞台にした映像作品を競うイベントであり、2018年に開催されました。参加チームの一つは、早稲田大学の空間映像ゼミナールです。彼らは、式根島の自然や文化を映像で表現し、観客にその魅力を伝えることを目指しています。コンテストは、映像制作の技術や創造性を発揮する場として、多くの参加者にとって貴重な経験となっています。' where id = '2JWRFVPAbvjfmRgao09RE';
update content_bodies set title = 'Shikinejima Video Power Contest 2018 ''Shikine, Sunny, Good Rain, Strange''', description = 'Team Name: Spatial Video Seminar (Waseda University)' where id = 'WmUw5ey5z13wUt0by9MDs';
update content_bodies set title = '【新島】映像のチカラコンテスト2018 『これが新島』', description = 'チーム名はLeviathanで、立教大学に所属しています。このコンテストは新島をテーマにした映像作品を競い合うイベントであり、参加者は新島の魅力を映像で表現することを目的としています。新島の自然や文化、地域の人々の生活を映し出すことで、観客に新島の素晴らしさを伝えることが期待されています。' where id = '4P5MqTiK3bhToRW2UG-KD';
update content_bodies set title = 'Niijima Video Power Contest 2018 ''This is Niijima''', description = 'Team Name: Leviathan (Rikkyo University)' where id = 'jXLR_2Fv-lrMOGLKQHUKj';
update content_bodies set title = '【新島・式根島】 Follow me　〜2017応募作品：最優秀作品〜', description = 'チーム名はBUZZで、東洋大学と城西国際大学の共同制作による作品です。この作品は2017年の応募作品の中で最優秀作品に選ばれました。新島と式根島の魅力を伝える内容で、観光や地域の特色を活かしたアプローチが評価された結果です。BUZZチームは、両大学の学生が協力し、地域の文化や自然をテーマにした作品を制作しました。' where id = 'Qp-yMXcOlUtH3HstQ8UFZ';
update content_bodies set title = 'Niijima and Shikinejima: Follow Me - 2017 Award-winning Work', description = 'Team Name: BUZZ (Toyo University & Josai International University)' where id = 'cKs2M-PXfPKDjtxj6j_Qy';
update content_bodies set title = '【式根島】「式根ベイベー」　〜2017応募作品〜', description = 'チーム名は東京デザイナー学院です。この作品は2017年に応募されたもので、式根島に関連する内容を持っています。具体的な詳細は記載されていませんが、式根島の魅力や特性を表現した作品であると考えられます。' where id = '9PShqvcOwoKPvf4mEwNZ5';
update content_bodies set title = 'Shikine Island: ''Shikine Baby'' - 2017 Submission', description = 'Team Name: Tokyo Designer Academy' where id = 'VmZypjV-NQ-Se3BvWLGLv';
update content_bodies set title = '式根島：また来たいと思ってもらえる島', description = 'これは東京デザイナー学院からの応募作品で、式根島が訪れる人々にまた来たいと思わせる場所でありたいという願いを表現しています。' where id = '-tzt1sdT9KoYZrSJiX47c';
update content_bodies set title = 'Shikinejima: A Place That Makes You Want to Return', description = 'This is a submission from the Tokyo Designer Academy, expressing the desire for Shikinejima to be a place that visitors would want to return to.' where id = 'XetE2CR_LHnnIP6zU0YwH';
update content_bodies set title = '【新島】きっと出会える新しい自分　〜2017応募作品〜', description = 'チーム名はSTAND UP!!で、日本工学院専門学校の作品です。この作品は、新しい自分との出会いをテーマにしており、応募作品として2017年に提出されました。' where id = 'W75aXGrpxHG_-OYr0m5xY';
update content_bodies set title = 'New Self You Will Definitely Meet - 2017 Submission', description = 'Team Name: STAND UP!! (Nihon Kogakuin College)' where id = 'Hln5x5uHGrE5Wixsoi3ND';
update content_bodies set title = '新島', description = 'これは東京デザイナー学院の生徒による作品です。' where id = 'CqxLg_oxDQdPnEPJkzMlO';
update content_bodies set title = 'Welcome to Niijima', description = 'This is a work by a student from the Tokyo Designer Academy.' where id = 'GxZPQUg49SiztUOKVXmKA';
update content_bodies set title = '【式根島】PR動画　～未体験の旅を東京で～', description = '東京の専門学校に、式根島のPR動画製作の依頼が舞い込んだ。この依頼を受けて、冒険心にあふれた5人の男たちが立ち上がる。彼らは新たな旅の体験を求めて、式根島の魅力を伝えるために奮闘する。' where id = 'Xg5xxjh77n73C4U8Zqa-X';
update content_bodies set title = 'Shikinejima PR Video - An Unforgettable Journey in Tokyo', description = 'A request arrived at a vocational school in Tokyo for the production of a PR video for Shikinejima. In response to this request, five adventurous men with a strong sense of adventure decided to take action.' where id = '-aU10tN164EE3Db64pxF8';
update content_bodies set title = '【新島】映像のチカラコンテスト2016最優秀作品『新島　女子旅』', description = 'この映像は、新島に旅行に行く2人の女子を描いています。この作品は、日本工学院専門学校の1年生によって制作されました。' where id = 'xDk41_nMiqzKJ5G2svjoz';
update content_bodies set title = 'Nishima: Best Work of the 2016 Video Power Contest ''Nishima Girls'' Trip''', description = 'The video showcases a trip taken by two girls to Nishima. This work is created by a first-year student from the Nihon Kogakuin College.' where id = 'ElllNGCyTjoLxeiMNRqeA';
update content_bodies set title = '鹿児島県 妙見温泉 日帰り温泉 6選', description = '妙見温泉は、鹿児島県に位置する人気の温泉地で、リラックスできる温泉が魅力です。この記事では、妙見エリアにある日帰り利用が可能な温泉を6つ紹介しており、訪れる人々が自然の美しさを楽しみながらくつろげる機会を提供しています。各温泉はさまざまな設備やユニークな体験を提供しており、日帰り旅行に最適です。また、温泉文化に関連するSNSや商品へのリンクも含まれています。' where id = 'GF_bau8sQ9gV2g748RYO7';
update content_bodies set title = 'Top 6 Day Onsen in Myoken, Kagoshima', description = 'Myouken Onsen is a popular destination in Kagoshima, known for its relaxing hot springs. This article highlights six recommended day-use onsens in the Myoken area, providing visitors with a chance to unwind and enjoy the natural beauty of the region. The onsens offer various amenities and unique experiences, making them ideal for day trips. Additionally, the article includes links to social media and merchandise related to the Japanese hot spring culture.' where id = 'E1lW1I25zXvkgtadyr28k';
update content_bodies set title = '【秋田市プロモーションビデオ②】自然の彩と隣人の温もりに富む「新波」short Ver.', description = '「新波」は雄物川が運んだ文化が花開く場所であり、秋には黄金色の絨毯が広がる「式田」として知られています。この映像は、秋田市のシティプロモーションモデル事業の一環として行われたワークショップを通じて、地域住民が見つけたそれぞれの地区の魅力を詰め込んだものです。「新波」では、雨の日に「洗濯もの入れておいて」と頼める隣人がいて、何があっても助け合う温かいコミュニティが描かれています。春には緑が広がり、秋には黄金の波が心を明るくします。この映像は、秋田市雄和・新波で見つけた大切なことを伝えています。' where id = 'Nna8lmtWvwl06WjtA48gZ';
update content_bodies set title = 'Akita City Promotion Video ②: ''Shinba'' Rich in Nature''s Colors and Neighborly Warmth - Short Version', description = 'The video showcases ''Shinba,'' a place where the culture brought by the Omorogawa River flourishes, and ''Shikida,'' a village that transforms into a golden carpet in autumn. This film is a product of a workshop conducted as part of Akita City''s city promotion model project, where local residents identified and highlighted the unique charms of their respective areas. In ''Shinba,'' neighbors help each other, whether it''s asking to keep laundry inside during rain or providing support in times of need. The vibrant greenery of spring and the bright golden waves of autumn bring joy to the community. The video captures the essence of what is truly important in Akita City''s Yuwa and Shinba.' where id = '0lwnR86caPysgyRZGSx6r';
update content_bodies set title = '【式子島】姉妹旅　〜2017応募作品〜', description = 'チーム名はコンタクトで、日本工学院専門学校に所属しています。この作品は2017年の応募作品であり、姉妹の旅をテーマにしています。' where id = 'pwwYZVjpYHZcQdf-rM0ey';
update content_bodies set title = 'Sister Trip to Shikishima - 2017 Submission', description = 'Team Name: Contact (Nihon Kogakuin College)' where id = 'EairtSIMI7oQ6gU00GMqm';
update content_bodies set title = '【共同湯 公衆浴場】島根県 江津市 有福温泉 全3湯', description = '有福温泉は島根県江津市に位置し、3つの共同浴場を備えています。この温泉地は、訪れる人々にリラックスした体験を提供することで知られています。説明には、Googleマップのリンクが含まれており、簡単にアクセスできるようになっています。また、インスタグラムのアカウントや、オリジナルのオレンジタオルの販売リンクも紹介されています。これらのタオルは「日本秘湯を攻める会」のキャンペーンの一環として販売されており、日本の隠れた温泉を楽しむことを促進しています。' where id = 'EPIO5JJr_ROGv1_Rnsqsr';
update content_bodies set title = 'The three communal bathhouses of Arifuku Onsen in Shimane', description = 'Arifuku Onsen, located in Gotsu City, Shimane Prefecture, features three communal bathhouses. The area is known for its hot springs, providing a relaxing experience for visitors. The description includes links to a Google Maps location for easy navigation, an Instagram account for updates, and various sets of original orange towels available for purchase through Mercari. These towels are part of a campaign by the ''Nihon Hito o Semeru Kai'' group, promoting the enjoyment of Japan''s hidden hot springs.' where id = 'kSDekXi-wcLKZRdbtIVDj';
update content_bodies set title = '秋田美人が秋田フキをＰＲ', description = '秋田美人の象徴である「秋田おばこ」の衣装を身にまとった女子たちが、名物の秋田フキをPRする様子を紹介します。秋田観光レディーの3人は、初めての蕗刈り体験と撮影会に参加しました。また、鹿児島県出身の秋田市地域おこし協力隊の重久愛さんも、地元の秋田おばこの皆さんと共に蕗刈りに挑戦しました。秋田市では、こうした秋田美人たちが伝統を受け継いでいます。' where id = '7JDj0O2XsQhFwU9r6-BSe';
update content_bodies set title = 'Akita Beauties Promote Akita Fuki', description = 'This article introduces women dressed in the traditional costume of ''Akita Obako,'' a symbol of Akita beauty, as they promote the local specialty, Akita Fuki. Three Akita tourism ladies participated in their first experience of fuki harvesting and a photo shoot. Additionally, Ai Shigehisa, a member of the Akita City regional revitalization team from Kagoshima Prefecture, joined local Akita Obako women in the fuki harvesting challenge. In Akita City, these beautiful women are carrying on the tradition.' where id = '3NwZcmyv8ZYxcC6rqOxmj';
update content_bodies set title = '私は、まいこ', description = '女子高生のまいこが舞妓の修行をしながら、秋田市の人々や街に愛着を深めていく成長物語です。秋田市の中心市街地や千秋公園の美しい自然は、あきた舞妓の艶やかな世界観と共鳴しています。「秋田美人」という言葉は日本中に広がっており、あきた舞妓はその気品と伝統を守りながら、千秋公園から秋田の素晴らしさを世界に発信するために努力しています。この作品は、「あきた舞妓」と「秋田美人」の関係をさらに広めることを目的としています。' where id = 'qeboFzpaZZ0T6ryyUYCIQ';
update content_bodies set title = 'I am Maiko', description = 'The story follows a high school girl named Maiko as she trains to become a maiko, deepening her affection for the people and the city of Akita. Through her journey, she grows into an Akita maiko. The beautiful natural scenery of Akita City, particularly in the central urban area and Chuo Park, resonates with the elegant world of Akita maiko. The term ''Akita Bijin'' (beautiful women of Akita) is well-known throughout Japan. The Akita maiko, representing this beauty, strives to uphold elegance and tradition while promoting the wonders of Akita to the world from Chuo Park. This production aims to further highlight the connection between ''Akita maiko'' and ''Akita Bijin.''' where id = 'aucT18zCqe9NKPAe9cCya';
update content_bodies set title = '共同湯 全8湯', description = '鹿児島県霧島市（旧隼人町）には、全8つの公衆浴場「共同湯」があります。これらの浴場は、伝統的な日本の温泉を楽しむためのユニークな体験を提供しており、自然の美しさと文化的な重要性に恵まれた地域です。地元の人々や観光客にとって人気のある目的地となっています。これらの浴場を訪れる際の情報は、GoogleマップやSNSで確認できます。また、日本秘湯を攻める会では、オリジナルのオレンジタオルなどのグッズも販売しており、オンラインで購入可能です。' where id = 'o9XBulyA5Gm2ptRiji5Ys';
update content_bodies set title = 'All 8 Public Bathhouses in Kirishima City, Kagoshima Prefecture', description = 'Kirishima City, located in Kagoshima Prefecture, is home to eight public bathhouses, known as ''共同湯'' (Kyoudou-yu). These bathhouses offer a unique experience for visitors looking to enjoy traditional Japanese hot springs. The area is rich in natural beauty and cultural significance, making it a popular destination for both locals and tourists. For those interested in exploring these bathhouses, additional information can be found on Google Maps and social media platforms. The Japanese Hidden Hot Springs Association also offers original merchandise, including orange towels, available for purchase through various online links.' where id = '99ZHNCjYG-UOuhKPBZZyp';
update content_bodies set title = '千秋公園「はちみつソフト」秋田美人が実食♪', description = '秋田駅前に位置する千秋公園は、四季折々の自然を楽しめる場所です。秋田犬やあきた舞妓に会える観光スポットとしても人気があります。そこで新たに登場した名物「はちみつソフト」を、あきた観光レディーの3人が実食しました。秋田市産のハチミツを使用したこのソフトは、甘すぎずスッキリとした味わいで、今夏話題になること間違いなしです。ぜひお試しください！' where id = 'M38I35SOzxC-p1kwgWpbD';
update content_bodies set title = 'Chishū Park''s ''Honey Soft Serve'' Tasted by Akita Beauties♪', description = 'Located just near Akita Station, Chishū Park offers a chance to enjoy nature throughout the seasons. It is a popular tourist spot where visitors can meet Akita dogs and Akita maiko. A new specialty, ''Honey Soft Serve,'' has been introduced in the park. Three Akita tourism ladies tried it out. Made with honey from Akita City, the soft serve has a refreshing taste that is not overly sweet, making it a hot topic this summer. Be sure to give it a try!' where id = 'OwmtT2mbQUHZuMljK4AQa';
update content_bodies set title = '秋田犬ふれあい処 in千秋公園オープン！', description = '秋田犬とふれあえるスポットが千秋公園二の丸にオープンしました。隣接する売店では秋田犬関連グッズも販売されており、併せて楽しむことができます。設置期間は平成30年6月16日から11月4日までの毎日で、時間は11:00から15:00まで（6月16日は12:30オープン）です。秋田市中心市街地に位置し、常時1頭の秋田犬がふれあい可能で、イベント時には2頭でおもてなしします。ただし、犬の体調管理のため、直接触れることができない場合もありますのでご了承ください。' where id = 'Ii4P6N4198DBFq77f1LdG';
update content_bodies set title = 'Akita Dog Interaction Spot Opens in Chuo Park!', description = 'A new spot for interacting with Akita dogs has opened at the Ninomaru area of Chuo Park. A nearby shop also sells Akita dog-related merchandise for visitors to enjoy. The interaction area is open daily from June 16, 2018, to November 4, 2018, from 11:00 AM to 3:00 PM (with a 12:30 PM opening on June 16). Located in the city center of Akita, there will typically be one Akita dog available for interaction, with two dogs present during special events. Please note that due to the dogs'' health management, direct contact may not always be possible.' where id = 'XLOSSTSU3XSOra9insa1J';
update content_bodies set title = '太平山三吉梵天', description = '毎年1月17日に行われる三吉梵天祭りは、秋田の冬の風物詩であり、邪気を祓い一年の幸を願う祭りです。この祭りでは、力の神にあやかろうとする参加者たちの間で激しい先陣争いが繰り広げられます。' where id = 'Au3T4nWGx587HPOdbx4E-';
update content_bodies set title = 'Taiheizan Mikiyoshi Bonden', description = 'The Mikiyoshi Bonden Festival, held annually on January 17th, is a spectacular winter event in Akita. This festival aims to drive away evil spirits and wish for a prosperous year. Intense competitions among participants take place as they strive to honor the god of strength.' where id = '5h4D2VK0uI4fpAE_v55jU';
update content_bodies set title = '山形県 小野川温泉 共同湯', description = '小野川温泉には、訪れる人々に日本の伝統的な温泉体験を提供する全3つの公衆浴場があります。山形県に位置するこの温泉は、静かな雰囲気と癒しの湯で知られています。訪問者は、Googleマップを利用して簡単にアクセスできます。また、小野川温泉のコミュニティは、インスタグラムアカウントを通じて温泉の美しさや魅力を発信しています。さらに、日本秘湯を攻める会のオリジナルオレンジタオルが、さまざまなセットで購入可能なリンクも提供されています。これらのタオルは、小野川温泉でのリラックスした体験を思い出すための素晴らしいお土産となるでしょう。' where id = 'n6HwH0Deij8eK1NvvvkWz';
update content_bodies set title = 'Public Baths in Onogawa Onsen, Yamagata Prefecture', description = 'Onogawa Onsen features three public baths, offering visitors a chance to experience traditional Japanese hot springs. Located in Yamagata Prefecture, this onsen is known for its serene atmosphere and therapeutic waters. The area is accessible via Google Maps, providing easy navigation for those wishing to visit. Additionally, the Onogawa Onsen community has embraced social media, with an Instagram account showcasing the beauty and charm of the hot springs. For those interested in souvenirs, original orange towels from the Nihon Hito Onsen Attack Club are available for purchase in various sets through provided links. These towels serve as a perfect memento for visitors to remember their relaxing experience at Onogawa Onsen.' where id = '0k3ACmxcZEyZ2-xOM0-w7';
update content_bodies set title = '秋田ノーザンブレッツＰＲムービー（2021年）～ショートver ～', description = '2021年に制作された秋田ノーザンブレッツのPR動画です。この動画は、チームの魅力を伝える内容となっています。試合やその他の情報については、一般社団法人秋田ノーザンブレッツラグビーフットボールクラブの公式ウェブサイト（www.northern-bullets.com）にお問い合わせください。' where id = 'oD-yaVPeyHsfxarKfUXu_';
update content_bodies set title = 'Akita Northern Bullets PR Movie (2021) - Short Version', description = 'This is a PR video for the Akita Northern Bullets from 2021. For inquiries regarding matches and other information, please contact the Akita Northern Bullets Rugby Football Club at www.northern-bullets.com.' where id = 'eJ70cQuiRfUhr6EC8JYRW';
update content_bodies set title = '山形県 蔵王温泉の共同湯', description = '蔵王温泉は、山形県に位置する3つの公衆浴場（共同湯）で知られています。この地域は、伝統的な日本の温泉体験を求める訪問者に人気があります。また、日本秘湯を攻める会のオリジナルオレンジタオルが、いくつかのリンクを通じて購入可能です。タオルは2本、3本、5本のセットがあり、さまざまなニーズや好みに応じて選べます。' where id = 'kI55nCYz_dLw6xXcjDAVX';
update content_bodies set title = 'Public Bathhouses in Zao Onsen, Yamagata Prefecture', description = 'Zao Onsen is known for its three public hot springs (Sotoyu) located in Yamagata Prefecture. The area is popular among visitors seeking traditional Japanese hot spring experiences. For those interested in unique merchandise, original orange towels from the Nihon Hito Onsen Attack Club are available for purchase through various links provided. These towels come in sets of two, three, and five, catering to different needs and preferences.' where id = 'LvpAZ7asdAHmGl99UNmcC';
update content_bodies set title = '秋田市プロモーションビデオ「人生は旅」短編版', description = '「人生は旅」は、地元のカップルの視点から秋田市を体験できるドラマ仕立ての観光プロモーションビデオです。このビデオは、毎日を旅のように好奇心を持って過ごし、小さな発見を楽しむことの大切さを伝えています。秋田市は多くの人々のお気に入りの体験や魅力に満ちており、視聴者に「秋田を旅してみませんか？」と呼びかけています。ビデオのメインバージョンは15分、施設情報版は5分です。出演は和楽座、テーマソングはhalosの「君を呼ぶ声」で、秋田市と市民の協力により制作されました。' where id = 'XTVltbham88__BYtER3nC';
update content_bodies set title = 'Akita City promotion video ''Life is a Journey'' Short version', description = '''Life is a journey'' is a dramatized tourism promotion video that offers an immersive experience of Akita City through the perspective of a local couple. The video encourages viewers to approach each day with curiosity and to appreciate the small discoveries that can brighten their lives. Akita City is depicted as a place filled with beloved experiences and attractions, inviting viewers to ''travel'' and explore its offerings. The main version of the video runs for 15 minutes, while a shorter facility information version is available for 5 minutes. The project features performances by Warabiza and includes the theme song ''Kimi wo yobu koe'' by halos, produced in collaboration with the citizens of Akita and created by Akita City and VISUALSPACE.INC.' where id = 'J5u93u6kg4UJobUj7DoJC';
update content_bodies set title = '千秋公園・秋田城跡歴史資料館・如斯亭', description = 'この文章では、秋田市の歴史と文化、そして自然の美しさを象徴する3つの施設、千秋公園、秋田城跡歴史資料館、如斯亭を紹介しています。' where id = 'hUzRn4xWcJmS_FlRpIJaI';
update content_bodies set title = 'Chūō Park, Akita Castle Ruins Historical Museum, and Joshi-tei', description = 'This text introduces three facilities that represent the history and culture of Akita City, as well as its natural beauty.' where id = 'RYVySva5PAv12Fe1A4eOp';
update content_bodies set title = '雄物川花火大会', description = '雄物川花火大会は、秋田市の夏の夜空に浮かぶダイナミックな花火の祭典です。このイベントは毎年8月に開催され、多くの観客が訪れます。' where id = 'B4oS0YhlawxRLqXZ0K6Md';
update content_bodies set title = 'Omorogawa Fireworks Festival', description = 'The Omorogawa Fireworks Festival is a dynamic fireworks display that lights up the summer night sky in Akita City. It is held annually in August.' where id = 'XJ0urV88dyObe5NyzXtS-';
update content_bodies set title = '大正寺おけさ', description = '大正寺おけさは、九州地方で受け継がれてきた「ハイヤ節」を起源とする貴重な民謡文化です。この民謡は北前船によって広まったとされ、地域の文化的なアイデンティティを形成しています。また、日本遺産に登録されたストーリー「荒波を越えた男たちの夢が紡いだ異空間～北前船寄港地・船主集落～」の中で、重要な文化財として位置づけられています。' where id = 'NfXTNuoPE6bSuT0-0J-Ip';
update content_bodies set title = 'Taisho-ji Okesa', description = 'Taisho-ji Okesa is a valuable folk song culture that originated from the ''Haiya-bushi,'' which has been passed down in the Kyushu region. It is said to have spread through the Kitamae-bune (Northbound ships). This folk song is also positioned as a cultural asset within the story registered as a Japanese heritage, ''The Dreams of Men Who Overcame Rough Waves - The Port Towns and Shipowners of Kitamae-bune.'' (Produced by Akita City Tourism Promotion Division)' where id = 'RVK99TeZGRyHVop6Pfla0';
update content_bodies set title = '【共同湯 公衆浴場】長野県 角間温泉 共同湯 全3湯', description = '角間温泉には、長野県に位置する3つの公衆浴場があります。この地域は自然の温泉で知られており、訪れる人々にリラックスした体験を提供します。場所はGoogleマップで確認でき、インスタグラムや温泉に関連する商品へのリンクもあります。商品には、さまざまなセットで販売されているオリジナルのオレンジタオルが含まれています。この説明は、温泉の魅力を強調し、角間温泉のユニークな提供物を探求するよう訪問者に促しています。' where id = 'T_90qw-9R49cPPJSA--Q7';
update content_bodies set title = 'Kakuma Onsen Public Baths, Nagano Prefecture: All 3 Hot Springs', description = 'Kakuma Onsen features three public hot springs located in Nagano Prefecture. The area is known for its natural hot springs, providing a relaxing experience for visitors. The location can be found on Google Maps, and there are links to Instagram and merchandise related to the hot springs. The merchandise includes original orange towels available in various sets. The description emphasizes the appeal of the hot springs and encourages visitors to explore the unique offerings of Kakuma Onsen.' where id = 'G7UEd7D9-0y_SejBwYNy1';
update content_bodies set title = '元気になりに、いらっしゃい。【宮崎市】宮崎食堂ムービー｜一人旅編', description = '宮崎市の魅力を発信する「宮崎食堂」プロジェクトのムービーが公開されました。このムービーでは、青い空の下で海や山の豊かな自然に触れ、地元のローカル食や人との交流を通じて元気を取り戻す様子が描かれています。一人旅編では、ビジネスパーソンがカフェで「宮崎食堂」ののれんに出会い、浜辺のバーガーハウスでテレワークをしながら、地元の人々から宮崎の文化や食を学び、サーフィンを楽しむ様子が描かれています。明るい日差しの中で仕事を終えた後は、浜辺でリラックスし、宮崎の温かさや自然の豊かさを感じながら充実した時間を過ごします。「宮崎食堂」は、食や自然、人の温かさを通じて宮崎市の魅力を伝えるプロジェクトであり、訪れる人々を元気にすることを目指しています。' where id = 'VoBH_Vdvw-CslHH_djABf';
update content_bodies set title = 'Come to Get Energized: Miyazaki Dining Movie - Solo Travel Edition', description = 'A new movie has been created to promote the charm of Miyazaki City through the ''Miyazaki Dining'' project. It showcases how visitors can rejuvenate by experiencing the rich nature of the sea and mountains under the blue sky, enjoying local cuisine, and interacting with the warm-hearted locals. In the solo travel edition, a busy businessperson unexpectedly encounters the ''Miyazaki Dining'' noren (curtain) at a café. Drawn in, they find themselves working remotely at a beach burger house, learning about local food and the ''dareyami'' culture from friendly locals, and even catching waves with surfers. After a productive work session in the bright sunshine, they relax on the beach, fully embracing the warmth of the people and the abundance of food and nature. The project aims to highlight Miyazaki''s appeal as a ''dining hall'' where delicious local offerings come together, inviting everyone to visit and feel revitalized.' where id = 'amXZ1yFN87K2EUWPr8zew';
update content_bodies set title = '秋田市プロモーションビデオ「人生は旅」施設情報版', description = '「人生は旅」は、地元のカップルの視点から秋田市を体験できるドラマ仕立ての観光プロモーションビデオです。このビデオは、毎日を旅のように好奇心を持って過ごし、小さな発見を楽しむことの大切さを伝えています。秋田市は多くの人々のお気に入りのスポットで満ちており、視聴者に「秋田を旅してみませんか？」と呼びかけています。ビデオのメインバージョンは15分、短い30秒のバージョンも用意されています。演者は和楽座で、テーマソングはhalosの「君を呼ぶ声」です。秋田市とVISUALSPACE.INCの共同制作で、秋田市民とのコラボレーションによって作成されました。' where id = 'UONzKlOGNhFRLelb6ceYL';
update content_bodies set title = 'Akita City promotion video ''Life is a Journey'' Facility information version', description = '''Life is a Journey'' is a dramatized tourism promotion video that offers an immersive experience of Akita City through the perspective of a local couple. The video encourages viewers to approach each day with curiosity and to appreciate the small discoveries that can brighten their lives. Akita City is depicted as a place filled with beloved attractions and experiences, inviting viewers to ''travel'' and explore its offerings. The main version of the video runs for 15 minutes, while a shorter 30-second version is also available. The project features performances by Warabiza and includes the theme song ''Kimi wo yobu koe'' by halos. It was produced in collaboration with the citizens of Akita and created by Akita City and VISUALSPACE.INC.' where id = 'FtRGICy10QPfSqB7is4yl';
update content_bodies set title = '秋田市観光宣伝動画「人生は旅」', description = '「人生は旅」と題されたこの観光宣伝動画は、秋田市に住む夫婦の視点から描かれた短編劇です。毎日を好奇心を持って過ごすことで、日常生活が旅のように感じられることを強調しています。秋田市には多くの人々が愛する要素があり、視聴者に地元を訪れてみることを促しています。動画のフルバージョンは約15分、短縮版は約30秒です。制作には劇団蕨座が参加し、テーマ曲「君を呼ぶ声」はhalosが担当しています。また、地元の秋田市民の協力も得ています。' where id = 'ozZC-B7EDGRs4wTbYuDut';
update content_bodies set title = 'Akita City Tourism Promotional Video ''Life is a Journey''', description = 'The promotional video ''Life is a Journey'' depicts a short drama from the perspective of a couple living in Akita City. It emphasizes the idea of experiencing each day with curiosity, making everyday life feel like a journey. The video highlights the many things that people love about Akita City, inviting viewers to explore the area themselves. The full video is approximately 15 minutes long, while a short version is about 30 seconds. The production features the Warabiza theater troupe and includes the theme song ''Kimi wo Yobu Koe'' by halos, with contributions from local Akita citizens.' where id = 'ZGtQE2q0mLe3iuhkNZzKd';
update content_bodies set title = '秋田市プロモーションビデオ「人生は旅」メインバージョン', description = '「人生は旅」は、地元のカップルの視点から秋田市を体験できるドラマ仕立ての観光プロモーションビデオです。このビデオは、毎日を旅のように好奇心を持って過ごし、小さな発見を楽しむことの大切さを伝えています。秋田市は多くの人々のお気に入りの体験や魅力に満ちており、視聴者に「旅」をするように秋田を探索することを促しています。ビデオには、Warabizaのパフォーマンスや、halosのテーマソング「君を呼ぶ声」が含まれています。秋田市とVISUALSPACE.INCの共同制作で、秋田市の市民と協力して作成されました。' where id = '_qU2iNbdwJx02yFgDjb8y';
update content_bodies set title = 'Akita City promotion video ''Life is a Journey'' Main version', description = '''Life is a journey'' is a dramatized tourism promotion video that offers an immersive experience of Akita City through the perspective of a local couple. The video encourages viewers to approach each day with curiosity and to appreciate the small discoveries that can brighten their lives. Akita City is depicted as a place filled with beloved experiences and attractions, inviting viewers to explore and ''travel'' through its offerings. The video features performances by Warabiza and includes the theme song ''Kimi wo yobu koe'' by halos. It was produced in collaboration with the citizens of Akita and created by Akita City and VISUALSPACE.INC.' where id = '9PYS6tjcwwThNHvKofCgZ';
update content_bodies set title = 'Discover Ikeda#002 花の寺｢久安寺｣へ行こう', description = 'Discover Ikedaの第2弾は、池田市伏尾に位置する久安寺です。「花の寺」として知られ、アジサイや紅葉の季節には多くの人々で賑わいます。また、座禅や写経の体験も行っており、こちらもおすすめです。久安寺の体験についての詳細は、こちらをご覧ください：https://kyuanji.jp/experience.html' where id = '7rSo1SYCm8khAS4ZQLca7';
update content_bodies set title = 'Discover Ikeda#002 Visit the Flower Temple ''Kyu-an-ji''', description = 'The second installment of Discover Ikeda features Kyu-an-ji, located in Fuseo, Ikeda City. Known as the ''Flower Temple,'' it attracts many visitors during the hydrangea and autumn foliage seasons. The temple also offers experiences such as zazen meditation and sutra copying, which are highly recommended. For more information on the experiences at Kyu-an-ji, visit: https://kyuanji.jp/experience.html' where id = 'uw9XBjhvT8vD8jSaE_g6i';
update content_bodies set title = '池田が誇る”癒しの空間”へ【不死王閣】', description = 'この動画では、オーストラリア出身の国際交流員Toriさんが日本文化を体験する様子が紹介されています。Toriさんの新鮮なリアクションが魅力的で、池田市の不死王閣の温泉や食事、そして美しい風景にも注目が集まります。日本文化を外国人の視点から楽しむことができる内容です。' where id = '3VtqPGA0nOVzl9AsJpVj6';
update content_bodies set title = 'Discover Ikeda#001: A Healing Space in Ikeda - Fushioukaku', description = 'This video features Tori, an international exchange staff member from Australia, as she experiences Japanese culture. Tori''s fresh reactions provide an engaging perspective on the local culture. The video highlights the hot springs, delicious food, and beautiful scenery at Fushioukaku, a renowned facility in Ikeda City.' where id = 'lS2XC36WH_b0C1vw9VCJG';
update content_bodies set title = '池田市', description = '今回の動画番号 #000 では、Toriさんが池田市のさまざまな場所を巡り、池田市全体を紹介しています。池田の豊かな自然や歴史、文化に触れられるスポットが多数登場し、視聴者はその魅力を体験できます。撮影地には、五月平展望台、池田城跡公園、水月公園、養庄園、伊居太神社、呉服神社、都市緑化植物園、五月山動物園、久安寺が含まれています。それぞれのスポットについての詳細は、池田市観光協会のHPをご覧ください。' where id = 'QQoWFF3fy967-1JNAyjRc';
update content_bodies set title = 'Discover Ikeda#000', description = 'This video, numbered #000, features Tori exploring various locations in Ikeda City, providing an overall introduction to the area. Viewers can experience the rich nature, history, and culture of Ikeda through numerous spots showcased in the video. Filming locations include Mayadaira Observatory, Ikeda Castle Ruins Park, Suigetsu Park, Yoshoen, Ikuta Shrine, Gofuku Shrine, Urban Greening Botanical Garden, Mayasan Zoo, and Kuanji Temple. For more information about each spot, please visit the Ikeda City Tourism Association''s website.' where id = 'H-szei7W084tILvjf1V5A';
update content_bodies set title = 'Discover Ikeda#004 池田呉服座【前編・観賞】', description = '歴史ある池田呉服座で旅芝居を楽しむことができます。「Discover Ikeda」は、オーストラリアから池田市にやってきた国際交流員のToriさんが、市内の様々なスポットを巡る様子を紹介する動画です。この動画では、日本人が気づかない池田市の新しい魅力を発見することができます。' where id = 'TEnvxgypuvfaSZYPDmG7F';
update content_bodies set title = 'Discover Ikeda#004 Ikeda Gofukuza [Part 1: Viewing]', description = 'Enjoy traveling theater at the historic Ikeda Gofukuza. ''Discover Ikeda'' features Tori, an international exchange staff member from Australia, exploring various spots in Ikeda City. This video highlights the ''new attractions of Ikeda City'' that Japanese people might overlook.' where id = 'Ww2u7PobPOtmuUFUiFGaQ';
update content_bodies set title = '家紋刷り体験イベント＠オアシス21iセンター', description = '名古屋・栄で家紋刷りの体験イベントが開催されます。場所はオアシス21iセンター前で、地下鉄東山線・名城線の「栄」駅、または名鉄瀬戸線の「栄町」駅からアクセス可能です。次回の開催日時や予約方法については、名古屋公式観光情報のURLをチェックしてください。' where id = '5S9C5E5v-lSL6MtDdn8dD';
update content_bodies set title = 'Family Crest Dyeing Experience at Oasis 21 iCenter', description = 'Join a hands-on family crest dyeing experience in Sakae, Nagoya. The event takes place outside the Oasis 21 iCenter, conveniently accessible via Sakae Station on the Higashiyama and Meijo Subway Lines or Sakaemachi Station on the Meitetsu Seto Line. For information on the next event dates, times, and reservation methods, please visit the provided URL.' where id = '7S0TmxP_uo_8ZMxPX55kp';
update content_bodies set title = '＜有松・鳴海絞り染め＞オアシス２１iセンター体験イベント', description = '名古屋市のオアシス２１iセンターで、有松・鳴海絞り染めの体験イベントが開催されます。会場は名古屋市東区に位置し、地下鉄東山線・名城線の「栄」駅や名鉄瀬戸線の「栄町」駅からアクセスが便利です。イベントは午前10時から午後6時まで行われ、参加費は1枚1200円です。次回の開催日時や予約方法については、名古屋公式観光情報『名古屋コンシェルジュ』をチェックしてください。' where id = 'FvDrTDqcyUHytBu3NbIWa';
update content_bodies set title = 'Oasis21 iCenter Hands-On Event (Arimatsu-Narumi Shibori tie-dyeing)', description = 'The Oasis21 iCenter in Nagoya is hosting a hands-on event featuring Arimatsu-Narumi Shibori tie-dyeing. Located in the Higashi Ward of Nagoya, participants can easily access the venue from Sakae Station on the Higashiyama and Meijo Subway Lines, or from Sakaemachi Station on the Meitetsu Seto Line. The event runs from 10:00 am to 6:00 pm, and the cost is JPY 1,200 for one dyed item. For information on the next event dates and reservation methods, please check the official Nagoya tourism website, ''Nagoya Concierge''.' where id = 'uFYRR-rsVjYz2z8sb64SD';
update content_bodies set title = 'COOL! NAGOYA - ファミリーブログ', description = '「Cool! Nagoya」という動画は、名古屋の観光名所を家族旅行の形式で紹介しています。中部国際空港、BUCYO COFFEE、名古屋港水族館、久屋大通公園、名古屋駅のひつまぶし屋、名古屋プリンスホテルスカイタワー、若宮八幡社、大須商店街、矢場とん大須本店、レゴランド®ジャパンなど、主要なスポットが取り上げられています。各スポットには詳細情報へのリンクがあり、名古屋での家族旅行を楽しむための包括的なガイドを提供しています。この動画は名古屋観光コンベンションビューローによって制作されており、名古屋の魅力や家族向けのアクティビティを強調しています。' where id = 'Xa0s9KFs73N8KQSnmFX5r';
update content_bodies set title = 'COOL! NAGOYA - FAMILY VLOG', description = 'The video titled ''Cool! Nagoya'' showcases various sightseeing attractions in Nagoya through a family vlog format. It highlights key locations such as Chubu Centrair International Airport, BUCYO COFFEE, the Port of Nagoya Public Aquarium, Hisaya Odori Park, Hitsumabushi Uya at Nagoya Station, Nagoya Prince Hotel Sky Tower, Wakamiya Hachiman Shrine, the Osu Retail District, Yabaton Yaba-cho Honten, and Legoland® Japan. Each location is linked for further exploration, providing viewers with a comprehensive guide to enjoying a family trip in Nagoya. The video is produced by the Nagoya Convention & Visitors Bureau, emphasizing the city''s attractions and family-friendly activities.' where id = 'Ros0WNCEAcXk1ttAeV8E8';
update content_bodies set title = 'Discover Ikeda#003 植木のまち・大阪府池田市で寄せ植え体験をしよう', description = '池田市観光PR動画第3弾は、総合園芸店「養庄園」を紹介しています。ここでは、盆栽を中心に多くの植物や園芸用品が販売されています。「盆栽」というと敷居が高く感じるかもしれませんが、スタッフはフレンドリーで親切に教えてくれます。また、トリさんが挑戦している寄せ植え体験など、さまざまな盆栽体験も行われています。' where id = 'y1kYFdNVB_4NWxEncCrmo';
update content_bodies set title = 'Discover Ikeda#003: Experience Container Gardening in Ikeda City, Osaka', description = 'The third promotional video for Ikeda City tourism features Yoshoen, a comprehensive garden center. They offer a wide range of plants and gardening supplies, with a focus on bonsai. While bonsai may seem intimidating, the staff are friendly and eager to help. Various bonsai experiences, including container gardening, are available for visitors to try.' where id = 'EiWZApOXLYmwBZm8OGGbG';
update content_bodies set title = 'Discover Ikeda#004 池田呉服座【後半・舞台裏潜入】', description = '歴史ある池田呉服座で旅芝居を楽しむことができます。『Discover Ikeda』は、オーストラリアから池田市にやってきた国際交流員のToriさんが、市内の様々なスポットを巡る様子を紹介します。この動画では、日本人が気づかない池田市の新しい魅力を発見することができます。' where id = '1Yyfjg-Jz8eUnkTpi9dgr';
update content_bodies set title = 'Discover Ikeda#004 Ikeda Gofukuza [Part 2: Behind the Scenes]', description = 'Enjoy traveling theater at the historic Ikeda Gofukuza. ''Discover Ikeda'' features Tori, an international exchange staff member from Australia, exploring various spots in Ikeda City. This video reveals ''new attractions in Ikeda City'' that Japanese people might overlook.' where id = 'torZNWByx18JWjFUz1Kr1';
update content_bodies set title = '観光三重NEWS 2018 夏のオススメ観光20セレクション', description = '夏休みの予定はもうお決まりですか？三重県内では楽しいイベントがたくさん開催されており、おすすめの観光スポットを紹介しています。伊勢神宮の内宮や外宮、おかげ横丁など、伊勢・鳥羽・志摩の観光情報が満載です。また、伊勢・鳥羽・志摩のホテルや宿泊、モデルコースについても情報が提供されています。三重県の観光、旅行、イベント、宿泊予約は、三重県観光連盟の公式サイト「観光三重」をご覧ください。' where id = '4qiQy2qa4ZpKp2KsMipj3';
update content_bodies set title = 'Mie Tourism News: 20 Recommended Summer Attractions', description = 'Have you decided on your summer vacation plans? Mie Prefecture is bustling with exciting events! This article introduces recommended spots for your visit. Explore the Ise Jingu Shrine, both the inner and outer shrines, and the Okage Yokocho area, along with travel information for Ise, Toba, and Shima. For hotel accommodations and model courses in the Ise, Toba, and Shima areas, visit the official Mie Prefecture tourism site, ''Kankou Mie''.' where id = 'yMxZSRRteJHqv8igAaZP7';
update content_bodies set title = '名古屋の落語', description = 'この動画は、日本の伝統的な演芸「落語」を通じて名古屋の観光を促進するものです。名古屋の魅力的な風景を紹介し、訪れる価値のある面白い街としての名古屋を強調しています。おじいさんと孫の物語を通じて、名古屋を一緒に探検しましょう！' where id = 'ffU8sTgPaubnSCJxDgr0q';
update content_bodies set title = 'RAKUGO DE NAGOYA', description = 'This video promotes tourism in Nagoya through the traditional Japanese performing art of ''RAKUGO''. It showcases the vibrant images of Nagoya, highlighting it as an interesting city worth visiting. Join us in exploring Nagoya through the story of a grandfather and his grandchild!' where id = 'iNU6EpE0g4pXHxuKqAHnH';
update content_bodies set title = '名古屋の落語', description = 'このプロモーションビデオは、日本の伝統的な演芸である「落語」を通じて名古屋の観光を紹介しています。「楽しい街、訪れたい街」としての名古屋の魅力をたっぷりと伝えています。物語は、祖父と孫の旅行を描いており、興味深い体験を提供しています。' where id = 'ceJd3O0lPl2Fu92hlIvnx';
update content_bodies set title = 'RAKUGO DE NAGOYA', description = 'This promotional video showcases Nagoya through the lens of RAKUGO, a traditional Japanese performing art. It highlights the many attractions of Nagoya, presenting it as a fun city worth visiting. The narrative follows a grandfather and his grandson on an engaging journey, making the experience both entertaining and informative.' where id = 'wamsazgjsVuGRnlXLDcC1';
update content_bodies set title = '名古屋の「COOL! NAGOYA」プロモーション動画【家族旅行】', description = '名古屋の伝統と近未来的な魅力を融合させた新しいプロモーション動画が完成しました。コンセプトは「COOL! NAGOYA」で、家族旅行におすすめのスポットやお祭りを紹介しています。名古屋発祥の和楽器「大正琴」の音色を取り入れたDJ/プロデューサーYamatoによるオリジナルのエレクトロニック・ダンスミュージックが流れる中、レゴランド・ジャパンやクルーズ名古屋、東山動植物園などの魅力的な場所が紹介されます。撮影は新型コロナウイルス感染症対策に留意して行われました。名古屋は東京と大阪の中間に位置し、歴史的にも多くのサムライが活躍した地域で、現在は日本経済を支える大都市です。動画を見た後には、名古屋に対するイメージが「COOL？」から「COOL！」に変わることでしょう。' where id = 'az9Ri53b6CIF9ksu3nb0P';
update content_bodies set title = 'Nagoya City Promotion Movie, “COOL! NAGOYA” 【FAMILY TRIP】', description = 'A new promotional movie showcasing the unique blend of traditional and futuristic attractions in Nagoya has been completed under the concept of ''COOL! NAGOYA.'' The film highlights recommended family vacation spots and local festivals, accompanied by original electronic dance music composed by Yamato, incorporating sounds from the traditional Japanese instrument, Taishōgoto. The video features various locations such as LEGOLAND Japan Resort, Cruise Nagoya, and Higashiyama Zoo and Botanical Garden, all filmed with strict infectious disease prevention measures in mind. Nagoya, conveniently located between Tokyo and Osaka, is a vibrant city with a rich history and a strong industrial presence, making it an ideal destination for family trips. After watching, viewers are likely to shift their perception of Nagoya from ''COOL?'' to ''COOL!''' where id = 'qBRefXWNh_1RV_8pwR084';
update content_bodies set title = '落語で名古屋', description = 'これは日本の伝統芸能「落語」に関する名古屋の観光宣伝ビデオです。名古屋の魅力的な観光スポットを紹介し、「行きたい街」としての名古屋の魅力を伝えています。おじいさんと孫が名古屋を旅行する楽しい物語が描かれています。' where id = 'ZRhMBKqN-srL1zVUy8eFo';
update content_bodies set title = 'RAKUGO DE NAGOYA', description = 'This is a promotional video for Nagoya, showcasing the traditional Japanese art of ''Rakugo.'' The video highlights various attractions in Nagoya, presenting it as an interesting city that you would want to visit. It features a fun story about a grandfather and his grandson traveling to Nagoya.' where id = 'E3TWOv0N93s6wWZXPiYTS';
update content_bodies set title = '名古屋の「COOL! NAGOYA」プロモーション動画【MATSURI】', description = '名古屋の伝統と近未来的な魅力を融合させた新しいプロモーション動画が完成しました。コンセプトは「COOL! NAGOYA」で、名古屋の祭りや家族旅行におすすめのスポットを紹介しています。音楽は名古屋発祥の和楽器「大正琴」の音色を取り入れたDJ/プロデューサーのYamatoによるオリジナルのエレクトロニック・ダンスミュージックです。撮影は新型コロナウイルス感染症対策に留意して行われました。名古屋は東京と大阪の中間に位置し、歴史的には多くのサムライが活躍した地域であり、現在は日本経済を支える大都市です。MATSURI編では、名古屋の祭りやイベントの魅力を紹介し、視聴者の名古屋に対するイメージを「COOL？」から「COOL！」に変えることを目指しています。' where id = 'V7U2dgbTlNo5c5A9kbLMv';
update content_bodies set title = 'Nagoya City Promotion Movie, “COOL! NAGOYA” 【MATSURI】', description = 'A new promotional movie showcasing the unique blend of traditional and futuristic charm of Nagoya has been completed under the concept of ''COOL! NAGOYA''. This film highlights the city''s festivals (MATSURI) and family-friendly travel spots, accompanied by original electronic dance music composed by Yamato, featuring the sounds of the traditional Japanese instrument, Taishokoto. The video was filmed with strict measures to prevent infectious diseases. Nagoya, located conveniently between Tokyo and Osaka, has a rich history of samurai and is a major economic hub in Japan today. The MATSURI segment introduces various local festivals and events, promising to transform viewers'' perceptions of Nagoya from ''COOL?'' to ''COOL!'' after watching.' where id = '8Rd9U7XzoD8GtQrOYXxiS';
update content_bodies set title = 'RAKUGO DE NAGOYA', description = '日本の伝統芸能『落語』を用いた名古屋観光のPR動画です。『楽しい街、行ってみたくなる街・NAGOYA』の魅力を余すところなく紹介しています。おじいさんと孫が織りなす名古屋を旅する面白いストーリーをお楽しみください！' where id = 'XfSqWT4qLFmpAdA1-lutO';
update content_bodies set title = 'RAKUGO DE NAGOYA', description = 'This is a promotional video for tourism in Nagoya, featuring the traditional Japanese art of ''Rakugo.'' The video showcases the attractions of Nagoya, a city that is fun and inviting to visit. Enjoy the entertaining story of a grandfather and his grandson as they explore Nagoya together!' where id = 'oLqjnahKfCWIrvla0p72F';
update content_bodies set title = '驚くべき名古屋 名古屋城でのユニークで特別な体験', description = '名古屋は侍の土地として知られ、豊かな歴史と独自の文化的アイデンティティを持っています。世界クラスの会議施設、古代の伝統、一流のダイニングが揃い、日本の中心に位置するこの街の文化的な雰囲気に触れることができます。名古屋コンベンション＆ビジターズビューローは、特別な体験やインセンティブグループへのサポートに関する情報を提供しています。また、名古屋城という歴史的な場所での特別なポストMICE体験を提案する動画も公開されています。ぜひ「驚くべき名古屋」をお楽しみください。' where id = 'La9n2vtuuQDftk2KbQF50';
update content_bodies set title = 'STUNNING NAGOYA  A Unique and Exclusive Experience at Nagoya Castle', description = 'Nagoya, known for its rich history as the land of Samurais, offers a unique cultural identity. The city features world-class meeting facilities, ancient traditions, and exceptional dining options, all set in the heart of Japan. The Nagoya Convention & Visitors Bureau provides information on exclusive experiences and support for incentive groups. A video showcasing a special post-MICE experience at the historical Nagoya Castle has been released, aiming to inspire visitors. Experience the charm of ''STUNNING Nagoya''.' where id = 'AfJjjCSrim0q0gp28umA4';
update content_bodies set title = '宮崎STYLE SHORTver', description = 'この動画は、宮崎市青島の美しい景観を映し出しています。青島の自然の美しさや魅力を感じることができる内容となっており、視聴者にリラックスしたひとときを提供します。青島の風景は、穏やかな海や緑豊かな環境が特徴で、観光地としても人気があります。' where id = 'yDADJtM-7PpbLRhbljZ1-';
update content_bodies set title = 'Miyazaki STYLE SHORTver', description = 'This video showcases the beautiful scenery of Aoshima in Miyazaki City.' where id = 'e57v4Wp4qUuk-u05w6AIB';
update content_bodies set title = '武将と喫茶文化', description = '名古屋と深い関係を持つ武将たちは、古くから喫茶を好んでおり、その影響で江戸時代には平民も喫茶を楽しむようになりました。このような精神文化は、今もなお受け継がれています。' where id = 'LeW-Ykb3sRsLxetJkUZCW';
update content_bodies set title = 'Warlords and Tea Culture', description = 'The warlords closely associated with Nagoya have historically had a fondness for tea, which influenced the common people during the Edo period to also begin enjoying tea. This cultural spirit has continued to be passed down to the present day.' where id = 'RjD3YM-f6zUIi6l4vInrk';
update content_bodies set title = '名古屋喫茶文化', description = '名古屋の喫茶店では、1杯の飲み物の価格で朝食を楽しむことができ、さらに他の特典が付くこともあります。各喫茶店には独自の特色メニューがあり、さまざまな喫茶店を探索する楽しみがあります。名古屋の多様な喫茶文化を体験してみてください。' where id = '03PYg5KcxoMvr9AZ9-J9U';
update content_bodies set title = 'Nagoya Coffee Culture', description = 'In Nagoya, you can enjoy a breakfast at coffee shops for the price of just one drink, often accompanied by additional complimentary items. Each coffee shop has its own unique menu, inviting you to explore the diverse offerings available. Discover the distinct characteristics of various coffee shops in the area.' where id = '38q3nE7mamyHzgwdMFQxx';
update content_bodies set title = '武将と喫茶文化', description = '名古屋にゆかりのある武将たちが楽しんだお茶の文化は、江戸時代には庶民にも広がりました。抹茶とお茶菓子で一服する習慣は、現代の喫茶店で一息つくというスピリッツにつながっていると言われています。' where id = 'Nvyz1CQTY6brqMlgJsTkv';
update content_bodies set title = 'Warlords and Tea Culture', description = 'The tea culture enjoyed by warlords associated with Nagoya spread to the common people during the Edo period. The custom of taking a break with matcha and sweets is said to connect to the spirit of relaxing in modern tea shops.' where id = 'O9KtoRCXruiCWyI-gfEaN';
update content_bodies set title = '名古屋喫茶文化', description = '名古屋の喫茶文化は、ドリンク1杯の値段でおまけがついてくる「モーニング」が有名です。このサービスは、朝食として軽食やおつまみが提供されることが多く、地元の人々に愛されています。また、各喫茶店には独自の特色あるメニューが豊富に揃っており、訪れるたびに新しい発見があります。喫茶店巡りを通じて、名古屋の多様な喫茶文化を楽しむことができるでしょう。' where id = 'aZTH3B4QPzq4_4k9971nM';
update content_bodies set title = 'Nagoya Coffee Culture', description = 'Nagoya is famous for its ''morning'' service, where customers receive a complimentary item with the purchase of a drink. In addition to this unique offering, there is a wide variety of coffee shop menus that showcase the distinct characteristics of each establishment. Exploring these coffee shops can be an enjoyable experience.' where id = 'sM7IXap9_z8KKycc4G9BR';
update content_bodies set title = '高知家ええもん動画　土佐おもてなし勤王党リポート　高知城ガイド・前編', description = '今回の動画では、土佐おもてなし勤王党が高知の観光名所である高知城を案内します。意外と知られていない高知城の見どころを紹介し、観光客に新たな発見を提供します。' where id = 'Yg1qm3_PjlaxAZu1Eavxn';
update content_bodies set title = 'Tosa Omotenashi Kinno-to Report: Kochi Castle Guide - Part 1', description = 'In this video, the Tosa Omotenashi Kinno-to introduces Kochi''s iconic tourist spot, Kochi Castle. The report highlights some of the lesser-known attractions of Kochi Castle.' where id = 'MDgWblw_-iENfvMtIYHJV';
update content_bodies set title = 'なばりまち和菓子の食べ歩きプラス（三重県名張市）', description = '三重県名張市内の老舗和菓子店の逸品を食べ歩くイベントが開催されています。参加者は12のお店の中から好きな5店を選び、自慢の和菓子を楽しむことができるお得なシートを購入できます。和菓子を味わいながら、風情ある名張の町を散策することができます。三重県の観光情報やイベント、宿泊予約については、三重県観光連盟の公式サイト「観光三重」をご覧ください。また、伊勢神宮や伊勢鳥羽志摩の観光情報も提供されています。' where id = 'nHfDF9OjgPHspk7t27mtP';
update content_bodies set title = 'Walking Tour of Traditional Japanese Sweets in Nabari City, Mie Prefecture', description = 'Explore the exquisite offerings of long-established wagashi shops in Nabari City, Mie Prefecture! A special ticket allows you to choose five out of twelve shops to enjoy their signature wagashi. While savoring these traditional sweets, take a leisurely stroll through the charming streets of Nabari. For more information on recommended sightseeing in Mie Prefecture, visit the special site ''Walking in Iga and Nabari''. You can also find details about tourism, events, and accommodation on the official Mie Prefecture tourism site ''Kankomie''. Additionally, for information on Ise Jingu Shrine and other attractions in the Ise-Toba-Shima area, check out ''First Time Visiting Ise: Walking in Ise-Shima''.' where id = '2_nV-nTL0tKp7HwGzBIks';
update content_bodies set title = '【高知県】土佐の匠 「土佐古代塗」', description = '土佐古代塗は、高知県の特有の漆器で、気品と重厚感が特徴です。この伝統的な技術を受け継ぐ唯一の職人、池田泰一さんの技をぜひご覧ください。' where id = 'gnFMOBdRf5F_l_ljmy7OF';
update content_bodies set title = 'Tosa''s Craftsman: Tosa Ancient Lacquer', description = 'Tosa Ancient Lacquer is a unique lacquerware from Kochi Prefecture, characterized by its elegance and heaviness. Witness the craftsmanship of Taiichi Ikeda, the sole inheritor of this traditional art.' where id = 'w9O3wGUkdPCaOLb2HD6d5';
update content_bodies set title = '名古屋神社巡禮', description = '名古屋の神社を巡る旅は、その色とりどりの魅力に驚かされるものです。賑やかな商業地区から静かで優雅な住宅街の隅々、そしてのんびりとした農村から、到達するのに一苦労する聖地まで、さまざまな場所がまるで日本全国を旅しているかのような感覚を与えます。変化に富んだ名古屋神社の旅は魅力に満ちており、出発した瞬間からその魅力に引き込まれることでしょう。' where id = 'O6e53vs6u3-PskltSp70t';
update content_bodies set title = 'Nagoya Shrine Tour', description = 'The tour through the shrines of Nagoya is filled with vibrant and colorful experiences that will leave you amazed. From bustling commercial areas to serene and elegant residential corners, and from leisurely rural settings to sacred places that seem to require effort to reach, the variety of locations feels like a journey across Japan. This diverse Nagoya shrine tour is full of charm and will surely keep you captivated from the moment you start your adventure.' where id = 'UxtXCPpdraxXGExJj65P5';
update content_bodies set title = '名古屋の神社を巡る旅', description = '日本の家庭では、伝統的に神棚が置かれていましたが、アパート暮らしの普及などライフスタイルの変化により、多くの家庭から神棚が姿を消しています。しかし、外に出れば、名古屋には多くの神社が存在します。世界各地から訪れる皆さんが、名古屋で私たちを見守る神々と出会うことができることを願っています。この出会いが皆さんに喜びをもたらすと信じています。' where id = 'up1xXE3t6emvIzxNbpZE_';
update content_bodies set title = 'Travel Around to Nagoya''s Shrines', description = 'Japanese families have traditionally kept a kamidana, or household Shinto altar, in their homes. However, modern lifestyle changes, particularly the shift towards apartment living, have led to the decline of these altars in many households. Despite this, numerous shrines can still be found throughout the city. Visitors from around the world are encouraged to explore these sacred spaces in Nagoya, where they may encounter deities that are believed to watch over us, bringing joy and a sense of connection to the spiritual heritage of Japan.' where id = 'JIlLKPo-csvJkVXxoDscN';
update content_bodies set title = '高知県 土佐の匠 「フラフ」', description = '「フラフ」は空を彩る大きな旗で、高知市の東部でよく見られます。この旗は、子どもの健やかな成長を願い、鯉のぼりなどと一緒に掲げられます。地域の伝統として、特に子どもの日などの行事で重要な役割を果たしています。' where id = 'dF4Qyt8TE1PzcfvL4Y-wg';
update content_bodies set title = 'Tosa''s Artisan: ''Furafu''', description = 'The ''Furafu'' is a large flag that colors the sky, commonly seen in the eastern part of Kochi City. This flag is raised alongside carp streamers and other decorations to wish for the healthy growth of children.' where id = 'rKk8JXnlv5CwC01y9CPcP';
update content_bodies set title = '名古屋のプロモーション動画「COOL! NAGOYA」【アミューズメント】', description = '名古屋の「伝統」と「近未来」が融合した新しいプロモーション動画「COOL! NAGOYA」が完成しました。この動画では、名古屋の魅力的な歴史、食、ナイトタイム観光、ウェルネス、アミューズメントを紹介しています。名古屋発祥の和楽器「大正琴」の音色を取り入れ、DJ/プロデューサーのYamatoが作曲したオリジナルのエレクトロニック・ダンスミュージックに乗せて、様々なスポットを紹介しています。シェアサイクルや中部電力MIRAI TOWER、ノリタケの森、名古屋市科学館、レゴランド・ジャパンなどが登場します。撮影は新型コロナウイルス感染症対策に留意して行われました。ぜひ名古屋の魅力を楽しんでください。' where id = 'PdpEQfe8Oj3_oVsETyrON';
update content_bodies set title = 'Nagoya City Promotion Movie, “COOL! NAGOYA” 【AMUSEMENT】', description = 'A new promotional movie titled ''COOL! NAGOYA'' has been completed, showcasing the unique blend of traditional and futuristic attractions in Nagoya. The film highlights the city''s rich history, delicious food, vibrant nightlife, wellness options, and amusement activities, all set to original electronic dance music composed by Yamato. The video features various locations, including share bike services, the Chubu Electric Power MIRAI TOWER, Noritake Garden, the Nagoya City Science Museum, and LEGOLAND Japan Resort, among others. The production adhered to strict infectious disease measures to ensure safety during filming. Viewers are encouraged to enjoy the captivating sights and sounds of Nagoya.' where id = 'GEPu_dJk0rx83RHCUz4ar';
update content_bodies set title = 'EEGANE! Come and Find, Your NAGOYA!', description = '名古屋観光コンベンションビューローは、日本に住むフィリピン人向けに「EEGANE! Come and Find, Your NAGOYA!」というプロモーションビデオを制作しました。このビデオでは、フィリピン・マニラ出身のテレビ愛知アナウンサー、岡田めぐみが、フィリピン人のステファニーさんとアリサさんと共に名古屋の魅力を紹介します。「EEGANE!」は名古屋弁で「素晴らしい」という意味です。ビデオは「名古屋の食」と「神社」の2つのテーマを取り上げ、名古屋独特の「モーニング」文化や、山田天満宮での御金洗いなど、名古屋での幸運を見つける体験を紹介しています。名古屋の魅力を「体験」をテーマに伝える内容です。' where id = 'PxfXfRs6lvwyLt5XQA-ql';
update content_bodies set title = 'EEGANE! Come and Find, Your NAGOYA!', description = 'The NAGOYA Convention & Visitors Bureau has created a promotional video aimed at Filipinos living in Japan, titled ''EEGANE! Come and Find, Your NAGOYA!'' The video features Megumi Marie Okada, a TV Aichi announcer from Manila, who guides viewers through the attractions of Nagoya alongside two Filipino residents, Stephanie and Alisa. The term ''EEGANE!'' translates to ''NICE!'' in the local Nagoya dialect. The video showcases two themes: ''Nagoya food'' and ''Shrines.'' It highlights unique aspects of Nagoya''s food culture, such as the local ''Morning'' dining experience, and activities like washing money at Yamada Tenmangu shrine, symbolizing good luck. The overall theme of the video is to convey the experiential charm of Nagoya.' where id = 'kwh1UAoGle5zJBOzZsOLl';
update content_bodies set title = 'ワォ！がたくさん あなたの知らない名古屋 オンラインツアー ナイトホッピング編', description = '2021年10月2日に開催された「ワォ！がたくさん あなたの知らない名古屋オンラインツアー ナイトホッピング編」のアーカイブです。総合司会はラジオパーソナリティーのMEGURUさんが務め、ガイドにはBOYS AND MENの田村侑久、勇翔、TEAM SHACHIの秋本帆華、咲良菜緒、大黒柚姫、坂本遥奈が参加しました。名古屋の名物や地酒をテーマに、居酒屋巡りを中心に名古屋の夜の観光を紹介しています。あなたの知らない名古屋をぜひ堪能してください。' where id = 'f3M6t-81kpXUtNUfU0hx2';
update content_bodies set title = 'Wow! A Lot of Surprises: Online Tour of Nagoya - Night Hopping Edition', description = 'This is the archive of the ''Wow! A Lot of Surprises: Online Tour of Nagoya - Night Hopping Edition'' held on October 2, 2021. The event was hosted by radio personality ''MEGURU'', with guides including ''Yuki Tamura'' and ''Yuto'' from BOYS AND MEN, and ''Honoka Akimoto'', ''Nao Sakuragi'', ''Yuzuki Ooguro'', and ''Haruna Sakamoto'' from TEAM SHACHI. The tour focused on introducing Nagoya''s nightlife, particularly through izakaya visits, featuring local specialties and sake. Enjoy discovering the Nagoya you didn''t know before.' where id = 'hLjyIg_CwVINBdeUb1KUH';
update content_bodies set title = 'ナガシマジャンボ海水プール「ジャパーーーーン」(桑名市)｜観光三重｜三重県の観光・旅行情報', description = 'ナガシマジャンボ海水プールの人気アトラクション「ジャパーーーーン」を体験しました！高さ約18ｍから大量の水が流れ落ちるこのアトラクションは、特に人気があります。タワーの最高部にある約3トンの巨大バケツと、他の2つの巨大バケツを合わせて、総重量6トンもの水が一気に流れ落ちる様子は圧巻です。スリルを求める方にはぜひ訪れてほしいスポットです。' where id = 'WJuXkzZKKFvSCbIaM2V5W';
update content_bodies set title = 'Nagashima Jumbo Ocean Pool ''Japan'' (Kuwana City) | Tourism Mie | Mie Prefecture Travel Information', description = 'We experienced the thrilling attraction ''Japan'' at Nagashima Jumbo Ocean Pool! Water flows down from a height of about 18 meters, creating a popular spectacle. A massive bucket weighing approximately 3 tons, located at the top of the tower, along with two other giant buckets, releases a total of 6 tons of water all at once! This attraction is a must-visit for thrill-seekers.' where id = 'Ang_JhC6iXbapR-sr0vdX';
update content_bodies set title = '鰻温泉散策と蒸し料理', description = '鹿児島県の指宿市に位置する鰻温泉では、温泉水を使って蒸した日本式の点心、すめを楽しむユニークな体験ができます。このガイドでは、村を散策し、温泉での料理の蒸し方についての情報を提供しています。' where id = '5PGVXnO1TroyzmoBazOsD';
update content_bodies set title = 'Strolling Around Unagi Hot Spring Village and Steaming Food in the Hot Spring', description = 'Located in Ibusuki City, Kagoshima Prefecture, the Unagi Hot Spring offers a unique experience of enjoying Japanese-style dim sum, known as sume, steamed using the hot spring water. This guide provides information on walking around the village and the process of steaming food in the hot spring.' where id = 'VZ8ywnHXbKXT0TxNsErMq';
update content_bodies set title = 'ともにいただく Taste Tomonoura Together -Francais-', description = 'このウェブサイトは、日本の美しい港町、鞆の浦の食文化体験に特化しています。地域の料理や文化を促進し、訪問者にその風味や伝統を探求することを呼びかけています。' where id = 'PHzMmzOAuDE7YxIyU765n';
update content_bodies set title = 'Taste Tomonoura Together -Francais-', description = 'This is a website dedicated to the culinary experiences of Tomonoura, a picturesque port town in Japan. It aims to promote the local cuisine and culture, inviting visitors to explore the flavors and traditions of the region.' where id = 'YU7aXpWOhsL2Rb-3VI-YB';
update content_bodies set title = 'ともにたのしむ Discover Tomonoura Together -Francais-', description = 'このウェブサイトは、日本の美しい港町、鞆の浦を探求するためのものです。訪問者が鞆の浦の地元文化や観光名所、体験を楽しむための情報やリソースを提供しています。' where id = 'mByGuf8tOgCMmYiFhniTl';
update content_bodies set title = 'Discover Tomonoura Together - Francais -', description = 'This is a website dedicated to exploring Tomonoura, a picturesque port town in Japan. The site provides information and resources for visitors to enjoy the local culture, attractions, and experiences available in Tomonoura.' where id = 'Iz-w5IQd7eVmuuyloa6KV';
update content_bodies set title = '名古屋市プロモーション動画「COOL! NAGOYA」【ダイジェスト】', description = '名古屋の伝統と近未来的な魅力を融合させたプロモーション動画「COOL! NAGOYA」が完成しました。この動画では、名古屋の豊かな歴史、多様な食文化、活気あるナイトライフを紹介し、名古屋発祥の和楽器「大正琴」の音色を取り入れたDJ/プロデューサーYamatoによるオリジナルのエレクトロニック・ダンスミュージックに乗せています。名古屋大仏や名古屋城、コメダ珈琲店や味噌カツ矢場とんなど、様々な名所が登場します。新型コロナウイルス感染症対策に留意して撮影されており、名古屋の魅力をぜひ楽しんでください。' where id = 'hy4HU-Eqceo467Dl5JEUd';
update content_bodies set title = 'Nagoya City Promotion Movie, “COOL! NAGOYA”【DIGEST】', description = 'A new promotional movie titled ''COOL! NAGOYA'' has been completed, showcasing the unique blend of traditional and futuristic attractions in Nagoya. The film highlights the city''s rich history, diverse food culture, and vibrant nightlife, all set to original electronic dance music composed by Yamato. Key locations featured include Nagoya Buddha at Toganji Temple, Nagoya Castle, and various local food spots such as Komeda Coffee and Misokatsu Yabaton. The video was produced with strict measures to prevent infectious diseases. Viewers are encouraged to enjoy the captivating sights and sounds of Nagoya.' where id = 'EFsL9L0wNp7Y9Us9fBCv8';
update content_bodies set title = '祇園白川筋を歩く | 4K', description = '私の好きな京都の通りは祇園白川筋です。この通りは非常にフォトジェニックで、たくさんの本格的な日本の建物を見ることができます。京都を訪れる際には絶対に見逃してはいけません。' where id = 'pilcr5QTsZ70n10s06VOI';
update content_bodies set title = 'Walking in Kyoto along Gion Shirakawa-suji | 4K', description = 'Gion Shirakawa-suji is my favorite street in Kyoto, known for its photogenic qualities. The area features many authentic Japanese-style buildings, making it a must-visit location for anyone traveling to Kyoto.' where id = 'iGb13Qc5Y12c_F6tseiSt';
update content_bodies set title = '女子旅！名古屋の産業観光ＰＲ動画（フルバージョン）', description = '名古屋の産業観光施設の魅力や伝統工芸、食文化を紹介する動画です。「ものづくり王国名古屋」の魅力が満載で、産業観光を巡る際の参考になります。名古屋市公式観光情報である名古屋コンシェルジュの特集「これぞモノづくりの神髄　攻める！名古屋の産業観光」でも紹介されています。' where id = '7j5i24U7qfTY-Afz4tGPI';
update content_bodies set title = 'Girls'' Trip! Nagoya''s Industrial Tourism PR Video (Full Version)', description = 'This video showcases the charm of Nagoya''s industrial tourism facilities, traditional crafts, and food culture. It is filled with the appeal of ''Monozukuri Kingdom Nagoya,'' making it a great reference for those exploring industrial tourism in the area.' where id = '-BvHZMYtro3Z8QgkXxmCk';
update content_bodies set title = '女子旅！名古屋の産業観光ＰＲ動画（ショートバージョン）', description = '名古屋の産業観光施設の魅力や伝統工芸、食文化を紹介する動画です。「ものづくり王国名古屋」の魅力が満載で、産業観光を巡る際の参考になります。名古屋市公式観光情報である名古屋コンシェルジュの特集「これぞモノづくりの神髄　攻める！名古屋の産業観光」で紹介されています。' where id = 'zZ47xeW_f-rQeGRnilzlc';
update content_bodies set title = 'Girls'' Trip! Nagoya''s Industrial Tourism PR Video (Short Version)', description = 'This video introduces the charm of Nagoya''s industrial tourism facilities, traditional crafts, and food culture. It is packed with the appeal of ''Monozukuri Kingdom Nagoya,'' making it a great reference for those exploring industrial tourism!' where id = 'Da_yZWzdPT_PKl5w72ob3';
