update content_bodies set title = 'Discover Tomonoura Together', description = 'This is a website dedicated to exploring and enjoying Tomonoura, a picturesque port town in Japan. The site provides information and resources for visitors to experience the beauty and culture of the area.' where id = 'GfUv1s6EumErphAK0aBYU';
update content_bodies set title = 'GEO MIRACLE KOBE～母なる六甲山～', description = 'GEO MIRACLE KOBEは、神戸の美しさを紹介するビジュアル体験であり、特に母なる六甲山に焦点を当てています。このプログラムでは、山が提供する自然の風景、文化的な重要性、レクリエーションの機会を強調しています。視聴者は、素晴らしい景色や地域のユニークな特徴を探求でき、地元の人々や観光客にとって必見の目的地となっています。詳細については、提供されたリンクを訪れてください。' where id = '1BPAZ7MIivLBs01ubloln';
update content_bodies set title = 'GEO MIRACLE KOBE - Mother Mt. ROKKO', description = 'GEO MIRACLE KOBE is a visual experience that showcases the beauty of Kobe, particularly focusing on Mother Mt. ROKKO. The program highlights the natural landscapes, cultural significance, and recreational opportunities that the mountain offers. Viewers can explore the stunning views and the unique features of the area, making it a must-see destination for both locals and tourists. For more information, visit the provided link.' where id = 'apP60k5zu7GNqYtTsqz0r';
update content_bodies set title = 'ともによろこぶ', description = 'このウェブサイトは、友浦のコミュニティと文化を祝うことに特化しています。地域の遺産を評価し、住民と訪問者の間に団結感を育むことを目的としています。' where id = '2NkdIK0cejYkgIZQjejkB';
update content_bodies set title = 'Celebrate Tomonoura Together', description = 'This is a website dedicated to celebrating the community and culture of Tomonoura. It aims to bring people together to appreciate the local heritage and foster a sense of unity among residents and visitors.' where id = 'LudtnaH6ATQXaZGuvA7rk';
update content_bodies set title = 'ともにいただく', description = 'このウェブサイトは、日本の美しい港町、鞆の浦の食文化体験に特化しています。地元の料理や文化を促進し、訪問者にこの地域の味や伝統を探求することを呼びかけています。' where id = 'bGw17Ge8Q2MIhaBaeXgca';
update content_bodies set title = 'Taste Tomonoura Together', description = 'This is a website dedicated to the culinary experiences of Tomonoura, a picturesque port town in Japan. It aims to promote the local cuisine and culture, inviting visitors to explore the flavors and traditions of the area.' where id = 'lCsKh6gYn8EGu4j5Ns-lh';
update content_bodies set title = '【アーカイブ】あなたの知らない名古屋オンラインツアー　名古屋城編', description = '2021年1月17日に開催された「あなたの知らない名古屋オンラインツアー　名古屋城編」のアーカイブです。名古屋おもてなし武将隊の徳川家康、前田慶次、加藤清正、踊舞、なつが名古屋城の魅力を分かりやすくガイドします。初心者向けから玄人向けの情報が提供され、特別に撮影された「藩主・将軍 着座目線」の映像も楽しめます。通常の観覧では立ち入れない「表書院上段之間」や「対面所上段之間」から、400年前の藩主や将軍しか見ることのできなかった景色を堪能できます。' where id = 'VjF7XgQ-e88yxD1nSd3km';
update content_bodies set title = 'Archive: Online Tour of Nagoya You Didn''t Know - Nagoya Castle Edition', description = 'This is the archive of the "Online Tour of Nagoya You Didn''t Know - Nagoya Castle Edition" held on January 17, 2021. The tour is guided by members of the Nagoya Omotenashi Busho-tai, including Tokugawa Ieyasu, Maeda Keiji, Kato Kiyomasa, Odori Mai, and Natsu, who explain the charm of Nagoya Castle in an easy-to-understand manner. The tour offers information for both beginners and experts, along with special footage shot for this online tour, featuring a ''lord and shogun''s perspective'' view. Participants can enjoy views from areas not accessible during regular visits, such as the ''Omote Shoin Jodan no Ma'' and ''Taimenjo Jodan no Ma,'' experiencing sights that only lords and shoguns could see 400 years ago.' where id = 'mgC40fswJVQTOLkRgcwZa';
update content_bodies set title = 'GEO MIRACLE KOBE～Water and Sake～', description = '『GEO MIRACLE KOBE～Water and Sake～』は、神戸における水と酒の関係を探る魅力的なプログラムです。神戸の水の特性が、同市の名酒生産にどのように寄与しているかを強調しています。視聴者は、酒造りの複雑なプロセスや、この伝統的な飲み物の文化的意義を発見することができます。ドキュメンタリーは神戸の美しさと自然資源を紹介し、環境と地元の職人技における水の重要性を強調しています。' where id = 'e4uh5wMz1c-Ns4CDlFXk-';
update content_bodies set title = 'GEO MIRACLE KOBE: Water and Sake', description = 'GEO MIRACLE KOBE is a captivating exploration of the relationship between water and sake in Kobe. The program highlights the unique qualities of Kobe''s water, which contribute to the city''s renowned sake production. Viewers are invited to discover the intricate processes involved in sake brewing and the cultural significance of this traditional beverage in the region. The documentary showcases the beauty of Kobe and its natural resources, emphasizing the importance of water in both the environment and local craftsmanship.' where id = 'tew_rwZlPGyWzV_17arTq';
update content_bodies set title = '霊台橋', description = 'この観光PR動画は2025年に制作された美里町のもので、霊台橋を紹介しています。霊台橋は全長90メートルの巨大な石橋で、緑川の本流で最も難所である船津峡を跨いでいます。1847年に田山の石工兄弟、宇助、宇一、常八によって建設され、江戸時代の日本で最大の単一石アーチの一つとして知られています。また、国の重要文化財にも指定されています。' where id = 'wucizdh-0oTIsDJsjxbyZ';
update content_bodies set title = 'Reidai Bridge', description = 'This tourism PR video for Misato Town, created in 2025, showcases the Reidai Bridge, a monumental stone structure measuring 90 meters in length. Spanning the Funatsu Gorge, it represents the most challenging section of the Midori River''s main stream. Built in 1847 by the Taneyama mason brothers Usuke, Uichi, and Johachi, it is recognized as one of Japan''s largest single stone arches from the Edo period and is designated as a nationally important cultural property.' where id = 'LWy-YGc5oqbBnHT4iKixd';
update content_bodies set title = 'きみへ届け！名古屋テレビ塔からエール', description = 'この動画では、名古屋テレビ塔からのエールについて紹介しています。名古屋テレビ塔は、地域の人々に向けて励ましのメッセージを発信しており、その点灯の様子が映し出されています。特に、困難な時期において、希望や勇気を与えるための取り組みとして注目されています。' where id = 'pFe4xNLGKIU3hcS5duw5e';
update content_bodies set title = 'A Message of Support from Nagoya TV Tower', description = 'This video introduces the message of support from Nagoya TV Tower.' where id = 'lhHx3t6LJ5-WxPrYwJs8j';
update content_bodies set title = '緑区プロモーション映像（3分版）', description = 'この動画は緑区について紹介しています。緑区の魅力や特徴を短時間で伝える内容となっており、地域の観光スポットや文化、自然環境などが紹介されています。視聴者は緑区の様々な側面を知ることができ、訪れてみたくなるような情報が盛り込まれています。' where id = '28rF7alypidQXldEDfsnB';
