update content_bodies set title = 'Nagoya City Tourism PV - Photogenic Nagoya', description = 'This video showcases the tourism attractions of Nagoya City, highlighting its photogenic spots. The content is presented in Korean, making it accessible for Korean-speaking audiences interested in exploring the beautiful locations within Nagoya.' where id = 'mttUfNwvul0dncNDaNVe7';
update content_bodies set title = '名古屋市観光PV - フォトジェニックな名古屋（ベトナム語）', description = 'この動画は、名古屋市の観光プロモーションビデオを紹介しており、特にベトナム語話者向けに名古屋のフォトジェニックな魅力や観光名所を強調しています。' where id = '6RFQHOvl2QQ1nStQ9Nkf2';
update content_bodies set title = 'Nagoya City Tourism PV - Photogenic Nagoya in Vietnamese', description = 'This video showcases the tourism promotion video for Nagoya City, highlighting its photogenic aspects and attractions, specifically tailored for Vietnamese audiences.' where id = 'lR7TVXU7RkNiBqYBt2wKB';
update content_bodies set title = '名古屋市観光PV - フォトジェニックな名古屋 タイ語版', description = 'この動画は、名古屋市の観光名所を紹介し、特にフォトジェニックなスポットに焦点を当てています。内容はタイ語で提供されており、名古屋の美しい場所を探索したいタイ語を話す観客に向けられています。' where id = '_ITegjKbZTuh2SSBWwC1F';
