update content_bodies set title = '名古屋市観光PV - フォトジェニックな名古屋 - 英語', description = 'この動画は名古屋市の観光を紹介し、名古屋のフォトジェニックな側面に焦点を当てています。訪れる人々にとって魅力的なスポットや観光名所を強調しています。' where id = 'LLM4H1E_ytCvL0Xj3TeTc';
update content_bodies set title = 'Nagoya City Tourism PV - Photogenic Nagoya - English', description = 'This video showcases the tourism potential of Nagoya City, focusing on its photogenic features. It highlights various scenic spots and attractions that make Nagoya an appealing destination for visitors.' where id = 'GYpfCCjUjlDcZtl8yF_Cb';
update content_bodies set title = '名古屋の城景観光', description = 'この動画では、名古屋の城景観光について紹介しています。名古屋城は日本の歴史的な名所であり、その美しい景観や文化的な価値が多くの観光客を惹きつけています。名古屋城本丸御殿は、城の中心部に位置し、訪れる人々にその魅力を伝えています。動画を通じて、名古屋城の魅力や観光の楽しみ方を知ることができます。' where id = 'FO6VRpAzX8oCD3jDK6aoj';
update content_bodies set title = 'Nagoya Castle Sightseeing', description = 'This video introduces sightseeing at Nagoya Castle.' where id = 'YQo0RpLJYwisfOD3kMVa8';
update content_bodies set title = '名古屋の歴史観光', description = 'この動画では、名古屋の歴史観光について紹介しています。名古屋は日本の中部地方に位置し、豊かな歴史と文化を持つ都市です。名古屋城や熱田神宮などの歴史的な名所があり、観光客にとって魅力的なスポットが多数存在します。動画では、これらの名所を訪れることで得られる歴史的な背景や文化的な意義についても触れています。名古屋の歴史を学びながら、観光を楽しむことができる内容となっています。' where id = 'bOKP0cySP2Ldj26sYGG6s';
update content_bodies set title = 'Historical Tourism in Nagoya', description = 'This video introduces historical tourism in Nagoya.' where id = 'OulJQcdjFAYQ8Fiq7Y1GO';
update content_bodies set title = '名古屋おもてなし武将隊 織田信長と徳川家康おススメ観光スポットとなごやめし', description = '名古屋おもてなし武将隊の織田信長と徳川家康が、おすすめの観光スポットや名古屋の名物料理「なごやめし」について熱く語ります。詳細な情報は、提供されたURLをクリックしてご覧ください。伝統美を味わえる有松や、三英傑にゆかりのある名古屋の歴史的な場所を訪れ、織田信長、豊臣秀吉、徳川家康に関連するテーマ別のツアーを楽しむことができます。また、NHKの大河ドラマ『麒麟がくる』に登場するスポットも紹介されています。' where id = 'DV4SPqRPKBkZUgXAf7Fqg';
update content_bodies set title = 'Nagoya Hospitality Samurai Team: Recommended Tourist Spots and Nagoya Cuisine', description = 'The Nagoya Hospitality Samurai Team, featuring Oda Nobunaga and Tokugawa Ieyasu, passionately discusses recommended tourist spots and local cuisine known as ''Nagoya-meshi.'' For detailed information on the recommended spots, please click the URLs provided. Explore traditional beauty in Arimatsu, visit the historical sites related to the three great unifiers of Japan in Nagoya, and enjoy various themed tours related to Oda Nobunaga, Toyotomi Hideyoshi, and Tokugawa Ieyasu. Additionally, discover locations featured in the NHK historical drama ''Kirin ga Kuru.''' where id = 'J6R4v-inrjR7TlomYaRui';
update content_bodies set title = '名古屋の文化芸術', description = 'この動画では、名古屋の文化芸術について紹介しています。名古屋は独自の文化を持ち、伝統的な芸術や現代アートが融合しています。地域の特性を反映した多様な表現が見られ、観光客や地元の人々にとって魅力的なスポットとなっています。' where id = 'ljOtILuxi7tao-nkPntlW';
update content_bodies set title = 'Cultural Arts of Nagoya', description = 'This video introduces the cultural arts of Nagoya.' where id = 'CJE7oZDuN1YqlUnuBv-BU';
update content_bodies set title = 'CITY LIGHT FANTASIA by NAKED ｰNEW WORLDｰ', description = 'この動画は、名古屋で開催される「CITY LIGHT FANTASIA by NAKED ｰNEW WORLDｰ」について紹介しています。このイベントは、名古屋の魅力を引き出す幻想的な光の演出が特徴で、訪れる人々に新しい世界観を提供します。' where id = 'gVYVFAyLElcPvqd9ZLd6e';
update content_bodies set title = 'CITY LIGHT FANTASIA by NAKED -NEW WORLD-', description = 'This video introduces CITY LIGHT FANTASIA by NAKED -NEW WORLD-.' where id = 'r7YanfSuSuSMWJvKtnxpx';
update content_bodies set title = 'ドラマティックシティ名古屋 ダイジェスト', description = 'この動画は、名古屋の魅力を伝える「ドラマティックシティ名古屋」について紹介しています。名古屋の文化や観光スポット、特有の魅力を視聴者に伝える内容となっており、名古屋を訪れる際の参考になる情報が含まれています。' where id = '5YOF0i4z4mgSBCZack5za';
update content_bodies set title = 'Dramatic City Nagoya Digest', description = 'This video introduces Dramatic City Nagoya.' where id = 'NFWO88pFW7rpoxBV0qpAJ';
update content_bodies set title = 'アマミ旅行 4K 30分 韓国語版', description = 'アマミオシマは、豊かな独特の文化が残る世界自然遺産推薦地域です。『アマミ旅行』は、アマミオシマ出身の二人の女性がレンタカーで観光地や景勝地を巡り、アマミオシマの魅力を再発見する動画です。この動画は、アマミオシマを訪れる予定の方にとって、参考になる内容となっています。また、アマミオシマを訪れた際には、素晴らしい景色の写真を『#アマミ旅行』のハッシュタグを付けてSNSで共有することが奨励されています。' where id = 'A-4kz0y8TF98uM9PXKdr8';
update content_bodies set title = 'Amami Travel 4K 30 Minutes Korean Version', description = 'Amami Oshima is a UNESCO World Heritage site known for its rich and unique culture. The video ''Amami Travel'' features two women from Amami Oshima who explore the island''s attractions and scenic spots by rental car, rediscovering the island''s charm. This video serves as a helpful guide for anyone planning to visit Amami Oshima. Visitors are encouraged to share their beautiful photos of the island on social media using the hashtag #AmamiTravel.' where id = 'Lz45ZEpOrXVz5IVCzKDNY';
