update content_bodies set title = 'なごやめしのうた', description = 'この動画は、名古屋の料理である「なごやめし」について紹介しています。名古屋の食文化や特有の料理を通じて、地域の魅力を伝える内容となっています。視聴者は、名古屋の代表的な料理やその特徴を知ることができ、食を通じて名古屋の文化に触れることができます。' where id = 'fXYjh0bf3qiSqEt0Jp-tC';
