update content_bodies set title = '南海＆沿線STORY 「ともに走る」（ダイジェスト版）', description = 'この動画は、南海＆沿線STORY「ともに走る」のダイジェスト版を紹介しています。南海電鉄とその沿線の魅力やストーリーを短くまとめた内容で、視聴者に南海の魅力を伝えることを目的としています。' where id = '74giU2G59ZLSdjgXoeFo_';
update content_bodies set title = 'Nankai & Line Story ''Running Together'' (Digest Version)', description = 'This video introduces the digest version of the Nankai & Line Story ''Running Together''.' where id = '9jT8lLKrJq9gJiYWwBPjP';
update content_bodies set title = '南海電鉄煉瓦造暗渠群を巡ろう！', description = 'この動画では、南海電鉄の煉瓦造暗渠群について詳しく紹介しています。煉瓦造の暗渠は、南海電鉄の歴史や技術を知る上で重要な遺産であり、地域の文化や景観にも深く関わっています。動画を通じて、これらの暗渠群の魅力や特徴を探求し、視聴者にその価値を伝えることを目的としています。' where id = 'Q-A-kUmeW-67aiQHH5Fdl';
update content_bodies set title = 'Let''s Explore the Nankai Electric Railway Brick Arched Tunnels!', description = 'This video introduces the brick arched tunnels of the Nankai Electric Railway.' where id = '19Omx73ryO4va2_TMLzH3';
update content_bodies set title = '「鉄道安全啓発」第３話「さちとの約束：歩きスマホ編」', description = '駅やホームでの歩きスマホは、周囲の人々に迷惑をかけるだけでなく、転落事故の危険性も伴います。そのため、ホームでは歩きスマホを控え、点字タイルの内側を歩くようにしましょう。皆様のご理解とご協力をお願い申し上げます。CVは中島由貴さんです。' where id = 'mPT5pCxVSSmN5cFKlhw_O';
update content_bodies set title = 'Railway Safety Awareness Episode 3: A Promise with Sachi - Smartphone Walking Edition', description = 'Using a smartphone while walking on the platform or in the station can disturb others and poses a risk of falling. Please refrain from using your smartphone on the platform and stay within the tactile paving. We appreciate your understanding and cooperation.' where id = '35mpeISLdqCBDsrBHDmEG';
update content_bodies set title = '「鉄道安全啓発」第2話「さちとの約束：踏切非常ボタン編」（CV.中島由貴）', description = 'この動画は「鉄道安全啓発」の第2話である「さちとの約束：踏切非常ボタン編」を紹介しています。声優は中島由貴さんが担当しています。' where id = 't2ZxP5Pq48t-PU6DFChLD';
update content_bodies set title = 'Railway Safety Awareness Episode 2: Sachi''s Promise - Emergency Button at the Level Crossing (CV: Yuki Nakajima)', description = 'This video introduces Episode 2 of ''Railway Safety Awareness,'' titled ''Sachi''s Promise: Emergency Button at the Level Crossing,'' featuring the voice of Yuki Nakajima.' where id = 'M6tplO32HZpG5vsmoYTxX';
update content_bodies set title = '安全啓発アニメーション第1弾 ～さちとの約束～（無理な踏切横断編）', description = 'このアニメは、大阪アニメーションカレッジ専門学校の学生の協力を得て制作されました。警報器が鳴ると踏切内に入ることが非常に危険であることを伝え、一旦立ち止まり安全を確認してから渡ることが重要です。鉄道の安全利用を呼びかけています。また、主人公の中松江幸の声は中島由貴さんが担当し、テーマソング「きみとでかけよう」も歌っています。視聴者が南海に親近感を持つことを願っています。' where id = 'pOYxw1VfL6k3jhzKGuHo5';
update content_bodies set title = 'Safety Awareness Animation Episode 1 - A Promise with Sachi (Dangerous Crossing at the Train Crossing)', description = 'This animation was created with the cooperation of students from Osaka Animation College. It emphasizes the dangers of entering a train crossing when the alarm sounds. Viewers are encouraged to stop and check for safety before crossing. The animation promotes safe use of railways. The main character, Nakamatue Sachi, is voiced by Yuki Nakajima, who also sings the theme song ''Let''s Go Out Together.'' The creators hope that viewers will feel a sense of familiarity with Nankai Railway.' where id = 'ogRlJ53PDzwdEOacwOJvo';
update content_bodies set title = '道の駅 美里「佐俣の湯」観光PR動画', description = 'このPR動画は、美里町を紹介し、心と体を癒す源泉掛け流しの温泉を備えた道の駅美里「佐俣の湯」を紹介しています。熊本県の国道218号線沿いに位置し、温泉施設のほか、地元農家が生産した加工農産物を販売する店舗、地元食材を使用したレストラン、ログハウス風の宿泊施設があります。また、訪れる人々に道路や観光情報を提供するために、屋外で利用できる公衆無線LAN設備や専用ウェブサイトを用意し、楽しい体験を提供することを目指しています。' where id = '_WpXL_P8fHo8G1m9P1Gbz';
update content_bodies set title = 'Roadside Station Misato ''Samata-no-Yu'' Tourism PR Video', description = 'This PR video promotes Misato Town and highlights the Roadside Station Misato ''Samata-no-Yu'', which features natural hot springs that provide relaxation for both mind and body. Located in Kumamoto Prefecture along National Route 218, the station offers a hot spring facility, a store selling local agricultural products, a restaurant using local ingredients, and log house-style accommodations. To assist visitors, the station provides outdoor public Wi-Fi and a dedicated website for road and tourist information, ensuring an enjoyable experience.' where id = '3BkacFQ_onXMfqdvcgUB_';
update content_bodies set title = 'テーマ曲「きみとでかけよう」', description = 'この動画では、テーマ曲「きみとでかけよう」について紹介しています。曲の内容や特徴、またその魅力について詳しく解説されており、視聴者にとって興味深い情報が提供されています。音楽の雰囲気や歌詞のテーマなど、さまざまな視点からこの曲を楽しむことができる内容となっています。' where id = 'wd_q6PUiCNX_meAJmKGa6';
update content_bodies set title = 'Theme Song ''Let''s Go Out Together''', description = 'This video introduces the theme song ''Let''s Go Out Together''.' where id = 'TFZlC4Z1T2YZmoOhxITJm';
update content_bodies set title = 'MEET-UP #BIZ TAG NANKAI 1st Talk Session：オープンファクトリーがもたらす効果', description = '「オープンファクトリー」は、作り手がものづくりの現場を公開し、一般のお客さまを含む様々な方に体験してもらう取り組みです。この活動は、企業プロモーションや他社とのビジネスチャンスの獲得に加え、人材育成にも寄与することが期待されています。関西におけるオープンファクトリーの推進者や実施企業が集まり、実際に開催した際のメリットや効果について意見を交わしました。登壇者には、株式会社ポートフォリオの延生康二氏、株式会社盛光SCMの草場寛子氏、株式会社小泉製作所の小泉達哉氏、近畿経済産業局の津田哲史氏が含まれています。' where id = 'fBYmgRz-KMBFhx-KxlP8x';
update content_bodies set title = 'MEET-UP #BIZ TAG NANKAI 1st Talk Session: Effects of Open Factory', description = 'The MEET-UP #BIZ TAG NANKAI 1st Talk Session focused on the concept of ''Open Factory,'' where manufacturers open their production sites to the public, allowing various participants, including general customers, to experience the manufacturing process. This initiative not only serves as a promotional tool for companies and a means to create business opportunities but also has potential benefits for human resource development. Key figures involved in the Open Factory movement in the Kansai region shared their experiences and discussed the advantages and effects gained from hosting such events.' where id = 'v7--dar_XiXUvL6JnpBKQ';
update content_bodies set title = 'MEET-UP #BIZ TAG NANKAI 2nd Talk Session：イノベーションを起こすための採用戦略', description = 'MEET-UP #BIZ TAG NANKAIの第2回トークセッションでは、イノベーションを促進するための採用戦略に焦点を当てました。採用活動が複雑化する中で、地方貢献を目的とした副業・兼業人材を活用するプラットフォームや、大学の講義の一環として行われるインターンシップを活用する企業が増加しています。これらの取り組みを行う各種団体と、実際に活用している企業が集まり、実施内容やその効果について意見を交わしました。登壇者には、桃山学院大学、ウェルグループ、大阪産業局、友安製作所の専門家が含まれています。このイベントは南海電気鉄道株式会社が主催しました。' where id = 'bKrEYzr7wH1CT10Qn2Nu1';
update content_bodies set title = 'MEET-UP #BIZ TAG NANKAI 2nd Talk Session: Recruitment Strategies for Innovation', description = 'The MEET-UP #BIZ TAG NANKAI 2nd Talk Session focused on recruitment strategies aimed at fostering innovation. As recruitment activities become increasingly complex, more companies are leveraging platforms that utilize part-time and concurrent workers for local contributions, as well as internships conducted as part of university courses. Various organizations involved in these initiatives and companies that are actively utilizing them discussed the implementation details and the effectiveness of these approaches. Speakers included professionals from Momoyama Gakuin University, Well Group, Osaka Industrial Bureau, and Tomoyasu Manufacturing Co., Ltd. The event was organized by Nankai Electric Railway Co., Ltd.' where id = 'BR79ly3rEbzKplwMURdU2';
update content_bodies set title = 'おかえりノムさん', description = '大阪球場跡地にノムさんが帰ってくる！「おかえり！ノムさん　大阪球場に。プロジェクト」が始動しました。このプロジェクトでは、なんばパークス９階にある南海ホークスメモリアルギャラリーにノムさんの功績を刻むことを目指しています。現在、クラウドファンディングサイト「CAMPFIRE」にて資金を募集中です！' where id = 'c1t7LJnrNklNg3ogpZV04';
update content_bodies set title = 'Welcome Back, Nomu-san', description = 'Nomu-san is returning to the site of the Osaka Stadium! The ''Welcome Back! Nomu-san to Osaka Stadium Project'' has begun. We aim to commemorate Nomu-san''s achievements at the Nankai Hawks Memorial Gallery on the 9th floor of Namba Parks. A crowdfunding campaign is currently underway on the CAMPFIRE platform!' where id = 'AcAoZBoOBpsI_PRpSqtXD';
update content_bodies set title = '南海タイムトラベル', description = 'この動画は南海タイムトラベルについて紹介しています。' where id = 'xkqiWMcTZw-WIB2mqUKbw';
update content_bodies set title = 'Nankai Time Travel', description = 'This video introduces Nankai Time Travel.' where id = '3BR9JZEbiclJswiM8U4Qf';
update content_bodies set title = '南海電鉄 鋼索線：4代目新型高野山ケーブルカー運行開始！！', description = '2019年3月1日、4代目となる新型高野山ケーブルカーが運行を開始しました。このケーブルカーのコンセプトは「期待感」「癒し・調和」「安全・安心」です。客車部分はスイスのキャビンメーカーが手掛け、欧州風の流線型のアルミ製車体に、高野山・壇上伽藍の根本大塔を想起させる朱色を採用し、和洋折衷のデザインで高野山への期待感を醸成しています。内装は木目調の装飾と調光式LEDの間接照明を用いて癒し・調和を演出。さらに、床面には滑りにくい材質を使用し、車内段差部には足元灯を設置することで、つまずきなどの事故防止対策を実施し、安全・安心を提供しています。' where id = '_aV2Fvjwe1vjQGhO_va2r';
update content_bodies set title = 'Nankai Electric Railway Cable Car: The 4th Generation New Koyasan Cable Car Begins Operation!!', description = 'On March 1, 2019, the 4th generation new Koyasan cable car commenced operations. The concept of the new cable car revolves around ''Expectations'', ''Healing and Harmony'', and ''Safety and Security''. The passenger cabin, designed by a Swiss manufacturer, features a European-style streamlined aluminum body painted in a vibrant red, reminiscent of the main pagoda at Koyasan''s Danjo Garan, creating a sense of anticipation for visitors. The interior is adorned with wood grain decorations and indirect lighting using dimmable LEDs to evoke a sense of healing and harmony. Additionally, safety measures include slip-resistant flooring and footlights at level changes to prevent accidents, ensuring a safe and secure experience for passengers.' where id = 'vUQHHM-xHu0A8Pwd4KrqL';
update content_bodies set title = '南海電鉄 鋼索線：新型高野山ケーブルカー運行開始！！', description = '2019年3月1日、4代目の新型高野山ケーブルカーが運行を開始します。このケーブルカーのコンセプトは「期待感」「癒し・調和」「安全・安心」です。客車はスイスのキャビンメーカーが手掛け、欧州風の流線型アルミ製車体に高野山の朱色を採用し、和洋折衷のデザインで期待感を醸成しています。内装は木目調の装飾と調光式LEDの間接照明を用いて癒しを演出。さらに、床面には滑りにくい材質を使用し、段差部には足元灯を設置することで、安全性を高めています。' where id = '4l_StAgriXoZVxwpymKVx';
update content_bodies set title = 'Nankai Electric Railway Cable Car: New Koyasan Cable Car Starts Operation!!', description = 'On March 1, 2019, the fourth-generation Koyasan Cable Car began operation. The concept of the new cable car focuses on ''Expectations'', ''Healing and Harmony'', and ''Safety and Security''. The passenger cars, designed by a Swiss cabin manufacturer, feature a European-style streamlined aluminum body painted in a vibrant red, reminiscent of the main pagoda at Koyasan''s Danjo Garan, creating a sense of anticipation for visitors. The interior is adorned with wood grain decorations and indirect lighting using dimmable LEDs to evoke a sense of healing and harmony. Additionally, safety measures include non-slip flooring and footlights at step areas to prevent accidents, ensuring a safe and secure experience for passengers.' where id = 'SEUMQLvCE9LJahgY9tGZM';
update content_bodies set title = '透明度抜群！御座白浜海水浴場でSUP（サップ）【伊勢志摩グランピング】LUXUNA伊勢志摩　マリンアクティビティ', description = 'SUP（サップ）は、腕の力がなくてもスイスイ漕げるため、初心者でも挑戦しやすいアクティビティです。大きく安定したボードでバランスを取りながら、三重県No.1の透明度を誇る御座白浜海水浴場の透き通った海の上で浮かぶ感覚を楽しむことができます。ふわふわとした感覚がとても気持ち良いです。この体験は、2021年7月にオープンした「ラグナ伊勢志摩LUXUNA」で提供されており、贅沢と自然を融合させた快適なグランピング施設です。豪華な食事や自然を楽しむアクティビティが充実しており、120分の体験料金は税込3,300円です。' where id = 'iSPFxXFPPK3WiWykGdaqp';
update content_bodies set title = 'Crystal Clear! SUP at Goza Shirahama Beach【Ise-Shima Glamping】LUXUNA Ise-Shima Marine Activities', description = 'SUP (Stand Up Paddleboarding) is an activity that is easy for beginners to try, as it allows for smooth paddling without requiring much arm strength. The large and stable board helps participants maintain balance while enjoying the sensation of floating on the clear waters of Goza Shirahama Beach, known for its top-notch transparency in Mie Prefecture. The experience is described as fluffy and very pleasant. The activity is offered at ''LAGUNA Ise-Shima LUXUNA,'' a glamping facility that opened in July 2021, combining luxury and nature. The facility provides comfortable accommodations, gourmet meals, and a variety of activities to enjoy the surrounding nature. The cost for a 120-minute session is 3,300 yen per person, including tax.' where id = 'vQ2r1QMbl_oeQuWFmIJ9t';
update content_bodies set title = '祇園から三条まで、ポント町を経由した京都の夜の散歩 | 4K', description = '京都は夜になるとさらに美しくなります。この動画を見ることで、その魅力を理解することができます。' where id = '7bo0qUQiKDyem7t1YVjEi';
update content_bodies set title = 'Night Walk in Kyoto, From Gion to Sanjo via Ponto-Cho | 4K', description = 'Kyoto''s beauty is enhanced at night, and this video showcases that allure. By watching, viewers can appreciate the nighttime charm of the city.' where id = 'sJvK-HmuXcwdcVTkbh_z2';
update content_bodies set title = '南海電鉄 鋼索線：高野山ケーブルカー', description = '高野山ケーブルカーは、高野線の終着駅である極楽橋駅と真言密教の聖地高野山の玄関口である高野山駅を結ぶ路線です。法律上は「鋼索鉄道」とされ、当社では『鋼索線』と呼ばれています。1930年に開通し、国内でも有数の歴史を持ち、高野山への参拝客や住民の交通手段として重要な役割を果たしています。全長0.8Km、高低差328mを約5分で昇り、東京タワーとほぼ同じ高さに達します。' where id = 'rziwH1-YrVn2-Lz2xDhTX';
update content_bodies set title = 'Nankai Electric Railway: Koyasan Cable Car', description = 'The Koyasan Cable Car connects Gokurakubashi Station, the terminus of the Koyasan Line, with Koyasan Station, the gateway to the sacred site of Shingon Buddhism, Koyasan. Legally classified as a ''cable railway,'' it is referred to as ''Kousakusen'' by the company. Opened in 1930, it boasts a rich history and serves not only as a means of transportation for visitors to Koyasan but also for residents living in the area. The cable car covers a distance of 0.8 km with an elevation difference of 328 meters, ascending to a height comparable to that of Tokyo Tower in approximately five minutes.' where id = 'JTwpUR7um_aXpuyCKT2M4';
update content_bodies set title = 'なんばEKIKAN プロモーションムービー2018', description = '南海なんば駅の南側に位置する高架下商業ゾーン「なんばEKIKAN」のプロモーションムービーです。このムービーは、なんばEKIKANの魅力を伝えるために制作されました。詳細については、公式ウェブサイト（http://ekikan.com）をご覧ください。' where id = 'pxEAUexCU5fSWliMwkiAs';
update content_bodies set title = 'Namba EKIKAN Promotional Movie 2018', description = 'This is a promotional movie for the commercial zone ''Namba EKIKAN'' located under the elevated area on the south side of Nankai Namba Station. For more information, visit the official Namba EKIKAN website at http://ekikan.com.' where id = 'jqjds7LZ_Ehkfpwha8Ck7';
